  const _friendMvp = {};  // okey -> seq (o.mvps) ล่าสุด — กันเด้ง "MVP" เหนือหัวเพื่อนซ้ำ (presence ค้าง ~1s)
  const _friendLvup = {}; // okey -> seq (o.lvups) ล่าสุด — กันเด้ง "LV UP" เหนือหัวเพื่อนซ้ำ
