  let _pFace = -Math.PI / 2, _pPrev = null, _pMuzzleUntil = 0; // ฮีโร่: ทิศหัน, ตำแหน่งก่อนหน้า, muzzle
  let _rAtkUntil = 0; // ไททัน: เล่นท่าโจมตี (robot_attack) จนถึงเวลานี้

