        const dx = CX + Math.cos(ang) * rr, dy = BASE + 70 + Math.sin(ang) * rr * 0.42;
        if (dy < BASE + 26 || Math.abs(dx - CX) < 46 * SC) continue; // ไม่วางทับตัวปราสาท/ทางเดินเข้า
        const ds = (1.0 + rnd() * 0.6) * SC;                         // เล็กกว่าตัวละคร (ของประดับ ไม่ใช่อาคาร)
