      const fi = Math.floor((Date.now() + 800) / 120) % frames, sz = 93 * scale; // +800ms เฟส Anubis (🎲 desync) · ×1.5 จาก 62 (เจ้าของสั่ง 2026-07-23)
      ctx.save(); ctx.imageSmoothingEnabled = false; ctx.translate(s.x, s.y);
