  function _pvpHideMons() { const ph = player && player.pvp && player.pvp.ph; return ph === 'run' || ph === 'count' || ph === 'fight'; } // ⚔️ ระหว่างดวล: ซ่อนมอนทั้งหมด (ลายตา — server กันมอนยุ่งอยู่แล้ว จบดวลโผล่กลับทันที)
