  function setGunTab(t){ gunTab = t; renderGuns(); }
  function upgradeArmor(){
    $.post(baseUrl+'xhrpg_upgrade.php',{line_uid:player.line_uid,action:'upgrade_armor'}).done(res=>{
      const d=typeof res==='string'?JSON.parse(res):res;
      if(d.ok){ player=d.player; renderGuns(); updateHUD(); addLog([{type:'levelup',msg:d.msg}]); } else addLog([{type:'dead',msg:d.error||T('อัพเกรดเกราะไม่ได้')}]);
    });
  }

  function tcCard(item, owned, qty) {
    const r = item.rarity || 'white';
    const badge = qty > 0 ? `<div class="tc-qty">x${qty+1}</div>` : '';
    if (owned) {
      return `<div class="treasure-card owned rarity-${r}" title="${T(item.desc)}">
        ${badge}
        <div class="tc-rarity"></div>
        <div class="tc-icon">${_icoHtml(item.icon, 16)}</div>
        <div class="tc-name">${T(item.name)}</div>
        <div class="tc-desc">${T(item.desc)}</div>
      </div>`;
    }
    return `<div class="treasure-card locked rarity-${r}">
      <div class="tc-rarity"></div>
      <div class="tc-icon">🔒</div>
      <div class="tc-name">???</div>
      <div class="tc-desc">${T('ยังไม่ค้นพบ')}</div>
    </div>`;
  }

  // รวมของสะสมทุกหมวดมาแสดงในเมนู ITEM ที่เดียว (display-only — logic apply effect คงเดิม)
  function _collectGrid(icon, title, master, ownedRaw, qtyRaw) {
    const owned = Array.isArray(ownedRaw) ? ownedRaw : JSON.parse(ownedRaw || '[]');
    const q     = decodeQty(qtyRaw);
    const cards = master.map(it => tcCard(it, owned.includes(it.id), q[it.id] || 0)).join('');
    return `<div class="treasure-panel" style="margin-top:10px">
      <div class="treasure-header">${icon} ${T(title)} <span class="treasure-count">${owned.length}/${master.length}</span></div>
      <div class="treasure-grid">${cards}</div>
    </div>`;
  }

  function decodeQty(v) {
    if (!v) return {};
    try { return typeof v === 'object' ? v : JSON.parse(v); } catch(e) { return {}; }
  }

