  const RARITY_BG    = { white:'#f9fafb',  green:'#f0fdf4',  blue:'#eff6ff',  purple:'#faf5ff',  gold:'#fffbeb',  red:'#fff1f2'  };
  const RARITY_BORDER= { white:'#d1d5db',  green:'#4ade80',  blue:'#60a5fa',  purple:'#a78bfa',  gold:'#fbbf24',  red:'#f87171'  };
  const RARITY_TEXT  = { white:'#4b5563',  green:'#15803d',  blue:'#1d4ed8',  purple:'#7c3aed',  gold:'#b45309',  red:'#dc2626'  };

  function renderEquipment() {
    const master = player._equipmentMaster;
    if (!master) return '';
    const eqOwned = (() => { const e = player.equipment; return (e && typeof e === 'object' && !Array.isArray(e)) ? e : (typeof e === 'string' ? JSON.parse(e || '{}') : {}); })();
    const SLOTS = ['head','body','hand','foot','ring','necklace'];
    const STAT_LABEL = { intel:'INT', vit:'VIT', dex:'DEX', agi:'AGI', str:'STR', luk:'LUK' };
    const eqQty = (() => { const q = player._equipmentQty; return (q && typeof q === 'object') ? q : {}; })();
    let cards = SLOTS.map(slot => {
      const def    = master[slot]; if (!def) return '';
      const tiers  = Array.isArray(eqOwned[slot]) ? eqOwned[slot] : [];
      const total  = tiers.reduce((s,t) => s+t, 0);
      const stat   = STAT_LABEL[def.stat] || def.stat.toUpperCase();
      const dupQty = eqQty[slot] ? parseInt(eqQty[slot]) : 0;
      const pips   = [1,2,3,4,5,6].map(t => {
        const have    = tiers.includes(t);
        const tDef    = def.tiers[t];
        const bg      = have ? RARITY_BG[tDef.rarity]     : '#f3f4f6';
        const border  = have ? RARITY_BORDER[tDef.rarity]  : '#94a3b8';
        const color   = have ? RARITY_TEXT[tDef.rarity]    : '#6b7280';
        const icon    = have ? tDef.icon : '🔒';
        const opacity = have ? '1' : '0.55';
        const tierDup = (eqQty[slot] && typeof eqQty[slot] === 'object') ? (parseInt(eqQty[slot][t]) || 0) : 0;
        const badge   = (have && tierDup > 0)
          ? `<span style="position:absolute;top:-5px;right:-5px;background:#ef4444;color:#fff;font-size:10px;font-weight:700;border-radius:999px;padding:0 4px;line-height:14px;z-index:1">x${tierDup}</span>`
          : '';
        return `<div title="${have ? tDef.name : '???'}" style="position:relative;width:100%;box-sizing:border-box;height:34px;border-radius:5px;border:1.5px solid ${border};background:${bg};opacity:${opacity};display:flex;flex-direction:column;align-items:center;justify-content:center;font-size:16px;gap:1px">
          ${badge}<span>${_icoHtml(icon, 16)}</span>
          <span style="font-size:9px;color:${color};line-height:1">+${t}</span>
        </div>`;
      }).join('');
      return `<div style="background:#fff;border:1px solid #94a3b8;border-radius:8px;padding:8px 10px;margin-bottom:6px">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">
          <span style="font-size:12px;color:#4b5563">${def.label}</span>
          <span style="font-size:13px;font-weight:600;color:#374151">${stat} +${total}</span>
        </div>
        <div style="display:grid;grid-template-columns:repeat(6,1fr);gap:4px">${pips}</div>
      </div>`;
    }).join('');
    const totalSlots = SLOTS.length * 6;
    const gotSlots   = SLOTS.reduce((s,sl) => s + (Array.isArray(eqOwned[sl]) ? eqOwned[sl].length : 0), 0);
    // 🏺 หัวข้อ "ของโบราณ" + เปลี่ยนชื่อแผงเป็น Old King Equipment (เจ้าของ 2026-07-19 — จองคำว่า Equipment ไว้ให้ระบบคราฟต์ของสวมใส่ใหม่ในอนาคต ไม่ให้ชื่อทับกัน)
    return `<div style="font-size:13px;font-weight:800;color:#78350f;margin-top:12px;padding:0 2px">🏺 ${T('ของโบราณ')}</div>
    <div class="treasure-panel" style="margin-top:4px">
      <div class="treasure-header">🗃️ Old King Equipment <span class="treasure-count">${gotSlots}/${totalSlots}</span></div>
      <div style="padding:4px 0">${cards}</div>
    </div>`;
  }

  function _renderPotionTierGrid(lv, vit) {
    const mask    = _potionEnabledMask();
    const activeT = _potionActiveT();
    let html = `<div style="background:#fff8ed;display:grid;grid-template-columns:repeat(6,1fr);gap:3px;padding:5px 8px 6px">`;
    for (let t = 1; t <= 6; t++) {
      const unlock   = POTION_TIER_UNLOCK_LV[t-1];
      const locked   = lv < unlock;
      const enabled  = !!(mask & (1 << (t-1)));
      const stock    = _potionStock(t);
      const cap      = _potionCarryCap(t-1, vit);
      const isActive = activeT.tier === t;
      const bg       = locked ? '#fafaf9' : (enabled ? '#fef3c7' : '#fafaf9');
      const border   = isActive ? '#f59e0b' : (enabled ? '#fbbf24' : '#e7e5e4');
      const op       = locked ? 0.5 : 1;
      const iconClr  = locked ? '#a8a29e' : (enabled ? '#92400e' : '#57534e');
      const numClr   = !locked && stock > cap ? '#dc2626' : (locked ? '#a8a29e' : (enabled ? '#78350f' : '#57534e'));
      const onclick  = locked ? '' : `xhrpg.togglePotionTier(${t},${enabled?0:1})`;
      const bottom   = locked
        ? `<div style="font-size:8px;color:#a8a29e">Lv.${unlock}</div>`
        : `<button style="font-size:8.5px;padding:1px 0;width:100%;border-radius:3px;border:none;font-weight:500;${enabled?'background:#16a34a;color:#fff':'background:#e7e5e4;color:#57534e'};cursor:pointer" onclick="${onclick}">${enabled?T('เปิด'):T('ปิด')}</button>`;
      html += `<div title="${locked ? T('ปลดล็อก Lv.{a}', {a: unlock}) : (T('+{a} HP · จุ {b} ขวด', {a: POTION_TIER_HEAL[t-1], b: cap})+(isActive?T(' · ใช้อยู่'):''))}" style="background:${bg};border:${isActive?'1.5px':'1px'} solid ${border};border-radius:6px;padding:4px 2px;text-align:center;opacity:${op}">
        <div style="font-size:9px;color:${iconClr};margin-bottom:1px;white-space:nowrap">${_icoPotionHtml(t, 12)}T${t}</div>
        <div style="font-size:12px;font-weight:500;color:${numClr};margin-bottom:2px">${locked ? '🔒' : stock}</div>
        ${bottom}
      </div>`;
    }
    html += `</div>`;
    return html;
  }

  // 🎴 สมุดสะสมการ์ด — มอนทุกตัว (จาก monMasters) มี 2 ช่อง: ปกติ + MVP · ค่า = ceil(Lv/20)×(MVP?3:1)
  const _CARD_STAT_CLR = { str:'#ef4444', agi:'#22c55e', vit:'#f59e0b', dex:'#06b6d4', intel:'#a855f7', luk:'#eab308' };
  const _CARD_STAT_LBL = { str:'STR', agi:'AGI', vit:'VIT', dex:'DEX', intel:'INT', luk:'LUK' }; // แสดง INT (ไม่ใช่ INTEL)
  function _cardValue(lv, mvp) { return Math.ceil(Math.max(1, lv|0) / 10) * (mvp ? 3 : 1); } // ทุก 10 Lv +1 · ปกติ ×1 · MVP ×3 (sync server)
  // โบนัสสะสม: นับ "ชนิด" (n>0 นับ 1 · m>0 นับ 1) ของ obj การ์ด/ไข่ — sync server xhrpg_*_collection_count
  function _collCount(obj) { const o=(obj&&typeof obj==='object'&&!Array.isArray(obj))?obj:(()=>{try{return JSON.parse(obj||'{}')||{};}catch(e){return {};}})(); let n=0; for(const k in o){ const v=o[k]; if(v&&((v.n|0)>0))n++; if(v&&((v.m|0)>0))n++; } return n; }
  function _collStatBonus() { return _collCount(player&&player.cards) + _collCount(player&&player.eggs); } // +N ทุก STAT (การ์ด + ไข่)
  // combat bonus การ์ด MVP (mirror xhrpg_mvp_card_bonus PHP): ชนิดจาก monster_id%12 · 6 STAT+ATK=ceil(lv/10) · เกราะ=ceil(lv/10)×10 · HP/MP=lv×10 · regen=lv/10
  const _MVP_CB_TYPES = ['str','agi','vit','dex','intel','luk','atk','armor','hp','mp','hp_regen','mp_regen'];
  function _mvpCardBonus(mid, lv) {
    lv = Math.max(1, lv|0);
    const t = _MVP_CB_TYPES[Math.abs(mid|0) % 12];
    let a;
    if (t==='hp'||t==='mp') a = Math.round(lv*30/4);                      // HP/MP = (×3)÷4 · แบบอื่น ×3 (sync server 2026-07-15)
    else if (t==='armor') a = Math.ceil(lv/10)*30;
    else if (t==='hp_regen'||t==='mp_regen') a = Math.max(1, Math.floor(lv/10))*3;
    else a = Math.ceil(lv/10)*3;
    return { t, a };
  }
  // sprite มอนจริงบนแมพ (crop เฟรมหน้า col0/row0 จากชีทตาม MON_ANIM) → CSS background · fallback emoji
  function _monSpriteBg(lv) {
    const sk = MON_ANIM[lv|0], sheet = sk ? SUM[sk] : null;
    if (sheet && sheet.src && sheet.naturalWidth) { const g = MON_GRID[sk] || _MON_GRID_DEF; return { url: sheet.src, cols: g.cols, rows: g.rows }; }
    const lc = Math.max(1, Math.min(9, lv|0)), st = SUM['mon' + lc];
    if (st && st.src && st.naturalWidth) return { url: st.src, cols: 1, rows: 1 };
    return null;
  }
  const _CARD_MVP_EXCHANGE_N = 100; // sync XHRPG_CARD_MVP_EXCHANGE_N — สะสมการ์ดปกติ N ใบ/มอน → แลก MVP 1 ใบ
  // 🎴 แถบความคืบหน้า + ปุ่ม "แลก" ใต้ช่อง MVP (cnt = จำนวนการ์ดปกติของมอนนี้) — ปุ่มกดได้ตลอด · ครบ=เขียว ไม่ครบ=แดง
  function _cardExchStrip(mid, cnt) {
    const N = _CARD_MVP_EXCHANGE_N, ready = cnt >= N, pct = Math.min(100, Math.round(cnt / N * 100));
    return `<div style="width:100%;margin-top:3px">
      <div style="height:5px;border-radius:3px;background:#fde0e0;overflow:hidden"><div style="height:100%;width:${pct}%;background:${ready ? '#16a34a' : '#f59e0b'}"></div></div>
      <div style="font-size:8.5px;font-weight:700;text-align:center;margin-top:1px;color:${ready ? '#16a34a' : '#b45309'}">${cnt}/${N}${ready ? ' ✓' : ''}</div>
      <button onclick="event.stopPropagation();xhrpg.cardMvpExchange(${mid})" style="width:100%;margin-top:4px;padding:3px 0;border:none;border-radius:6px;background:${ready ? '#16a34a' : '#dc2626'};color:#fff;font-size:9.5px;font-weight:800;cursor:pointer;line-height:1.4">${T('🔄 แลก')}</button>
    </div>`;
  }
  // กดปุ่มแลกที่การ์ด MVP → popup: ครบ=ยืนยันแลก · ไม่ครบ=แจ้งมี/ขาดกี่ใบ (server verify ยอดจริงกัน hack อีกชั้น)
  function cardMvpExchange(mid) {
    const cards = (player && player.cards && typeof player.cards === 'object' && !Array.isArray(player.cards)) ? player.cards
                : (() => { try { return JSON.parse((player && player.cards) || '{}') || {}; } catch (e) { return {}; } })();
    const own = cards[mid] || {}, nN = own.n | 0, N = _CARD_MVP_EXCHANGE_N;
    const mm = monMasters[mid] || {}, nm = T(mm.n || '');
    const ready = nN >= N, left = nN - N, short = N - nN, pct = Math.min(100, Math.round(nN / N * 100));
    const sb = _monSpriteBg(mm.lv || 1), D = 30;
    const artHtml = sb
      ? `<div style="width:${D}px;height:${D}px;margin:0 auto;background:url('${sb.url}') 0 0/${sb.cols * D}px ${sb.rows * D}px no-repeat;image-rendering:pixelated"></div>`
      : `<div style="font-size:26px;line-height:1">${mm.e || '👾'}</div>`;
    // แถบความคืบหน้าในป๊อปอัป (โชว์ทั้ง 2 สถานะ)
    const barHtml = `<div style="margin:2px 0 10px">
      <div style="height:8px;border-radius:4px;background:#f1f5f9;overflow:hidden"><div style="height:100%;width:${pct}%;background:${ready ? '#16a34a' : '#f59e0b'}"></div></div>
      <div style="font-size:11px;font-weight:700;text-align:center;margin-top:3px;color:${ready ? '#16a34a' : '#b45309'}">${nN}/${N}${ready ? ' ✓' : ''}</div></div>`;
    const body = ready
      ? `<div style="display:flex;align-items:center;justify-content:center;gap:10px;margin:2px 0 10px">
          <div style="text-align:center">${artHtml}<div style="font-size:11px;font-weight:700;margin-top:2px;color:#334155">${nm} ×${N}</div><div style="font-size:9.5px;color:#94a3b8">${T('การ์ดปกติ')}</div></div>
          <div style="font-size:20px;color:#94a3b8">➜</div>
          <div style="text-align:center">${artHtml}<div style="font-size:11px;font-weight:700;margin-top:2px;color:#dc2626">${T('⭐MVP')} ×1</div></div>
        </div>
        ${barHtml}
        <div style="background:#fffbeb;border:1px solid #fde68a;border-radius:9px;padding:7px 9px;font-size:11px;color:#92400e;text-align:center;line-height:1.5;margin-bottom:12px">${T('ใช้การ์ดปกติ {a} ใบ → เหลือ {b} ใบ', {a: N, b: left})}</div>
        <div style="display:flex;gap:8px">
          <button onclick="xhrpg._cardMvpExClose()" style="flex:1;padding:9px 0;border:none;border-radius:9px;background:#e2e8f0;color:#475569;font-size:12.5px;font-weight:700;cursor:pointer">${T('ยกเลิก')}</button>
          <button onclick="xhrpg._cardMvpExGo(${mid})" style="flex:1;padding:9px 0;border:none;border-radius:9px;background:#dc2626;color:#fff;font-size:12.5px;font-weight:700;cursor:pointer">${T('✅ แลกเลย')}</button>
        </div>`
      : `<div style="text-align:center;margin:2px 0 8px">${artHtml}<div style="font-size:12px;font-weight:700;margin-top:3px;color:#334155">${nm}</div></div>
        ${barHtml}
        <div style="background:#fef2f2;border:1px solid #fecaca;border-radius:9px;padding:8px 9px;font-size:11.5px;color:#b91c1c;text-align:center;line-height:1.6;margin-bottom:12px">${T('ยังแลกไม่ได้ — ต้องสะสมให้ครบ {a} ใบก่อน', {a: N})}<br><b style="font-size:13px">${T('มี {a} ใบ · ขาดอีก {b} ใบ', {a: nN, b: short})}</b></div>
        <button onclick="xhrpg._cardMvpExClose()" style="width:100%;padding:9px 0;border:none;border-radius:9px;background:#dc2626;color:#fff;font-size:12.5px;font-weight:700;cursor:pointer">${T('เข้าใจแล้ว')}</button>`;
    const el = document.createElement('div');
    el.id = 'card-mvpex-modal';
    el.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,.55);z-index:10004;display:flex;align-items:center;justify-content:center;padding:16px';
    el.innerHTML = `<div style="background:#fff;border-radius:16px;width:280px;max-width:100%;overflow:hidden;box-shadow:0 12px 40px rgba(2,8,23,.35)">
      <div style="background:#dc2626;color:#fff;padding:14px 16px 12px;text-align:center">
        <div style="font-size:30px;line-height:1">🔄</div><div style="font-size:15px;font-weight:800;margin-top:4px">${T('แลกการ์ด ⭐MVP')}</div></div>
      <div style="padding:14px 16px 16px">${body}</div></div>`;
    el.addEventListener('click', e => { if (e.target === el) _cardMvpExClose(); });
    document.body.appendChild(el);
  }
  function _cardMvpExClose() { const el = document.getElementById('card-mvpex-modal'); if (el) el.remove(); }
  function _cardMvpExGo(mid) {
    _cardMvpExClose();
    $.post(baseUrl + 'xhrpg_upgrade.php', {line_uid: player.line_uid, action: 'card_mvp_exchange', mid, lang: LANG(), session_token: sessionToken || ''}).done(res => {
      const d = typeof res === 'string' ? JSON.parse(res) : res;
      if (d.ok) { player = d.player; renderCard(); updateHUD(); addLog([{type:'levelup', msg: d.msg}]); }
      else addLog([{type:'dead', msg: d.error || T('แลกการ์ดไม่สำเร็จ')}]);
    }).fail(() => addLog([{type:'dead', msg: T('แลกการ์ดไม่สำเร็จ')}]));
  }

  // 🎴 ตัวกรองสมุดการ์ด (docs/card-book-filter-design.md · เจ้าของสั่ง 2026-08-09)
  //    stat = STAT หลักของการ์ด (mm.cs) · cb = ชนิดโบนัสคอมแบตของการ์ด MVP (_mvpCardBonus().t)
  //    ⚠️ เก็บในตัวแปรฝั่ง client เท่านั้น ไม่ลง localStorage — ปิดแผงแล้วกลับเป็น "ทั้งหมด"
  //       ถ้าจำข้ามวัน ผู้เล่นจะเปิดสมุดมาเห็นการ์ดไม่กี่ใบแล้วนึกว่าการ์ดหาย
  let _cbFilter = { stat: '', cb: '' };
  function _cbSetStat(s) { _cbFilter.stat = (_cbFilter.stat === s) ? '' : s; renderCard(); }
  function _cbSetCB(v)   { _cbFilter.cb = v || ''; renderCard(); }
  function _renderCardBook() {
    const cards = (player.cards && typeof player.cards === 'object' && !Array.isArray(player.cards)) ? player.cards
                : (() => { try { return JSON.parse(player.cards || '{}') || {}; } catch (e) { return {}; } })();
    const ids = Object.keys(monMasters).sort((a, b) => ((monMasters[a].lv || 0) - (monMasters[b].lv || 0)) || (+a - +b));
    if (!ids.length) return ''; // ยังไม่ได้รับตารางมอน (have_static)
    let ownN = 0, ownM = 0, cells = '';
    const cell = (mm, mvp, cnt, id) => {
      const st = (mm.cs || '').toLowerCase(), clr = _CARD_STAT_CLR[st] || '#94a3b8', su = _CARD_STAT_LBL[st] || '?';
      const has = cnt > 0, D = mvp ? 44 : 34; // MVP รูปใหญ่กว่า — แต่อยู่ในกล่อง art สูงคงที่ (ทุกใบระนาบตรงกัน)
      const sb = _monSpriteBg(mm.lv || 1);
      const art = sb
        ? `<div style="width:${D}px;height:${D}px;background:url('${sb.url}') 0 0/${sb.cols * D}px ${sb.rows * D}px no-repeat;image-rendering:pixelated;${has ? '' : 'filter:grayscale(1);opacity:.5'}"></div>`
        : `<div style="font-size:${mvp ? 26 : 22}px;line-height:1;${has ? '' : 'filter:grayscale(1);opacity:.5'}">${mm.e || '👾'}</div>`;
      return `<div style="border:${mvp ? '1.5px' : '1px'} solid ${has ? (mvp ? '#dc2626' : clr) : '#e5e7eb'};border-radius:9px;padding:5px 3px 6px;background:${has ? (mvp ? '#fef2f2' : '#fff') : '#f8fafc'};opacity:${(has || mvp) ? 1 : 0.6};position:relative;display:flex;flex-direction:column;align-items:center">
        ${mvp ? `<span style="position:absolute;top:3px;left:4px;font-size:8px;font-weight:800;color:#fff;background:#dc2626;padding:0 4px;border-radius:4px">MVP</span>` : ''}
        ${_sacBadge(+id, mm.lv || 1, mvp)}
        <span style="position:absolute;top:3px;right:4px;font-size:8px;font-weight:700;color:#64748b;background:#eef2f7;padding:0 3px;border-radius:4px">Lv.${mm.lv || 1}</span>
        ${cnt > 1 ? `<span style="position:absolute;top:16px;right:5px;font-size:9px;font-weight:700;color:${mvp ? '#dc2626' : clr}">×${cnt}</span>` : ''}
        <div style="height:48px;display:flex;align-items:center;justify-content:center">${art}</div>
        <div style="width:100%;height:12px;line-height:12px;font-size:9.5px;color:${mvp ? '#b91c1c' : '#475569'};white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-align:center">${T(mm.n || '')}</div>
        <div style="height:14px;line-height:14px;font-size:10px;font-weight:700;color:${clr};margin-top:2px">+${_cardValue(mm.lv || 1, mvp)} ${su}${_sacPlus(+id, mm.lv || 1)}</div>
        ${mvp ? ((()=>{ const b=_mvpCardBonus(+id, mm.lv||1); return b.a>0 ? `<div style="height:12px;line-height:12px;font-size:8.5px;font-weight:700;color:#7c3aed" title="${T('โบนัสคอมแบต (เฉพาะการ์ด MVP เมื่อเสียบในโมดูล)')}">+${b.a} ${_CB_LBL[b.t]||b.t}</div>` : '';})() + _cardExchStrip(+id, (cards[id]||{}).n|0)) : ''}</div>`;
    };
    let shownN = 0, totalN = 0;
    ids.forEach(id => {
      const mm = monMasters[id], own = cards[id] || {}, nN = own.n | 0, nM = own.m | 0;
      // ⚠️ นับ ownN/ownM ให้ครบ "ก่อน" กรอง — โบนัสสะสมเป็นค่าจริงในเกม ห้ามขยับตามตัวกรอง
      if (nN > 0) ownN++; if (nM > 0) ownM++;
      totalN += 2;
      // 🔎 การ์ด 1 ใบมี STAT ได้ 2 ชั้น — ใบปกติมีแต่ STAT หลัก · ใบ MVP มีโบนัสคอมแบตอีกชั้น
      //    และโบนัสนั้น "เป็น STAT ตัวไหนก็ได้" (เช่น หลัก AGI แต่โบนัส +VIT)
      //    ⇒ กด VIT ต้องเห็นใบที่ VIT อยู่ชั้นไหนก็ได้ (เจ้าของทักไว้ 2026-08-10)
      const cs = (mm.cs || '').toLowerCase(), cbT = _mvpCardBonus(+id, mm.lv || 1).t;
      const wS = _cbFilter.stat, wB = _cbFilter.cb;
      let okN = !wS || cs === wS;                 // ใบปกติ: ดูแค่ STAT หลัก
      let okM = !wS || cs === wS || cbT === wS;   // ใบ MVP: STAT หลัก "หรือ" โบนัสก็นับ
      if (wB) { okN = false; okM = okM && cbT === wB; } // เลือกโบนัส MVP = ใบปกติไม่มีทางเข้าเงื่อนไข
      if (okN) { cells += cell(mm, false, nN, id); shownN++; }
      if (okM) { cells += cell(mm, true,  nM, id); shownN++; }
    });
    const _CB_PICK = ['atk', 'armor', 'hp', 'mp', 'hp_regen', 'mp_regen']; // 6 ชนิดที่ไม่ซ้ำกับปุ่ม STAT
    const _statBtn = (s, lbl) => {
      const on = _cbFilter.stat === s, c = _CARD_STAT_CLR[s] || '#64748b';
      return `<button onclick="xhrpg._cbSetStat('${s}')" style="flex:1 1 0;min-width:0;padding:3px 0;border-radius:7px;cursor:pointer;font-size:10px;font-weight:800;
        border:${on ? '1.5px solid ' + c : '1px solid #e2e8f0'};background:${on ? c + '1a' : '#fff'};color:${on ? c : '#64748b'}">${lbl}</button>`;
    };
    const _filterBar = `<div style="display:flex;gap:3px;margin:5px 0 3px">
        ${_statBtn('', T('ทั้งหมด'))}${['str','agi','vit','dex','intel','luk'].map(s => _statBtn(s, _CARD_STAT_LBL[s] || s)).join('')}
      </div>
      <div style="display:flex;align-items:center;gap:6px;margin-bottom:4px">
        <span style="flex:none;font-size:10px;color:#64748b;font-weight:600">${T('โบนัส MVP')}</span>
        <select onchange="xhrpg._cbSetCB(this.value)" style="flex:1;min-width:0;padding:3px 6px;border:1px solid #e2e8f0;border-radius:7px;font-size:10.5px;background:#fff;color:#334155">
          <option value=""${_cbFilter.cb ? '' : ' selected'}>${T('ทั้งหมด')}</option>
          ${_CB_PICK.map(k => `<option value="${k}"${_cbFilter.cb === k ? ' selected' : ''}>${T(_CB_LBL[k] || k)}</option>`).join('')}
        </select>
        <span style="flex:none;font-size:9.5px;color:#94a3b8">${T('แสดง {a}/{b} ใบ', {a: shownN, b: totalN})}</span>
      </div>`;
    const _collB = ownN * 1 + ownM * 3; // ✨ โบนัสสะสม → ATK/DEF/HP/MP · ปกติ +1 · MVP +3 (sync xhrpg_collection_cb)
    return `<div class="treasure-panel" style="margin-top:4px;border-top:none;padding-top:0">
      <div class="treasure-header">${T('🎴 สมุดสะสมการ์ด')} <span class="treasure-count">${ownN}/${ids.length} · MVP ${ownM}/${ids.length}</span></div>
      <div style="font-size:11px;color:#b91c1c;text-align:center;font-weight:600;margin:3px 0 1px">${T('🔄 การ์ดปกติ {a} ใบ = การ์ด ⭐MVP 1 ใบ', {a: _CARD_MVP_EXCHANGE_N})} <span style="font-weight:400;color:#94a3b8">· ${T('กดปุ่มแลกที่การ์ด MVP')}</span></div>
      ${_collB > 0 ? `<div style="background:#ede9fe;border:1px solid #7c3aed;border-radius:9px;padding:7px 10px;margin:4px 0 2px;font-size:12.5px;color:#5b21b6;text-align:center;font-weight:700">${T('✨ โบนัสสะสมการ์ด:')} <b style="color:#7c3aed;font-size:14px">+${_collB}</b> ${T('ทั้ง ATK/DEF/HP/MP')} <span style="font-size:10px;font-weight:500;color:#7c3aed">${T('(ปกติ {n} · MVP {m})', {n: ownN, m: ownM})}</span></div>` : ''}
      ${_filterBar}
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(70px,1fr));gap:5px;padding:5px 0">${cells || `<div style="grid-column:1/-1;text-align:center;color:#a8a29e;font-size:11px;padding:14px 0">${T('ไม่มีการ์ดที่ตรงเงื่อนไข')}</div>`}</div>
    </div>`;
  }

  // ── การ์ดในรูโมดูล (Phase 2) — เสียบถาวร / ถอดเสีย P ────────────────────────────
  // 🎴🔎 ตัวกรอง "หน้าเลือกการ์ดเสียบ" — ใช้ร่วม 3 ที่: โมดูล · สัตว์เลี้ยง · Anubis (เจ้าของสั่ง 2026-08-10)
  //    ตรรกะการจับคู่ยกมาจากสมุดการ์ดทั้งดุ้น (docs/card-book-filter-design.md) — ต้องเหมือนกันเป๊ะ
  //    ไม่งั้นกรอง VIT ในสมุดเห็นใบนึง แต่กรอง VIT ตอนจะเสียบไม่เห็น = ผู้เล่นนึกว่าการ์ดหาย
  //    ⚠️ รีเซ็ตทุกครั้งที่เปิดหน้าเลือก (ไม่ค้างข้ามครั้ง ไม่ลง localStorage) — เหตุผลเดียวกับสมุดการ์ด
  //    ctx บอกวิธีเรนเดอร์ใหม่: 'mod' = แผงในหน้าโมดูล · 'dv' = แผงในหน้าสัตว์เทพ · 'pet' = overlay ลอย (ต้องสร้างใหม่)
  let _cpFilter = { stat: '', cb: '' };
  function _cpReset() { _cpFilter = { stat: '', cb: '' }; }
  function _cpRedraw(ctx) {
    if (ctx === 'pet') { const _o = document.getElementById('pet-cardpick-overlay'); if (_o) _o.remove(); petCardPickOpen(true); return; }
    if (ctx === 'dv')  { renderPet(); return; }
    if (_cardPick.weapon) _modRefresh(_cardPick.weapon);
  }
  function _cpSetStat(s, ctx) { _cpFilter.stat = (_cpFilter.stat === s) ? '' : s; _cpRedraw(ctx); }
  function _cpSetCB(v, ctx)   { _cpFilter.cb = v || ''; _cpRedraw(ctx); }
  // ใบนี้ผ่านตัวกรองไหม — การ์ด 1 ใบมี STAT ได้ 2 ชั้น (หลัก + โบนัสคอมแบตของใบ MVP ซึ่งเป็น STAT ตัวไหนก็ได้)
  function _cpPass(mm, id, mvp) {
    const cs = (mm.cs || '').toLowerCase(), cbT = _mvpCardBonus(+id, mm.lv || 1).t;
    const wS = _cpFilter.stat, wB = _cpFilter.cb;
    let ok = !wS || cs === wS || (mvp && cbT === wS); // ใบปกติดูแค่ STAT หลัก · ใบ MVP นับโบนัสด้วย
    if (wB) ok = mvp && ok && cbT === wB;             // เลือกโบนัส MVP = ใบปกติไม่มีทางเข้าเงื่อนไข
    return ok;
  }
  function _cpFilterBar(ctx, shown, total) {
    const btn = (s, lbl) => {
      const on = _cpFilter.stat === s, c = _CARD_STAT_CLR[s] || '#64748b';
      return `<button onclick="xhrpg._cpSetStat('${s}','${ctx}')" style="flex:1 1 0;min-width:0;padding:3px 0;border-radius:7px;cursor:pointer;font-size:10px;font-weight:800;border:${on ? '1.5px solid ' + c : '1px solid #e2e8f0'};background:${on ? c + '1a' : '#fff'};color:${on ? c : '#64748b'}">${lbl}</button>`;
    };
    return `<div style="display:flex;gap:3px;margin-bottom:4px">
        ${btn('', T('ทั้งหมด'))}${['str','agi','vit','dex','intel','luk'].map(s => btn(s, _CARD_STAT_LBL[s] || s)).join('')}
      </div>
      <div style="display:flex;align-items:center;gap:6px;margin-bottom:5px">
        <span style="flex:none;font-size:10px;color:#64748b;font-weight:600">${T('โบนัส MVP')}</span>
        <select onchange="xhrpg._cpSetCB(this.value,'${ctx}')" style="flex:1;min-width:0;padding:3px 6px;border:1px solid #e2e8f0;border-radius:7px;font-size:10.5px;background:#fff;color:#334155">
          <option value=""${_cpFilter.cb ? '' : ' selected'}>${T('ทั้งหมด')}</option>
          ${['atk','armor','hp','mp','hp_regen','mp_regen'].map(k => `<option value="${k}"${_cpFilter.cb === k ? ' selected' : ''}>${T(_CB_LBL[k] || k)}</option>`).join('')}
        </select>
        <span style="flex:none;font-size:9.5px;color:#94a3b8">${T('แสดง {a}/{b} ใบ', {a: shown, b: total})}</span>
      </div>`;
  }
  const _CARD_UNSOCKET_G = 3000;                     // sync XHRPG_CARD_UNSOCKET_G (server) — ถอดการ์ดจ่าย Gold (เดิม 10000)
  const _PETCARD_UNSOCK_G_PER_LV = 500, _PETCARD_UNSOCK_P = 15; // sync XHRPG_PETCARD_UNSOCKET_G_PER_LV / _P — ถอดการ์ดสัตว์เลี้ยง/สัตว์เทพ = Lv × 500 G หรือ 15 P
  const _PET_RESET_G_PER_LV = 1000, _PET_RESET_P = 20; // sync XHRPG_PET_RESET_G_PER_LV / _P — รีเซ็ตแต้มอัพสัตว์เลี้ยง/สัตว์เทพ = Lv × 1000 G หรือ 20 P
  function _modSockets(rarity){ return Math.max(1, Math.min(7, (rarity|0)||1)); } // sync xhrpg_module_sockets
  let _cardPick = { weapon:null, slot:null };        // รูที่กำลังเลือกการ์ดเสียบ (null = ปิด)
  // แถบรูการ์ดใต้โมดูลที่สวม: ช่องมีการ์ด = ค่า+ปุ่มถอด, ช่องว่าง = ปุ่ม ＋ เปิด picker
  function _modSocketStrip(weapon, slotKey, m){
    const n = _modSockets(m.rarity), cards = Array.isArray(m.cards) ? m.cards : [];
    let filled = 0, tiles = '';
    for (let i = 0; i < n; i++){
      const c = cards[i];
      if (c){
        filled++;
        const st  = (c.s || '').toLowerCase();
        const clr = _CARD_STAT_CLR[st] || '#94a3b8';
        const su  = _CARD_STAT_LBL[st] || '?';
        const mvp = !!c.mvp;
        const ba  = (c.mb && c.mb.a) | 0;
        const bt  = (c.mb && c.mb.t) || '';
        const bl  = _CB_LBL[bt] || bt || '';
        const bonus = (mvp && ba > 0)
          ? `<div style="height:12px;line-height:12px;font-size:8px;font-weight:800;color:#7c3aed;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%">+${ba} ${bl}</div>`
          : `<div style="height:12px"></div>`;
        tiles += `<div title="${T('ถอด {a} G', {a: _CARD_UNSOCKET_G.toLocaleString()})}" style="position:relative;box-sizing:border-box;min-width:0;height:46px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;background:${mvp ? '#fef2f2' : '#fffdf8'};border:1px solid ${mvp ? '#dc2626' : clr};border-radius:8px;padding:2px 3px">`
          + `${mvp ? `<span style="position:absolute;top:1px;left:3px;font-size:8px;line-height:1;color:#dc2626">⭐</span>` : ''}`
          + `<button onclick="xhrpg.cardUnsocket('${weapon}','${slotKey}',${i})" title="${T('ถอดการ์ด (เลือกจ่าย G ตามระดับ / 5 P)')}" style="position:absolute;top:1px;right:1px;width:14px;height:14px;border:none;background:#fee2e2;color:#dc2626;font-size:9px;font-weight:800;border-radius:5px;padding:0;cursor:pointer;line-height:14px">✕</button>`
          + `<div style="font-size:11px;line-height:12px;font-weight:800;color:${clr};white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%">+${c.v | 0} ${su}${_sacPlusOf(c)}</div>`
          + bonus
          + `</div>`;
      } else {
        const active = _cardPick.weapon === weapon && _cardPick.slot === slotKey;
        tiles += `<button onclick="xhrpg.cardPickOpen('${weapon}','${slotKey}')" title="${T('เสียบการ์ด')}" style="box-sizing:border-box;min-width:0;height:46px;display:flex;align-items:center;justify-content:center;font-size:16px;font-weight:700;color:${active ? '#fff' : '#a78bfa'};background:${active ? '#7c3aed' : '#faf5ff'};border:1px dashed ${active ? '#7c3aed' : '#a78bfa'};border-radius:8px;padding:0;cursor:pointer;line-height:1">＋</button>`;
      }
    }
    return `<div style="padding:2px 8px 7px 8px;border-top:1px dashed #f1e9d8">`
      + `<div style="font-size:9px;color:#92400e;font-weight:700;margin:3px 0 4px 1px">${T('🎴 รู {a}/{b}', {a: filled, b: n})}</div>`
      + `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(74px,1fr));gap:4px">${tiles}</div>`
      + `</div>`;
  }
  // picker เลือกการ์ดจากคลัง (player.cards) เสียบลงรูที่เลือก — โชว์เฉพาะอาวุธที่ตรงกับ _cardPick
  function _cardPickerHtml(weapon){
    if (_cardPick.weapon !== weapon || !_cardPick.slot) return '';
    const cards = (player.cards && typeof player.cards === 'object' && !Array.isArray(player.cards)) ? player.cards
                : (() => { try { return JSON.parse(player.cards || '{}') || {}; } catch (e) { return {}; } })();
    let cells = '', _cpShow = 0, _cpTot = 0;
    Object.keys(cards).filter(id => monMasters[id] && (((cards[id]||{}).n|0) > 0 || ((cards[id]||{}).m|0) > 0))
      .sort((a,b) => ((monMasters[a].lv||0)-(monMasters[b].lv||0)) || (+a - +b))
      .forEach(id => {
        const mm = monMasters[id], o = cards[id] || {};
        [['n', false], ['m', true]].forEach(([k, mvp]) => {
          const cnt = o[k] | 0; if (cnt <= 0) return;
          _cpTot++; if (!_cpPass(mm, id, mvp)) return; _cpShow++; // 🔎 ตัวกรอง — นับยอดรวมก่อนกรองเสมอ
          const st=(mm.cs||'').toLowerCase(), clr=_CARD_STAT_CLR[st]||'#94a3b8', su=_CARD_STAT_LBL[st]||'?', v=_cardValue(mm.lv||1, mvp);
          const sb = _monSpriteBg(mm.lv||1);
          const art = sb
            ? `<div style="width:28px;height:28px;background:url('${sb.url}') 0 0/${sb.cols*28}px ${sb.rows*28}px no-repeat;image-rendering:pixelated"></div>`
            : `<div style="font-size:20px;line-height:1">${mm.e||'👾'}</div>`;
          cells += `<button onclick="xhrpg.cardSocket('${weapon}',${id},${mvp?1:0})" title="${T(mm.n||'')}${mvp?' MVP':''}" style="position:relative;display:flex;flex-direction:column;align-items:center;gap:1px;background:${mvp?'#fef2f2':'#fff'};border:1px solid ${mvp?'#dc2626':clr};border-radius:7px;padding:4px 2px;cursor:pointer">
            ${mvp?`<span style="position:absolute;top:1px;left:2px;font-size:7px;font-weight:800;color:#fff;background:#dc2626;padding:0 2px;border-radius:3px">MVP</span>`:''}
            ${cnt>1?`<span style="position:absolute;top:1px;right:3px;font-size:8px;font-weight:700;color:${mvp?'#dc2626':clr}">×${cnt}</span>`:''}
            <div style="height:30px;display:flex;align-items:center;justify-content:center">${art}</div>
            <span style="font-size:9px;font-weight:700;color:${clr}">+${v} ${su}${_sacPlus(+id, mm.lv || 1)}</span>
            ${mvp ? (()=>{ const b=_mvpCardBonus(+id, mm.lv||1); return b.a>0 ? `<span style="font-size:8px;font-weight:700;color:#7c3aed">+${b.a} ${_CB_LBL[b.t]||b.t}</span>` : ''; })() : ''}</button>`;
        });
      });
    if (!cells) cells = `<span style="font-size:11px;color:#78716c">${T(_cpTot > 0 ? 'ไม่มีการ์ดที่ตรงเงื่อนไข' : '— ไม่มีการ์ดในคลัง —')}</span>`;
    return `<div style="margin-top:8px;background:#faf5ff;border:1px solid #d8b4fe;border-radius:9px;padding:7px">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px">
        <span style="font-size:11px;color:#7c2d92;font-weight:700">${T('🎴 เลือกการ์ดเสียบ')} · ${T(_modSlotName(weapon, _cardPick.slot))} <span style="color:#a855f7">${T('(เสียบถาวร)')}</span></span>
        <button onclick="xhrpg.cardPickClose()" style="font-size:10px;padding:2px 8px;border:1px solid #a8a29e;border-radius:5px;background:#fff;color:#57534e;cursor:pointer">${T('ปิดหน้าต่าง')}</button>
      </div>
      ${_cpFilterBar('mod', _cpShow, _cpTot)}
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(48px,1fr));gap:4px">${cells}</div>
    </div>`;
  }

  // แผงการ์ด (เมนู CARD) — สมุดสะสมเต็มแผง · diff guard กัน rebuild ทุก poll (แวบ)
  // ── 🏺🎴 การ์ด 3 เทพ (sync XHRPG_GOD_CARD_*) — แลกด้วยการ์ด MVP มอนทุกชนิด Lv≤50 ชนิดละ 3 ใบ ──
  const GOD_MAX = 5, GOD_ATK = 0.20, GOD_COST = 3, GOD_MAX_LV = 50;
  // ── 🎴🔥 บูชายัญการ์ด MVP (docs/card-sacrifice-design.md · เจ้าของเคาะ 2026-08-14) ──
  //    ⚠️ ค่าคงที่ 4 ตัวนี้ต้องตรงกับ XHRPG_SAC_* ใน xhrpg_config.php เป๊ะ (เลขที่โชว์ต้องตรงกับที่ server คิด)
  const SAC_MAX = 30, SAC_COST = 1, SAC_PER = 0.2, SAC_BIG = 7; // SAC_PER 0.2 = ระดับ 🅲 (เต็ม 30 ดาว = การ์ด MVP อีก 2 ใบ)
  const _sacObj = () => { const s = player && player.sac_cards; return (s && typeof s === 'object' && !Array.isArray(s)) ? s : (typeof s === 'string' ? (() => { try { return JSON.parse(s || '{}') || {}; } catch (e) { return {}; } })() : {}); };
  const _sacN = (mid) => Math.max(0, Math.min(SAC_MAX, (_sacObj()[mid] | 0)));       // ดาวของมอนชนิดนี้ (clamp sync PHP)
  const _sacU = (lv) => Math.max(1, Math.ceil(Math.max(1, lv | 0) / 10));             // u = ceil(Lv/10) — หน่วยเดียวกับ _cardValue
  // 🚨 ตัดขยะ float ก่อนเสมอ — 0.1 เก็บเป็น binary ไม่ลงตัว (3 × 0.1 = 0.30000000000000004)
  //    ไม่ปัดก่อน = ceil เด้งเกินมา 1 แบบสุ่ม · **ต้องตรงกับ round(…, 6) ฝั่ง PHP** ไม่งั้นเลขที่โชว์ไม่ตรงกับที่ได้จริง
  const _sacRnd = (v) => Math.round(v * 1e6) / 1e6;
  const _sacAdd = (mid, lv) => _sacRnd(_sacN(mid) * SAC_PER * _sacU(lv));             // โบนัสต่อการ์ด 1 ใบ (ทศนิยม)
  // นับการ์ดของมอนชนิดนี้ที่ "เสียบอยู่" ทุกที่ — mirror 3 บล็อกใน xhrpg_module_stat_bonus
  //    (โมดูล 10 ชุด · 🐾 สัตว์เลี้ยง · 🏺 สัตว์เทพ) · นับทั้งการ์ดปกติและ MVP เพราะโบนัสครอบทั้งคู่
  function _sacWorn(mid) {
    if (!player) return 0;
    let n = 0;
    const _pick = (arr) => { if (Array.isArray(arr)) arr.forEach(c => { if (c && (c.mid | 0) === (mid | 0)) n++; }); };
    ['pistol_modules','sniper_modules','knife_modules','axe_modules','robot_modules','robot_gun_modules','railgun_modules','armor_modules','house_modules','turret_modules'].forEach(f => {
      if (f === 'railgun_modules' && (+(player.robot_railgun_expires || 0)) <= Math.floor(Date.now() / 1000)) return; // หมดอายุ = ไม่ให้ stat (ตรงกับ server)
      let mods = player[f];
      if (typeof mods === 'string') { try { mods = JSON.parse(mods || '{}'); } catch (e) { mods = {}; } }
      if (!mods || typeof mods !== 'object') return;
      Object.keys(mods).forEach(k => { const m = mods[k]; if (m) _pick(m.cards); });
    });
    if (player.pet_mid | 0) { let pc = player.pet_cards; if (typeof pc === 'string') { try { pc = JSON.parse(pc || '[]'); } catch (e) { pc = []; } } _pick(pc); }
    if (player.dv_pet | 0)  { let dc = player.dv_cards;  if (typeof dc === 'string') { try { dc = JSON.parse(dc || '[]'); } catch (e) { dc = []; } } _pick(dc); }
    return n;
  }
  // 🌟 ดาวเล็ก SAC_BIG ดวง = ดาวใหญ่ 1 ดวง — font เล็ก + letter-spacing ติดลบ กันดันเลย์เอาต์ตอนเต็ม 30 ดาว
  const _sacStars = (n) => n < 1 ? '' :
    `<span style="font-size:9px;letter-spacing:-1px;white-space:nowrap">${'🌟'.repeat((n / SAC_BIG) | 0)}${'⭐'.repeat(n % SAC_BIG)}</span>`;
  // แสดงทศนิยม 1 ตำแหน่ง แต่ตัด .0 ทิ้ง (1.6 · 6 · 12.8)
  const _sacTxt = (v) => (Math.round(v * 10) / 10).toFixed(1).replace(/\.0$/, '');
  // 🎴🔥 ป้ายระดับดาวในช่องการ์ด (สมุดการ์ด) — ดาวผูกกับ "ชนิดมอน" ⇒ ขึ้นทั้งช่องปกติและช่อง MVP ของมอนตัวเดียวกัน
  //    วาง absolute เพื่อไม่ให้ดันเลย์เอาต์ — ช่อง MVP มีป้าย MVP อยู่มุมบนซ้ายแล้ว จึงเลื่อนลงมาแถวถัดไป
  //    ใช้เลข (🌟5) ไม่ใช่เรียงสัญลักษณ์ — ช่องการ์ดแคบ 30 ดาวจะล้น (แท็บบูชายัญที่กว้างกว่าถึงเรียงเต็ม)
  function _sacBadge(mid, lv, mvp) {
    const st = _sacN(mid); if (st < 1) return '';
    const ttl = T('โบนัสจากดาว').replace(/"/g, '&quot;'); // บางภาษามี " ในคำแปล — กัน attribute แตก
    return `<span title="${ttl} +${_sacTxt(_sacAdd(mid, lv))}" style="position:absolute;top:${mvp ? 16 : 3}px;left:4px;font-size:8.5px;font-weight:800;color:#b45309;background:#fef3c7;padding:0 3px;border-radius:4px;line-height:13px">🌟${st}</span>`;
  }
  // ต่อท้ายค่า STAT หลักด้วยส่วนที่ดาวเพิ่มให้ (เจ้าของสั่ง 2026-08-14) — เช่น "+24 VIT +4.8"
  const _sacPlus = (mid, lv) => { const a = _sacAdd(mid, lv); return a > 0 ? ` <span style="color:#b45309">+${_sacTxt(a)}</span>` : ''; };
  // ── โบนัสดาวของ "การ์ดที่เสียบอยู่ 1 ใบ" — mirror xhrpg_sac_add_of() ฝั่ง server ─────
  //    การ์ดที่เสียบเก็บแค่ {mid,mvp,s,v,mb} ไม่มี Lv ⇒ ถอด u กลับจาก v เหมือน server เป๊ะ
  //    (xhrpg_card_value: การ์ดปกติ v = u · การ์ด MVP v = u × 3)
  const _sacUnitOf = (c) => { const v = (c && parseInt(c.v)) || 0; return v < 1 ? 0 : Math.max(1, c.mvp ? Math.round(v / 3) : v); };
  const _sacAddOf  = (c) => {
    const mid = (c && (c.mid | 0)) || 0; if (mid < 1) return 0;
    const st = _sacN(mid); if (st < 1) return 0;
    const u = _sacUnitOf(c); return u < 1 ? 0 : _sacRnd(st * SAC_PER * u);
  };
  // ป้ายต่อท้ายค่าการ์ดในช่องที่เสียบอยู่ (โมดูล/สัตว์เลี้ยง/สัตว์เทพ) — โชว์ว่าดาวเพิ่มให้เท่าไหร่
  const _sacPlusOf = (c) => { const a = _sacAddOf(c); return a > 0 ? ` <span style="color:#b45309">+${_sacTxt(a)}</span>` : ''; };

  let _godTab = 0; // 0 = สมุดการ์ด · 1 = การ์ด 3 เทพ · 2 = 🔥 บูชายัญ
  const _godCardsObj = () => { const g = player && player.god_cards; return (g && typeof g === 'object' && !Array.isArray(g)) ? g : (typeof g === 'string' ? (JSON.parse(g || '{}') || {}) : {}); };
  const _godN = (k) => Math.max(0, Math.min(GOD_MAX, (_godCardsObj()[k || 'anubis'] | 0))); // จำนวนใบที่ถือ (clamp เพดาน sync PHP)
  function _godSetTab(on) { _godTab = on | 0; renderCard(); }
  function _renderGodCards() { // เนื้อหาแท็บ 3 เทพ
    const have = _godN('anubis'), full = have >= GOD_MAX;
    // ความคืบหน้า: มอนทุกชนิด Lv ≤ 50 ต้องมีการ์ด MVP ชนิดละ ≥ GOD_COST
    const cards = (player.cards && typeof player.cards === 'object' && !Array.isArray(player.cards)) ? player.cards
                : (() => { try { return JSON.parse(player.cards || '{}') || {}; } catch (e) { return {}; } })();
    const need = Object.keys(monMasters).map(k => monMasters[k] && { id: +k, lv: monMasters[k].lv | 0, n: monMasters[k].n || '' })
      .filter(m => m && m.lv >= 1 && m.lv <= GOD_MAX_LV);
    const missing = need.filter(m => (((cards[m.id] || {}).m) | 0) < GOD_COST);
    const okN = need.length - missing.length, ready = need.length > 0 && missing.length === 0;
    const pct = need.length ? Math.round(okN / need.length * 100) : 0;
    const missTxt = missing.slice(0, 3).map(m => `${T(m.n)} (${((cards[m.id] || {}).m) | 0}/${GOD_COST})`).join(' · ') + (missing.length > 3 ? ` … +${missing.length - 3}` : '');
    const lockedRows = [['dv_horus', 'Horus'], ['dv_medusa', 'Medusa']].map(([k, n]) =>
      `<div style="border:1px solid #e2e8f0;border-radius:12px;background:#f8fafc;padding:8px 12px;display:flex;align-items:center;gap:10px;margin-top:8px">
        <img src="${baseUrl}assets/pets/${k}.png" style="width:40px;height:40px;border-radius:10px;background:#e2e8f0;filter:grayscale(1);opacity:.5" alt="">
        <div style="min-width:0"><div style="font-size:12.5px;color:#94a3b8;font-weight:600">${n}</div><div style="font-size:10px;color:#cbd5e1">??? · ${T('เร็วๆ นี้')}</div></div>
        <span style="margin-left:auto;font-size:14px;color:#cbd5e1">🔒</span>
      </div>`).join('');
    const btnOn = ready && !full;
    return `<div style="border:2px solid #f59e0b;border-radius:12px;background:#fffbeb;padding:11px 12px;margin-top:4px">
      <div style="display:flex;gap:10px;align-items:center">
        <img src="${baseUrl}assets/pets/dv_anubis.png" style="width:56px;height:56px;border-radius:12px;background:#1e293b" alt="">
        <div style="flex:1;min-width:0">
          <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap">
            <span style="font-size:14px;font-weight:700;color:#78350f">${T('การ์ดเทพ Anubis')}</span>
            <span style="font-size:10px;background:#fbbf24;color:#78350f;border-radius:6px;padding:1px 6px">${T('ถือครอง {n}/{m}', {n: have, m: GOD_MAX})}</span>
          </div>
          <div style="font-size:10.5px;color:#92400e;margin-top:2px">${T('⚔️ ATK ทุกแหล่ง +{p}% ต่อใบ (ติดตัวถาวร)', {p: Math.round(GOD_ATK * 100)})}</div>
          <div style="font-size:10.5px;color:#b45309">🔒 ${T('ผูกกับตัวผู้เล่น — ขาย/เทรด/ลงตลาดไม่ได้')}</div>
        </div>
      </div>
      ${have > 0 ? `<div style="margin-top:8px;background:#fff;border:1px solid #fcd34d;border-radius:9px;padding:7px 10px;text-align:center;font-size:12px;color:#78350f;font-weight:700">⚔️ ${T('พลังโจมตีรวมตอนนี้')} <b style="font-size:15px;color:#b45309">+${Math.round(GOD_ATK * 100 * have)}%</b></div>` : ''}
      <div style="margin-top:9px;background:#fff;border-radius:9px;padding:8px 10px;border:1px solid #fcd34d">
        <div style="display:flex;justify-content:space-between;font-size:11px;color:#92400e">
          <span>${T('🎴⭐ การ์ด MVP Lv.1-{a} (ทุกชนิด · ชนิดละ {c})', {a: GOD_MAX_LV, c: GOD_COST})}</span>
          <span style="font-weight:700">${okN}/${need.length} ${T('ชนิด')}</span>
        </div>
        <div style="height:8px;background:#fde68a;border-radius:4px;margin-top:5px;overflow:hidden"><div style="width:${pct}%;height:100%;background:${ready ? '#16a34a' : '#f59e0b'}"></div></div>
        ${missing.length ? `<div style="font-size:9.5px;color:#b45309;margin-top:4px">${T('ขาด:')} ${missTxt}</div>` : ''}
      </div>
      <button onclick="xhrpg.godCardExchange()" ${btnOn ? '' : 'disabled'} style="width:100%;margin-top:8px;text-align:center;padding:9px 0;border-radius:9px;border:none;background:${btnOn ? '#d97706' : '#d6d3d1'};color:${btnOn ? '#fff' : '#78716c'};font-size:13px;font-weight:700;cursor:${btnOn ? 'pointer' : 'default'}">${full ? T('✅ เต็มเพดานแล้ว ({m} ใบ)', {m: GOD_MAX}) : (ready ? T('🏺🎴 แลกการ์ดเทพ Anubis') : T('🔒 สะสมการ์ด MVP ให้ครบเพื่อแลก'))}</button>
    </div>` + lockedRows;
  }
  function godCardExchange() {
    if (!player || player.line_uid === 'demo') return;
    if (!confirm(T('แลกการ์ดเทพ Anubis? จะใช้การ์ด ⭐MVP ทุกชนิด Lv.1-{a} ชนิดละ {c} ใบ (ใช้แล้วหายถาวร)', {a: GOD_MAX_LV, c: GOD_COST}))) return;
    $.post(baseUrl + 'xhrpg_upgrade.php', { line_uid: player.line_uid, action: 'god_card_exchange', lang: LANG() })
      .done(res => {
        let d; try { d = typeof res === 'string' ? JSON.parse(res) : res; } catch (e) { return; }
        if (d.ok) { player = d.player; renderCard(); updateHUD(); addLog([{ type: 'levelup', msg: d.msg }]); }
        else addLog([{ type: 'dead', msg: d.error || T('แลกไม่สำเร็จ') }]);
      })
      .fail(() => addLog([{ type: 'dead', msg: T('❌ แลกไม่สำเร็จ (เชื่อมต่อ server ไม่ได้)') }]));
  }
  // ── 🎴🔥 เนื้อหาแท็บบูชายัญ ────────────────────────────────────────────────
  //    โชว์เฉพาะมอนที่ "ทำอะไรได้/มีอะไรให้ดู": มี MVP ในคลัง หรือเคยบูชายัญไว้แล้ว
  //    มอนที่ไม่มี card_stat ตัดทิ้ง — เสียบไม่ได้อยู่แล้ว ดาวจะไร้ความหมาย (server กันซ้ำอีกชั้น)
  // ══ 🔥 โครงร่วมของหน้าบูชายัญ 2 หน้า (การ์ด / ไข่) — docs/sacrifice-ui-redesign.md ══
  //    ⚠️ งานนี้ปรับ **หน้าตาอย่างเดียว** — สูตร ค่าพลัง เงื่อนไขปุ่ม ลำดับการเรียง เหมือนเดิมทุกตัวอักษร
  //    เดิมสองหน้าโครงต่างกันเล็ก ๆ หลายจุดทั้งที่เป็นระบบพี่น้องกัน · การ์ดสูงไม่เท่ากันเพราะบรรทัดรองมีบ้างไม่มีบ้าง
  //    ⇒ ยุบเหลือ shell เดียว 3 ชั้น: ① ตัวตน ② ผลลัพธ์บรรทัดเดียว ③ ของในคลัง + ปุ่มเดียวกว้างคงที่
  let _sacFilt = { c: 'all', e: 'all' };  // ตัวกรองแยกกันต่อหน้า (c = การ์ด · e = ไข่) — จำแค่ใน session
  let _sacOpen = {};                       // การ์ดใบไหนกางรายละเอียดอยู่ · คีย์ 'c12' / 'e12'
  function _sacToggle(k) { _sacOpen[k] = !_sacOpen[k]; if (String(k).charAt(0) === 'c') renderCard(); else renderPet(); }
  function _sacSetFilt(w, v) { _sacFilt[w] = v; if (w === 'c') renderCard(); else renderPet(); }
  // 📊 แถบสรุปบนสุด — นับจากข้อมูลที่หน้านี้มีอยู่แล้ว ไม่ยิง endpoint เพิ่ม
  function _sacSumBar(parts) {
    return `<div style="display:flex;gap:6px;background:#fffbeb;border:1px solid #fde68a;border-radius:10px;padding:6px 9px;margin-bottom:6px">`
      + parts.map(p => `<div style="flex:1;min-width:0;text-align:center">
          <div style="font-size:13px;font-weight:800;color:#b45309;line-height:1.2">${p.v}</div>
          <div style="font-size:8.5px;color:#a16207;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${p.k}</div>
        </div>`).join('') + `</div>`;
  }
  // 🔀 ชิปกรอง — "ทั้งหมด" ต้องคงพฤติกรรมเดิมเป๊ะ (ไม่ตัดใครออก · ลำดับเดิม)
  //    ⚠️ บทเรียน 2026-08-14: เคยกรองแถวที่ยังไม่มีการ์ดออกจากค่าเริ่มต้น แล้วผู้เล่นนึกว่าระบบไม่แสดง — ห้ามซ้ำ
  function _sacFiltBar(w, nAll, nReady, nStar) {
    const cur = _sacFilt[w] || 'all';
    const b = (v, lb, n) => `<button onclick="xhrpg._sacSetFilt('${w}','${v}')" style="flex:1;padding:5px 3px;border-radius:7px;border:1px solid ${cur === v ? '#b91c1c' : '#e2e8f0'};background:${cur === v ? '#b91c1c' : '#fff'};color:${cur === v ? '#fff' : '#64748b'};font-size:10px;font-weight:700;cursor:pointer;font-family:inherit;white-space:nowrap">${lb} ${n}</button>`;
    return `<div style="display:flex;gap:5px;margin-bottom:8px">${b('all', T('ทั้งหมด'), nAll)}${b('ready', '🔥 ' + T('พร้อมบูชา'), nReady)}${b('star', '⭐ ' + T('มีดาวแล้ว'), nStar)}</div>`;
  }
  // 🖼️ รูปมอน 40px — ยกสูตรเดิมมาใช้ร่วมกัน 2 หน้า (เดิมก็อปไว้คนละที่)
  //    ⚠️ _monSpriteBg คืนอ็อบเจกต์ {url, cols, rows} ไม่ใช่สตริง CSS — ใส่ตรง ๆ จะได้ [object Object] = สี่เหลี่ยมเปล่า
  function _sacArt(lv, emo) {
    const D = 40, sb = _monSpriteBg(lv);
    return sb
      ? `<div style="width:${D}px;height:${D}px;flex:none;background:url('${sb.url}') 0 0/${sb.cols * D}px ${sb.rows * D}px no-repeat;image-rendering:pixelated"></div>`
      : `<div style="width:${D}px;height:${D}px;flex:none;display:flex;align-items:center;justify-content:center;font-size:26px">${emo || '👾'}</div>`;
  }
  // 🧱 การ์ด 1 ใบ — ความสูงพื้นฐานเท่ากันทุกแถว · อะไรที่ยาวไม่เท่ากันไปอยู่ในส่วนกางทั้งหมด
  function _sacShell(o) {
    const open = !!_sacOpen[o.key];
    const chev = o.detail
      ? `<button onclick="xhrpg._sacToggle('${o.key}')" aria-label="${T('รายละเอียด')}" style="flex:none;width:20px;height:20px;padding:0;border:1px solid #e2e8f0;border-radius:6px;background:#fff;color:#94a3b8;font-size:9px;line-height:1;cursor:pointer;font-family:inherit">${open ? '▲' : '▼'}</button>`
      : '';
    return `<div style="position:relative;border:1px solid ${o.on ? '#fbbf24' : '#e2e8f0'};background:${o.on ? '#fffbeb' : '#fff'};border-radius:11px;padding:9px 11px;margin-bottom:8px${o.dim ? ';opacity:.55' : ''}">
      ${o.corner || ''}
      <div style="display:flex;align-items:center;gap:9px">
        ${_sacArt(o.lv, o.emo)}
        <div style="flex:1;min-width:0">
          <div style="display:flex;align-items:center;gap:5px">
            <span style="font-size:12.5px;font-weight:700;color:#1e293b;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${o.name}</span>
            <span style="flex:none;font-size:9.5px;color:#94a3b8">Lv.${o.lv}</span>
          </div>
          <div style="font-size:11px;font-weight:700;margin-top:1px">${o.effect}</div>
        </div>
        <div style="flex:none;text-align:right;max-width:96px">${_sacStars(o.st)}
          <div style="font-size:9.5px;color:#b45309;font-weight:700">${o.st}/${SAC_MAX}</div></div>
      </div>
      <div style="display:flex;align-items:center;gap:8px;margin-top:6px">
        <span style="flex:1;min-width:0;font-size:9.5px;color:#64748b;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${o.stock}</span>
        ${chev}
        <div style="flex:0 0 55%;min-width:0">${o.btn}</div>
      </div>
      ${open && o.detail ? `<div style="margin-top:7px;padding-top:7px;border-top:1px dashed #e5e7eb;font-size:9.5px;color:#475569;line-height:1.7">${o.detail}</div>` : ''}
    </div>`;
  }
  function _sacTag(txt, col) { return `<div style="text-align:center;font-size:10px;font-weight:700;color:${col};padding:7px 2px;line-height:1.2">${txt}</div>`; }
  function _sacGo(onclick, label, bg) { return `<button onclick="${onclick}" style="width:100%;padding:7px 4px;border:none;border-radius:8px;background:${bg};color:#fff;font-size:10.5px;font-weight:700;cursor:pointer;font-family:inherit;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${label}</button>`; }

  function _renderSacrifice() {
    const cards = (player.cards && typeof player.cards === 'object' && !Array.isArray(player.cards)) ? player.cards
                : (() => { try { return JSON.parse(player.cards || '{}') || {}; } catch (e) { return {}; } })();
    const rows = Object.keys(monMasters)
      .map(k => { const mm = monMasters[k]; return mm ? { id: +k, mm, mvp: (cards[k] || {}).m | 0, st: _sacN(+k) } : null; })
      // แสดง **ทุกมอนที่การ์ดใช้งานได้** เหมือนสมุดการ์ด (เจ้าของติง 2026-08-14 "แสดง MVP ไม่ครบทุกใบ")
      //    เดิมกรองเฉพาะที่มี MVP ในคลัง ⇒ มอนที่ยังไม่มีการ์ดหายไปเลย ทั้งที่สมุดการ์ดโชว์ทุกตัว
      //    มอนที่ไม่มี card_stat ยังตัดทิ้ง — เสียบไม่ได้อยู่แล้ว ดาวจะไร้ความหมาย
      .filter(r => r && (r.mm.cs || ''))
      //    เรียง: มีดาวแล้วขึ้นบนสุด → ที่เหลือเรียงตาม Lv สูง→ต่ำ
      //    ⚠️ **ห้ามเอา "มีการ์ดในคลัง" มาเป็นตัวเรียง** — เคยทำแล้วแถวที่ยังไม่มีการ์ด (สีเทา)
      //       ถูกดันไปกองท้ายลิสต์ทั้งหมด ผู้เล่นเลื่อนไม่ถึง นึกว่าไม่แสดง (เจ้าของแจ้ง 2026-08-14)
      //       เรียงตาม Lv ล้วนแบบนี้ = มีกับไม่มีสลับกันไป เห็นภาพรวมทั้งสมุดเหมือนแท็บสมุดการ์ด
      .sort((a, b) => (b.st - a.st) || ((b.mm.lv | 0) - (a.mm.lv | 0)) || (a.id - b.id));
    const head = `<div style="border:1px solid #fecaca;background:#fef2f2;border-radius:10px;padding:8px 11px;font-size:11px;color:#991b1b;margin-bottom:8px">
        🔥 ${T('ใช้การ์ด ⭐MVP บูชายัญ → ได้ดาวของมอนชนิดนั้น (สูงสุด {a} ดาว)', {a: SAC_MAX})}<br>
        <span style="color:#b91c1c">${T('ทุกดาว = การ์ดของมอนชนิดนี้ที่เสียบอยู่ "ทุกใบ" แรงขึ้นทันที ไม่ต้องถอด')}</span>
      </div>`;
    if (!rows.length) return head + `<div style="text-align:center;color:#94a3b8;padding:22px;font-size:12.5px">${T('ยังไม่มีการ์ด ⭐MVP ให้บูชายัญ')}</div>`;
    // 📊 นับก่อนกรอง — ตัวเลขบนแถบสรุป/ชิป ต้องเป็นภาพรวมทั้งสมุด ไม่ใช่แค่ที่กรองเหลือ
    const nAll = rows.length;
    const nStar = rows.filter(r => r.st > 0).length;
    const nReady = rows.filter(r => r.st < SAC_MAX && r.mvp >= SAC_COST).length;
    const sumStars = rows.reduce((s, r) => s + r.st, 0);
    const bar = _sacSumBar([
      { v: '⭐ ' + sumStars, k: T('ดาวรวม') },
      { v: nStar + '/' + nAll, k: T('มีดาวแล้ว') },
      { v: '🔥 ' + nReady, k: T('พร้อมบูชา') },
    ]) + _sacFiltBar('c', nAll, nReady, nStar);
    const fv = _sacFilt.c || 'all';
    const view = fv === 'ready' ? rows.filter(r => r.st < SAC_MAX && r.mvp >= SAC_COST)
               : fv === 'star'  ? rows.filter(r => r.st > 0) : rows;
    if (!view.length) return head + bar + `<div style="text-align:center;color:#94a3b8;padding:20px;font-size:12px">${T('ไม่มีรายการในตัวกรองนี้')}</div>`;
    return head + bar + view.map(r => {
      const lv = r.mm.lv | 0, st = r.st, full = st >= SAC_MAX, worn = _sacWorn(r.id);
      const sKey = (r.mm.cs || '').toLowerCase(), clr = _CARD_STAT_CLR[sKey] || '#94a3b8', su = _CARD_STAT_LBL[sKey] || '?';
      const base = _cardValue(lv, true), add = _sacAdd(r.id, lv);           // ค่าอ้างอิง = การ์ด MVP 1 ใบ
      const addTxt = add > 0 ? _sacTxt(add) : '0';
      const per = SAC_PER * _sacU(lv);
      // 🎯 โชว์ "ค่าตอนนี้ → ค่าหลังกด" ไม่ใช่ "ฐาน → ตอนนี้" (เจ้าของติง 2026-08-14 "24 → 32 มันงง")
      //    คนที่ยืนหน้าปุ่มอยากรู้ว่ากดแล้วได้อะไร ไม่ใช่ว่าเคยเริ่มจากเท่าไหร่
      const cur = base + Math.ceil(add);                    // ค่าที่ได้จริงตอนนี้
      const nxt = base + Math.ceil(_sacRnd(add + per));      // ค่าหลังบูชายัญอีก 1 ครั้ง
      // "อีกกี่ดาวเลขจะขยับ" — เก็บไว้เฉพาะตอนที่ยังมีช่วงนิ่งจริง คือดาวละ < 1 (มอน Lv ≤ 40)
      //    มอน Lv.41+ ดาวละ ≥ 1 ขยับทุกดาวอยู่แล้ว ⇒ บรรทัดนี้กลายเป็นตัวกวน (docs round2 §1)
      const need = per > 0 ? Math.ceil(_sacRnd(((Math.floor(add) + 1) - add) / per)) : 0;
      const nextTxt = (!full && per < 1 && need > 1 && st + need <= SAC_MAX)
        ? ` · <span style="color:#94a3b8">${T('อีก {a} ดาว → +{b}', {a: need, b: Math.floor(add) + 1})}</span>` : '';
      // 🎯 STAT เสริมของการ์ด MVP (mb) — ชนิดคงที่ต่อมอน
      //    ⚠️ ดาว **ไม่คูณตัวนี้** (โบนัสเป็นค่าคงที่ ไม่ใช่ %) ⇒ ย้ายไปอยู่ในส่วนกาง จะได้ไม่ปนกับตัวเลขที่ดาวคูณจริง
      const cb = _mvpCardBonus(r.id, lv);
      const can = !full && r.mvp >= SAC_COST;
      // ยังไม่มีการ์ด MVP และยังไม่เคยลงดาว = โชว์แบบจาง ๆ ให้รู้ว่ามีอยู่ (ล้อสมุดการ์ดที่โชว์ทุกตัว)
      const dim = (r.mvp < 1 && st < 1);
      // ② ผลลัพธ์บรรทัดเดียว — ตัวเลขและเงื่อนไขเหมือนเดิมทุกประการ แค่ตัดของรองออกไปไว้ส่วนกาง
      const effect = `<span style="color:${clr}">+${su} ${cur}</span>${full ? '' : ` <span style="color:#b45309">→ ${nxt}</span>`}`;
      // ③ ของในคลัง (ซ้าย) + ปุ่มเดียวกว้างคงที่ (ขวา)
      const stock = `🎴<b style="color:${r.mvp > 0 ? '#b91c1c' : '#cbd5e1'}">⭐${T('ในคลัง {a} ใบ', {a: r.mvp})}</b>`;
      const btn = full ? _sacTag('✅ ' + T('เต็มเพดาน {a} ดาว', {a: SAC_MAX}), '#16a34a')
        : can ? _sacGo('xhrpg.cardSacrifice(' + r.id + ')', '🔥 ' + T('บูชายัญ'), '#b91c1c')
        : _sacTag(T('ยังไม่มีการ์ด ⭐MVP ใบนี้'), '#94a3b8');
      // ส่วนกาง — ของเดิมทั้งหมดที่เคยเบียดอยู่บนหน้าการ์ด ย้ายมารวมที่นี่
      const detail = `${T('เสียบอยู่ {a} ใบ', {a: worn})}`
        + (add > 0 ? ` · <b style="color:#b45309">${T('โบนัสจากดาว')} +${addTxt}</b>${nextTxt}` : '')
        + (cb && cb.a > 0 ? `<br><span style="color:#7c3aed;font-weight:700">+${cb.a} ${_CB_LBL[cb.t] || cb.t}</span> <span style="color:#94a3b8">${T('โบนัสคอมแบต (เฉพาะการ์ด MVP เมื่อเสียบในโมดูล)')}</span>` : '');
      return _sacShell({ key: 'c' + r.id, lv, emo: r.mm.e, name: T(r.mm.n || ''), st, on: st > 0, dim, effect, stock, btn, detail });
    }).join('');
  }
  function cardSacrifice(mid) {
    if (!player || player.line_uid === 'demo') return;
    const mm = monMasters[mid] || {};
    if (!confirm(T('บูชายัญการ์ด {a}? ใช้การ์ด ⭐MVP {b} ใบ (ใช้แล้วหายถาวร)', {a: T(mm.n || ''), b: SAC_COST}))) return;
    $.post(baseUrl + 'xhrpg_upgrade.php', { line_uid: player.line_uid, action: 'card_sacrifice', mid: mid | 0, lang: LANG() })
      .done(res => {
        let d; try { d = typeof res === 'string' ? JSON.parse(res) : res; } catch (e) { return; }
        if (d.ok) { player = d.player; renderCard(); updateHUD(); addLog([{ type: 'levelup', msg: d.msg }]); }
        else addLog([{ type: 'dead', msg: d.error || T('บูชายัญไม่สำเร็จ') }]);
      })
      .fail(() => addLog([{ type: 'dead', msg: T('❌ บูชายัญไม่สำเร็จ (เชื่อมต่อ server ไม่ได้)') }]));
  }
  function renderCard() {
    const el = document.getElementById('card-list');
    if (!el) return;
    // แท็บ: 📖 สมุดการ์ด | 🏺 การ์ด 3 เทพ | 🔥 บูชายัญ
    //    3 แท็บใน 1 แถวที่ ~300px — ป้ายต้อง nowrap+ellipsis ไม่งั้นภาษายาว (es/pt) ดันสูงคนละแถว
    const tab = (on, lbl, fn) => `<button onclick="xhrpg._godSetTab(${fn})" style="flex:1;padding:7px 0;border:none;border-radius:9px;font-size:11.5px;font-weight:700;cursor:pointer;background:${on ? '#d97706' : '#f1f5f9'};color:${on ? '#fff' : '#64748b'};font-family:inherit;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${lbl}</button>`;
    const tabBar = `<div style="display:flex;gap:5px;margin-bottom:6px">${tab(_godTab === 0, '📖 ' + T('สมุดการ์ด'), '0')}${tab(_godTab === 1, '🏺 ' + T('การ์ด 3 เทพ'), '1')}${tab(_godTab === 2, '🔥 ' + T('บูชายัญ'), '2')}</div>`;
    const body = _godTab === 1 ? _renderGodCards()
               : _godTab === 2 ? _renderSacrifice()
               : (_renderCardBook() || '<div style="text-align:center;color:#94a3b8;padding:22px;font-size:13px">' + T('ยังไม่มีข้อมูลการ์ด — เข้าเกมสักครู่') + '</div>');
    const html = tabBar + body;
    if (el._lastHtml !== html) { el._lastHtml = html; el.innerHTML = html; }
  }

  // ── 🐾 สัตว์เลี้ยง (ฟักไข่มอนสเตอร์) — docs/pet-system-design.md ─────────────
  // Lv(UP) จาก exp สะสม — เส้นโค้งเดียวกับผู้เล่น (sync xhrpg_pet_lv ฝั่ง server) · cap 99
  function _petLvInfo(exp) {
    let lv = 1, e = Math.max(0, Math.floor(Number(exp) || 0)); // ห้าม |0 — pet_exp เป็น BIGINT สะสมตลอดชีพ เกิน 2³¹ ได้ราว Lv(UP) 42+ (|0 จะ wrap ติดลบ → โชว์ Lv1)
    while (lv < 99) { const need = expNext(lv); if (e < need) break; e -= need; lv++; }
    return { lv, cur: e, need: expNext(lv) };
  }
  function _petSlots(olv, mvp) { olv = Math.max(1, olv | 0); let s = Math.min(5, Math.ceil(olv / 20)); if (mvp) s += Math.min(3, Math.ceil(olv / 30)); return s; } // sync xhrpg_pet_card_slots
  function _eggsArr() {
    const e = player && player.eggs;
    if (e && typeof e === 'object' && !Array.isArray(e)) return e;
    try { return JSON.parse(e || '{}') || {}; } catch (_) { return {}; }
  }
  function _petCardsArr() {
    const c = player && player.pet_cards;
    if (Array.isArray(c)) return c;
    try { return JSON.parse(c || '[]') || []; } catch (_) { return []; }
  }
  // ── 🥚🔥 บูชายัญไข่ MVP (docs/egg-sacrifice-design.md) — mirror helper ฝั่ง server ─────────────
  //    sac_eggs = {"<mid>":{st:ดาว, e:pet_exp, a:up_atk, h:up_hp, r:up_reco}}
  //    🔑 **มี key = ปลดล็อกชนิดนั้นถาวร** ⇒ ไม่มีฟิลด์ปลดล็อกแยก (sync xhrpg_eggsac_unlocked)
  const EGGSAC_PER = 0.05; // sync XHRPG_EGGSAC_PER_STAR — +5%/ดาว · เต็มเพดาน SAC_MAX(30) = ×2.5
  const _eggSacObj = () => {
    const g = player && player.sac_eggs;
    if (g && typeof g === 'object' && !Array.isArray(g)) return g;
    try { return JSON.parse(g || '{}') || {}; } catch (e) { return {}; }
  };
  const _eggSacRow = (mid) => { const r = _eggSacObj()[mid]; return (r && typeof r === 'object' && !Array.isArray(r)) ? r : null; };
  const _eggSacUnl = (mid) => (mid | 0) > 0 && !!_eggSacRow(mid);                                    // 🔓 ปลดล็อกถาวรแล้ว
  const _eggSacN   = (mid) => { const r = _eggSacRow(mid); return Math.max(0, Math.min(SAC_MAX, (r && r.st) | 0)); }; // ⭐ ดาว (clamp เพดาน sync PHP)
  const _eggSacMult = (mid) => 1 + EGGSAC_PER * _eggSacN(mid);                                       // ✖️ ตัวคูณ (sync xhrpg_eggsac_mult)
  // 🐾 Pet Combat — mirror สูตร server xhrpg_pet_combat_stats (base master · MVP ×1.5 ทั้งก้อน)
  function _petCombatStats(p) {
    const batk = p.pet_batk | 0, bhp = p.pet_bhp | 0;
    if (batk < 1 || bhp < 1) return null; // รอ backfill จาก poll แรก
    const lv = _petLvInfo(p.pet_exp).lv, mvp = (+p.pet_mvp || 0) ? 2 : 1; // MVP ×2 atk/hp/def (sync PHP 2026-07-15)
    // 🥚🔥 ตัวคูณดาวบูชายัญไข่ (ผูกกับ "ชนิดมอน" ไม่ใช่ตัวสัตว์) — คูณ **ในวงเล็บ** 3 จุด atk/hp/def
    //    🚨 ห้ามย้ายออกนอกวงเล็บ (ATK กลาง/บัฟจะโตซ้ำสองชั้น) · 🚨 ห้ามคูณ regen (ฟื้นจริงจะกลายเป็น 6.25 เท่า)
    //    🪞 มิเรอร์เป๊ะกับ xhrpg_pet_combat_stats() ใน xhrpg_config.php — แก้ที่นั่นต้องแก้ที่นี่เสมอ
    const es = _eggSacMult(p.pet_mid | 0);
    return {
      lv,
      // ⚔️ + ATK กลาง (โมดูลทุกอาวุธ + การ์ดสู้) นอกวงเล็บ — sync PHP xhrpg_pet_combat_stats (เจ้าของสั่ง 2026-08-01)
      atk:   Math.max(1, Math.round(batk * (2 + 0.20 * lv + 0.30 * (p.pet_up_atk | 0)) * mvp * es) + _modTotalAtk() + (_cardCB().atk | 0)), // base ×2 + โตต่อ Lv ×2 · ต่อแต้ม ×3 (sync PHP)
      hpMax: Math.max(1, Math.round(0.5 * bhp * (1 + 0.25 * lv) * mvp * es)), // HP ตั้งต้น ×0.5 (ลด 1/4 · 2026-07-15) · โตตาม Lv ล้วน (25%/Lv) — ไม่มีสายอัพ (sync PHP)
      def:   Math.max(0, Math.round(((p.pet_olv | 0) + lv + 2 * (p.pet_up_hp | 0)) * mvp * es)), // (Lv.ต้นฉบับ + Lv(UP) + 2×DEF Lv.) ×mvp × 🥚 ดาว — ลดดาเมจมอนสวน (sync PHP · บัฟนักบวชฝั่ง server)
      regen: 1.0 + 0.20 * (p.pet_up_reco | 0), // % ของ HP max ต่อวินาที — 🚨 ไม่คูณดาวไข่โดยตั้งใจ (sync PHP)
      pts:   Math.max(0, (lv - 1) - (p.pet_up_atk | 0) - (p.pet_up_hp | 0) - (p.pet_up_reco | 0)),
    };
  }
  // แถวสถานะสู้ + แต้ม + ปุ่มอัพเกรด 3 สาย (แทนสกิล 4 ตัวเดิม)
  function _petCombatRows(p, mvp) {
    const st = _petCombatStats(p);
    if (!st) return `<div style="background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;padding:8px;font-size:11px;color:#94a3b8;margin-top:9px;text-align:center">${T('⏳ กำลังโหลดค่าพลังสัตว์เลี้ยง (จาก master)...')}</div>`;
    const hp = Math.max(0, Math.min(st.hpMax, p.pet_hp | 0));
    const down = !!(+p.pet_down || 0);
    const hpPct = Math.round(hp / st.hpMax * 100);
    const mul = mvp ? 1.5 : 1;
    const gAtk = Math.round((p.pet_batk | 0) * 0.30 * mul * 10) / 10; // +ATK ต่อแต้ม = batk×30%×mvp (sync PHP 0.30)
    const btn = (stat, on) => `<button onclick="xhrpg.petUpgrade('${stat}')" ${on ? '' : 'disabled'} style="width:100%;margin-top:auto;padding:4px;border:none;border-radius:6px;background:${on ? {atk:'#dc2626',hp:'#2563eb',reco:'#0d9488'}[stat] : '#e2e8f0'};color:${on ? '#fff' : '#94a3b8'};font-size:11px;font-weight:700;cursor:${on ? 'pointer' : 'default'}">${T('+ อัพ (1 แต้ม)')}</button>`; // margin-top:auto = ปักปุ่มก้นกล่อง (บรรทัดกลางยาวไม่เท่ากัน/ตัดบรรทัดบนมือถือ = ปุ่มยังตรงแถวเดียวกัน)
    return `
      <div style="display:flex;gap:5px;margin-top:9px">
        <div style="flex:1;background:#fff;border:1px solid #fecaca;border-radius:8px;padding:5px 6px;text-align:center">
          <div style="font-size:9.5px;color:#991b1b">⚔️ ATK</div><div style="font-size:15px;font-weight:800;color:#dc2626">${st.atk.toLocaleString()}</div>
        </div>
        <div style="flex:1;background:#fff;border:1px solid #bfdbfe;border-radius:8px;padding:5px 6px;text-align:center">
          <div style="font-size:9.5px;color:#1d4ed8">🛡️ DEF</div><div style="font-size:15px;font-weight:800;color:#2563eb">${st.def.toLocaleString()}</div>
        </div>
        <div style="flex:1.3;background:#fff;border:1px solid #fecaca;border-radius:8px;padding:5px 6px;text-align:center">
          <div style="font-size:9.5px;color:#991b1b">❤️ HP ${down ? '<b style="color:#dc2626">' + T('💫 สลบ') + '</b>' : ''}</div>
          <div style="font-size:14px;font-weight:800;color:${down ? '#dc2626' : '#16a34a'}">${hp.toLocaleString()} <span style="font-size:9px;color:#94a3b8">/ ${st.hpMax.toLocaleString()}</span></div>
          <div style="height:4px;background:#e2e8f0;border-radius:2px;margin-top:2px"><div style="width:${hpPct}%;height:100%;background:${down ? '#dc2626' : '#16a34a'};border-radius:2px"></div></div>
        </div>
        <div style="flex:1;background:#fff;border:1px solid #99f6e4;border-radius:8px;padding:5px 6px;text-align:center">
          <div style="font-size:9.5px;color:#0f766e">${T('💚 ฟื้น/วิ')}</div><div style="font-size:15px;font-weight:800;color:#0d9488">${st.regen.toFixed(2)}%</div>
        </div>
      </div>
      <div style="display:flex;justify-content:space-between;align-items:center;background:#fffbeb;border:1px solid #fcd34d;border-radius:8px;padding:5px 9px;margin-top:7px">
        <span style="font-size:11px;font-weight:700;color:#92400e">${T('🎯 แต้มอัพเกรด (Lv up +1)')}</span>
        <span style="display:flex;align-items:center;gap:6px">
          <span style="font-size:13px;font-weight:800;color:#b45309">${T('{a} แต้ม', {a: st.pts})}</span>
          <button onclick="xhrpg.petResetUp()" title="${T('รีเซ็ตแต้มอัพ (เลือกจ่าย G ตาม Lv / {p} P)', {p: _PET_RESET_P})}" style="font-size:9.5px;font-weight:700;color:#b45309;background:#fff;border:1px solid #f59e0b;border-radius:6px;padding:2px 7px;cursor:pointer">${T('♻️ รีเซ็ต')}</button>
        </span>
      </div>
      <div style="display:flex;gap:5px;margin-top:6px">
        <div style="flex:1;display:flex;flex-direction:column;background:#fff;border:1.5px solid #f87171;border-radius:9px;padding:6px 4px;text-align:center">
          <div style="font-size:10px;font-weight:700;color:#b91c1c">⚔️ ATK <span style="color:#64748b;font-weight:400">Lv.${p.pet_up_atk | 0}</span></div>
          <div style="font-size:8.5px;color:#64748b;margin:2px 0">${T('ATK ×{a}/แต้ม', {a: gAtk})}</div>${btn('atk', st.pts > 0)}
        </div>
        <div style="flex:1;display:flex;flex-direction:column;background:#fff;border:1.5px solid #60a5fa;border-radius:9px;padding:6px 4px;text-align:center">
          <div style="font-size:10px;font-weight:700;color:#1d4ed8">🛡️ DEF <span style="color:#64748b;font-weight:400">Lv.${p.pet_up_hp | 0}</span></div>
          <div style="font-size:8.5px;color:#64748b;margin:2px 0">${T('+2 DEF/แต้ม')}</div>${btn('hp', st.pts > 0)}
        </div>
        <div style="flex:1;display:flex;flex-direction:column;background:#fff;border:1.5px solid #2dd4bf;border-radius:9px;padding:6px 4px;text-align:center">
          <div style="font-size:10px;font-weight:700;color:#0f766e">${T('💚 ฟื้นตัว')} <span style="color:#64748b;font-weight:400">Lv.${p.pet_up_reco | 0}</span></div>
          <div style="font-size:8.5px;color:#64748b;margin:2px 0">${T('+0.20%/แต้ม')}</div>${btn('reco', st.pts > 0)}
        </div>
      </div>`;
  }
  function petUpgrade(stat) {
    if (!player || player.line_uid === 'demo') return;
    $.post(baseUrl + 'xhrpg_upgrade.php', { line_uid: player.line_uid, action: 'pet_up', stat })
      .done(res => {
        const d = typeof res === 'string' ? JSON.parse(res) : res;
        if (d.ok) { player = d.player; renderPet(); addLog([{ type: 'levelup', msg: d.msg }]); }
        else addLog([{ type: 'dead', msg: d.error || T('อัพเกรดไม่ได้') }]);
      })
      .fail(() => addLog([{ type: 'dead', msg: T('❌ อัพเกรดไม่สำเร็จ (เชื่อมต่อ server ไม่ได้)') }]));
  }
  // แถบรูการ์ดของสัตว์ — มีการ์ด = ค่า+ปุ่มถอด (10,000 G) · ว่าง = ＋ เปิด picker
  function _petSocketStrip() {
    const slots = _petSlots(player.pet_olv | 0, !!(+player.pet_mvp || 0));
    const cards = _petCardsArr();
    let tiles = '';
    for (let i = 0; i < slots; i++) {
      const c = cards[i];
      if (c) {
        const st = (c.s || '').toLowerCase(), clr = _CARD_STAT_CLR[st] || '#94a3b8', su = _CARD_STAT_LBL[st] || '?';
        const mvp = !!c.mvp, ba = (c.mb && c.mb.a) | 0, bl = _CB_LBL[(c.mb && c.mb.t) || ''] || '';
        const bonus = (mvp && ba > 0) ? `<div style="height:11px;line-height:11px;font-size:8px;font-weight:800;color:#7c3aed;white-space:nowrap;overflow:hidden;max-width:100%">+${ba} ${bl}</div>` : '<div style="height:11px"></div>';
        tiles += `<div style="position:relative;box-sizing:border-box;min-width:0;height:44px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;background:${mvp ? '#fef2f2' : '#fffdf8'};border:1px solid ${mvp ? '#dc2626' : clr};border-radius:8px;padding:2px 3px">`
          + (mvp ? `<span style="position:absolute;top:1px;left:3px;font-size:8px;line-height:1;color:#dc2626">⭐</span>` : '')
          + `<button onclick="xhrpg.petCardUnsocket(${i})" title="${T('ถอดการ์ด (เลือกจ่าย G ตาม Lv / {p} P)', {p: _PETCARD_UNSOCK_P})}" style="position:absolute;top:1px;right:1px;width:14px;height:14px;border:none;background:#fee2e2;color:#dc2626;font-size:9px;font-weight:800;border-radius:5px;padding:0;cursor:pointer;line-height:14px">✕</button>`
          + `<div style="font-size:11px;line-height:12px;font-weight:800;color:${clr};white-space:nowrap;overflow:hidden;max-width:100%">+${c.v | 0} ${su}${_sacPlusOf(c)}</div>`
          + bonus + `</div>`;
      } else {
        tiles += `<button onclick="xhrpg.petCardPickOpen()" title="${T('เสียบการ์ด')}" style="box-sizing:border-box;min-width:0;height:44px;display:flex;align-items:center;justify-content:center;font-size:16px;font-weight:700;color:#a78bfa;background:#faf5ff;border:1px dashed #a78bfa;border-radius:8px;padding:0;cursor:pointer;line-height:1">＋</button>`;
      }
    }
    // panel รูการ์ด: หัวข้อซ้าย + ตัวนับขวาบน · grid ช่องคงที่แถวละ 4 (ช่องเกิน = ขึ้นบรรทัดใหม่ เป็นระเบียบ)
    return `<div style="border:1px solid #e9d5ff;background:#faf5ff66;border-radius:10px;padding:8px 9px;margin-top:8px">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">
        <span style="font-size:11px;font-weight:700;color:#7c3aed">${T('🎴 การ์ดเสริมพลัง')}</span>
        <span style="font-size:10px;font-weight:600;color:#7c3aed;background:#f3e8ff;border-radius:5px;padding:1px 7px">${T('{a}/{b} รู', {a: Math.min(cards.length, slots), b: slots})}</span>
      </div>
      <div style="display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:4px">${tiles}</div>
    </div>`;
  }
  const _EGG_MVP_EXCHANGE_N = 100; // sync XHRPG_EGG_MVP_EXCHANGE_N — สะสมไข่ปกติ N ฟอง/มอน → แลก MVP 1 ฟอง
  // 🥚 แถบ + ปุ่ม "แลก" ใต้ช่องไข่ MVP (cnt = จำนวนไข่ปกติ) — โครงเดียวกับการ์ด
  function _eggExchStrip(mid, cnt) {
    const N = _EGG_MVP_EXCHANGE_N, ready = cnt >= N, pct = Math.min(100, Math.round(cnt / N * 100));
    return `<div style="width:100%;margin-top:3px">
      <div style="height:5px;border-radius:3px;background:#fde0e0;overflow:hidden"><div style="height:100%;width:${pct}%;background:${ready ? '#16a34a' : '#f59e0b'}"></div></div>
      <div style="font-size:8.5px;font-weight:700;text-align:center;margin-top:1px;color:${ready ? '#16a34a' : '#b45309'}">${cnt}/${N}${ready ? ' ✓' : ''}</div>
      <button onclick="event.stopPropagation();xhrpg.eggMvpExchange(${mid})" style="width:100%;margin-top:4px;padding:3px 0;border:none;border-radius:6px;background:${ready ? '#16a34a' : '#dc2626'};color:#fff;font-size:9.5px;font-weight:800;cursor:pointer;line-height:1.4">${T('🔄 แลก')}</button>
    </div>`;
  }
  function eggMvpExchange(mid) {
    const eggs = _eggsArr(), own = eggs[mid] || {}, nN = own.n | 0, N = _EGG_MVP_EXCHANGE_N;
    const mm = monMasters[mid] || {}, nm = T(mm.n || '');
    const ready = nN >= N, left = nN - N, short = N - nN, pct = Math.min(100, Math.round(nN / N * 100));
    const sb = _monSpriteBg(mm.lv || 1), D = 30;
    const artHtml = sb
      ? `<div style="width:${D}px;height:${D}px;margin:0 auto;background:url('${sb.url}') 0 0/${sb.cols * D}px ${sb.rows * D}px no-repeat;image-rendering:pixelated"></div>`
      : `<div style="font-size:26px;line-height:1">${mm.e || '👾'}</div>`;
    const barHtml = `<div style="margin:2px 0 10px">
      <div style="height:8px;border-radius:4px;background:#f1f5f9;overflow:hidden"><div style="height:100%;width:${pct}%;background:${ready ? '#16a34a' : '#f59e0b'}"></div></div>
      <div style="font-size:11px;font-weight:700;text-align:center;margin-top:3px;color:${ready ? '#16a34a' : '#b45309'}">${nN}/${N}${ready ? ' ✓' : ''}</div></div>`;
    const body = ready
      ? `<div style="display:flex;align-items:center;justify-content:center;gap:10px;margin:2px 0 10px">
          <div style="text-align:center"><span style="font-size:18px">🥚</span>${artHtml}<div style="font-size:11px;font-weight:700;margin-top:2px;color:#334155">${nm} ×${N}</div><div style="font-size:9.5px;color:#94a3b8">${T('ไข่ปกติ')}</div></div>
          <div style="font-size:20px;color:#94a3b8">➜</div>
          <div style="text-align:center"><span style="font-size:18px">🥚</span>${artHtml}<div style="font-size:11px;font-weight:700;margin-top:2px;color:#dc2626">${T('⭐MVP')} ×1</div></div>
        </div>
        ${barHtml}
        <div style="background:#fffbeb;border:1px solid #fde68a;border-radius:9px;padding:7px 9px;font-size:11px;color:#92400e;text-align:center;line-height:1.5;margin-bottom:12px">${T('ใช้ไข่ปกติ {a} ฟอง → เหลือ {b} ฟอง', {a: N, b: left})}</div>
        <div style="display:flex;gap:8px">
          <button onclick="xhrpg._eggMvpExClose()" style="flex:1;padding:9px 0;border:none;border-radius:9px;background:#e2e8f0;color:#475569;font-size:12.5px;font-weight:700;cursor:pointer">${T('ยกเลิก')}</button>
          <button onclick="xhrpg._eggMvpExGo(${mid})" style="flex:1;padding:9px 0;border:none;border-radius:9px;background:#dc2626;color:#fff;font-size:12.5px;font-weight:700;cursor:pointer">${T('✅ แลกเลย')}</button>
        </div>`
      : `<div style="text-align:center;margin:2px 0 8px"><span style="font-size:18px">🥚</span>${artHtml}<div style="font-size:12px;font-weight:700;margin-top:3px;color:#334155">${nm}</div></div>
        ${barHtml}
        <div style="background:#fef2f2;border:1px solid #fecaca;border-radius:9px;padding:8px 9px;font-size:11.5px;color:#b91c1c;text-align:center;line-height:1.6;margin-bottom:12px">${T('ยังแลกไม่ได้ — ต้องสะสมให้ครบ {a} ฟองก่อน', {a: N})}<br><b style="font-size:13px">${T('มี {a} ฟอง · ขาดอีก {b} ฟอง', {a: nN, b: short})}</b></div>
        <button onclick="xhrpg._eggMvpExClose()" style="width:100%;padding:9px 0;border:none;border-radius:9px;background:#dc2626;color:#fff;font-size:12.5px;font-weight:700;cursor:pointer">${T('เข้าใจแล้ว')}</button>`;
    const el = document.createElement('div');
    el.id = 'egg-mvpex-modal';
    el.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,.55);z-index:10004;display:flex;align-items:center;justify-content:center;padding:16px';
    el.innerHTML = `<div style="background:#fff;border-radius:16px;width:280px;max-width:100%;overflow:hidden;box-shadow:0 12px 40px rgba(2,8,23,.35)">
      <div style="background:#dc2626;color:#fff;padding:14px 16px 12px;text-align:center">
        <div style="font-size:30px;line-height:1">🔄</div><div style="font-size:15px;font-weight:800;margin-top:4px">${T('แลกไข่ ⭐MVP')}</div></div>
      <div style="padding:14px 16px 16px">${body}</div></div>`;
    el.addEventListener('click', e => { if (e.target === el) _eggMvpExClose(); });
    document.body.appendChild(el);
  }
  function _eggMvpExClose() { const el = document.getElementById('egg-mvpex-modal'); if (el) el.remove(); }
  function _eggMvpExGo(mid) {
    _eggMvpExClose();
    $.post(baseUrl + 'xhrpg_upgrade.php', {line_uid: player.line_uid, action: 'egg_mvp_exchange', mid, lang: LANG(), session_token: sessionToken || ''}).done(res => {
      const d = typeof res === 'string' ? JSON.parse(res) : res;
      if (d.ok) { player = d.player; renderPet(); updateHUD(); addLog([{type:'levelup', msg: d.msg}]); }
      else addLog([{type:'dead', msg: d.error || T('แลกไข่ไม่สำเร็จ')}]);
    }).fail(() => addLog([{type:'dead', msg: T('แลกไข่ไม่สำเร็จ')}]));
  }

  function _renderEggBook() {
    const eggs = _eggsArr();
    const ids = Object.keys(monMasters).sort((a, b) => ((monMasters[a].lv || 0) - (monMasters[b].lv || 0)) || (+a - +b));
    if (!ids.length) return '';
    let ownN = 0, ownM = 0, cells = '';
    const busy = (player.pet_mid | 0) > 0;
    const cell = (mm, mvp, cnt, id) => {
      // 🥚🔥 ปลดล็อกชนิดนี้ด้วยการบูชายัญไข่แล้ว ⇒ ฟักฟรีจาก **ช่อง MVP** ได้ตลอด แม้ไข่หมดคลัง
      //    server บังคับให้เส้นทางนี้เป็น ⭐MVP เสมอ (จ่ายด้วยไข่ MVP ไปแล้วตอนปลดล็อก · ดู pet_hatch)
      //    ⇒ ช่องไข่ "ปกติ" ของชนิดที่ปลดล็อกแล้วจึงไม่ให้กดฟัก — กันงงว่ากดแล้วทำไมได้ MVP ฟรีทั้งที่ป้ายบอกราคา
      const unl  = _eggSacUnl(+id);
      const free = mvp && unl;                       // 🔓 ฟักฟรี
      const canH = free || (cnt > 0 && !unl);        // กดฟักได้ไหม
      const has  = cnt > 0 || free, D = mvp ? 40 : 32;
      const sb = _monSpriteBg(mm.lv || 1);
      const cost = free ? 0 : (mm.lv || 1) * 100 * (mvp ? 10 : 1);
      const art = sb
        ? `<div style="width:${D}px;height:${D}px;background:url('${sb.url}') 0 0/${sb.cols * D}px ${sb.rows * D}px no-repeat;image-rendering:pixelated;${has ? '' : 'filter:grayscale(1);opacity:.5'}"></div>`
        : `<div style="font-size:${mvp ? 24 : 20}px;line-height:1;${has ? '' : 'filter:grayscale(1);opacity:.5'}">${mm.e || '👾'}</div>`;
      const click = canH ? `onclick="xhrpg.petHatchAsk(${id},${mvp ? 1 : 0})" ` : '';
      return `<div ${click}style="border:${mvp ? '1.5px' : '1px'} solid ${has ? (mvp ? '#dc2626' : '#0f766e') : '#e5e7eb'};border-radius:9px;padding:5px 3px 6px;background:${has ? (mvp ? '#fef2f2' : '#fff') : '#f8fafc'};opacity:${(has || mvp) ? 1 : 0.6};position:relative;display:flex;flex-direction:column;align-items:center;${has ? 'cursor:pointer' : ''}">
        ${mvp ? `<span style="position:absolute;top:3px;left:4px;font-size:8px;font-weight:800;color:#fff;background:#dc2626;padding:0 4px;border-radius:4px">MVP</span>` : ''}
        <span style="position:absolute;top:3px;right:4px;font-size:8px;font-weight:700;color:#64748b;background:#eef2f7;padding:0 3px;border-radius:4px">Lv.${mm.lv || 1}</span>
        ${cnt > 1 ? `<span style="position:absolute;top:16px;right:5px;font-size:9px;font-weight:700;color:${mvp ? '#dc2626' : '#0f766e'}">×${cnt}</span>` : ''}
        <span style="position:absolute;bottom:26px;left:4px;font-size:11px">🥚</span>
        <div style="height:44px;display:flex;align-items:center;justify-content:center">${art}</div>
        <div style="width:100%;height:12px;line-height:12px;font-size:9.5px;color:${mvp ? '#b91c1c' : '#475569'};white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-align:center">${T(mm.n || '')}</div>
        <div style="height:13px;line-height:13px;font-size:9px;font-weight:600;color:${free ? '#b91c1c' : (canH ? '#b45309' : '#cbd5e1')};white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${free ? '🔓 ' + T('ฟักฟรี') : (canH ? '🐣 ' + cost.toLocaleString() + ' G' : (unl ? '🔓 ' + T('ฟักที่ช่อง MVP') : '—'))}</div>
        ${canH ? `<button onclick="event.stopPropagation();xhrpg.petHatchAsk(${id},${mvp ? 1 : 0})" style="width:100%;margin-top:3px;padding:3px 0;border:none;border-radius:6px;background:${free ? '#b91c1c' : '#0f766e'};color:#fff;font-size:9.5px;font-weight:800;cursor:pointer;line-height:1.4">${free ? '🔓 ' + T('ฟักฟรี') : '🐣 ' + T('ฟักไข่')}</button>` : ''}
        ${mvp ? _eggExchStrip(+id, (eggs[id]||{}).n|0) : ''}
      </div>`;
    };
    ids.forEach(id => {
      const mm = monMasters[id], own = eggs[id] || {}, nN = own.n | 0, nM = own.m | 0;
      if (nN > 0) ownN++; if (nM > 0) ownM++;
      cells += cell(mm, false, nN, id) + cell(mm, true, nM, id);
    });
    const _eCollB = ownN * 1 + ownM * 3; // ✨ โบนัสสะสมไข่ → ATK/DEF/HP/MP · ปกติ +1 · MVP +3 (sync xhrpg_collection_cb)
    return `<div class="treasure-panel" style="margin-top:4px;border-top:none;padding-top:0">
      <div class="treasure-header">${T('🥚 สมุดสะสมไข่')} <span class="treasure-count">${ownN}/${ids.length} · MVP ${ownM}/${ids.length}</span></div>
      <div style="font-size:11px;color:#b91c1c;text-align:center;font-weight:600;margin:3px 0 1px">${T('🔄 ไข่ปกติ {a} ฟอง = ไข่ ⭐MVP 1 ฟอง', {a: _EGG_MVP_EXCHANGE_N})} <span style="font-weight:400;color:#94a3b8">· ${T('กดปุ่มแลกที่ไข่ MVP')}</span></div>
      ${_eCollB > 0 ? `<div style="background:#ede9fe;border:1px solid #7c3aed;border-radius:9px;padding:7px 10px;margin:4px 0 2px;font-size:12.5px;color:#5b21b6;text-align:center;font-weight:700">${T('✨ โบนัสสะสมไข่:')} <b style="color:#7c3aed;font-size:14px">+${_eCollB}</b> ${T('ทั้ง ATK/DEF/HP/MP')} <span style="font-size:10px;font-weight:500;color:#7c3aed">${T('(ปกติ {n} · MVP {m})', {n: ownN, m: ownM})}</span></div>` : ''}
      <div style="font-size:10.5px;color:#78716c;margin:2px 0 4px">${T('ดรอปจากการกำจัดมอน/MVP · กดไข่ที่มีเพื่อฟัก (Lv.มอน × 100 G · MVP ×10)')}${busy ? ' · <b style="color:#b45309">' + T('มีสัตว์ฟักอยู่ — เก็บเข้าไข่ก่อนจึงฟักตัวใหม่ได้') + '</b>' : ''}</div>
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(70px,1fr));gap:5px;padding:3px 0">${cells}</div>
    </div>`;
  }
  // ── 🏺 สัตว์เทพ (Divine Pet · docs/divine-pet-design.md) — แท็บ 2 ในเมนู PET ──
  //    ⚠️ _dvTab เป็น **ตัวเลข 3 ค่า** (เดิมเป็น boolean) — 0 = 🐾 สัตว์เลี้ยง · 1 = 🏺 สัตว์เทพ · 2 = 🥚🔥 บูชายัญไข่
  //       ปุ่มเดิมส่ง 0/1 มาอยู่แล้ว จึงไม่ต้องแก้ onclick · เทียบด้วย === เสมอ (ห้ามใช้ truthiness เพราะ 0 กับ 2 ต่างกัน)
  let _dvTab = 0;
  const DV_BASE = { hp: 183000, atk: 2748, def: 372 }; // sync PHP XHRPG_DV_BASE_* (MVP Lv.60 ×3 · เจ้าของสั่ง 2026-07-22)
  const DV_EGG_MAX_LV = 50, DV_SLOTS = 8, DV_EGG_COST = 3, DV_CHAIN_MULT = 6; // sync XHRPG_DV_EGG_MAX_LV / CARD_SLOTS(4→8 · 2026-07-23) / EGG_COST / CHAIN_MULT (×6)
  function _dvLvInfo(expRaw) { // เกณฑ์ = เส้นฮีโร่ ×10 · cap 99 (sync xhrpg_dv_lv)
    let e = Math.max(0, parseInt(expRaw) || 0), lv = 1;
    while (lv < 99) { const need = expNextHero(lv) * 10; if (e < need) break; e -= need; lv++; }
    return { lv, cur: e, need: expNextHero(lv) * 10 };
  }
  function _dvStatsC() { // mirror xhrpg_dv_stats (PHP)
    const p = player || {};
    const lv = _dvLvInfo(p.dv_exp).lv, g = 1 + 0.02 * (lv - 1);
    return { lv,
      // ⚔️ × 🌟 Ragnalok ATK (รวม 🏺 การ์ดเทพ) — มิเรอร์ xhrpg_dv_stats() ที่เพิ่ม 2026-08-11
      atk:    Math.max(1, Math.round(DV_BASE.atk * (g + 0.10 * (p.dv_up_atk | 0)) * _ragMult('atk'))),
      hp_max: Math.max(1, Math.round(DV_BASE.hp * (g + 0.05 * (p.dv_up_hp | 0)))),
      def:    Math.max(0, Math.round(DV_BASE.def * g) + 2 * (p.dv_up_hp | 0)),
      regen:  1 + 0.2 * (p.dv_up_reco | 0),
      pts:    Math.max(0, (lv - 1) - (p.dv_up_atk | 0) - (p.dv_up_hp | 0) - (p.dv_up_reco | 0)) };
  }
  function _dvAllStatC() { // ALL STAT effective รวม 6 ค่า (sync xhrpg_dv_allstat — *_eff จาก server)
    let s = 0; ['str','agi','vit','dex','intel','luk'].forEach(k => { s += (player[k + '_eff'] ?? player[k] ?? 5) | 0; });
    return s;
  }
  function _dvChainDmgC() { // mirror xhrpg_dv_chain_dmg — เลขโชว์แผง (× CHAIN_MULT 3)
    const lv = _dvLvInfo(player?.dv_exp).lv;
    return Math.max(1, Math.round((_dvAllStatC() + _modTotalAtk() + ((_cardCB().atk) | 0)) * (1 + 0.01 * lv) * _ragMult('atk') * DV_CHAIN_MULT));
  }
  function _dvCardsArrC() { const c = player && player.dv_cards; return Array.isArray(c) ? c : (typeof c === 'string' ? (JSON.parse(c || '[]') || []) : []); }
  function _dvSocketStrip() { // การ์ด DV_SLOTS ช่อง (โครงเดียวกับ _petSocketStrip · grid 4 คอลัมน์ → 8 ช่อง = 2 แถว)
    const cards = _dvCardsArrC();
    let tiles = '';
    for (let i = 0; i < DV_SLOTS; i++) {
      const c = cards[i];
      if (c) {
        const st = (c.s || '').toLowerCase(), clr = _CARD_STAT_CLR[st] || '#94a3b8', su = _CARD_STAT_LBL[st] || '?';
        const mvp = !!c.mvp, ba = (c.mb && c.mb.a) | 0, bl = _CB_LBL[(c.mb && c.mb.t) || ''] || '';
        const bonus = (mvp && ba > 0) ? `<div style="height:11px;line-height:11px;font-size:8px;font-weight:800;color:#7c3aed;white-space:nowrap;overflow:hidden;max-width:100%">+${ba} ${bl}</div>` : '<div style="height:11px"></div>';
        tiles += `<div style="position:relative;box-sizing:border-box;min-width:0;height:44px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;background:${mvp ? '#fef2f2' : '#fffdf8'};border:1px solid ${mvp ? '#dc2626' : clr};border-radius:8px;padding:2px 3px">`
          + (mvp ? `<span style="position:absolute;top:1px;left:3px;font-size:8px;line-height:1;color:#dc2626">⭐</span>` : '')
          + `<button onclick="xhrpg.dvCardUnsocket(${i})" title="${T('ถอดการ์ด (เลือกจ่าย G ตาม Lv / {p} P)', {p: _PETCARD_UNSOCK_P})}" style="position:absolute;top:1px;right:1px;width:14px;height:14px;border:none;background:#fee2e2;color:#dc2626;font-size:9px;font-weight:800;border-radius:5px;padding:0;cursor:pointer;line-height:14px">✕</button>`
          + `<div style="font-size:11px;line-height:12px;font-weight:800;color:${clr};white-space:nowrap;overflow:hidden;max-width:100%">+${c.v | 0} ${su}${_sacPlusOf(c)}</div>`
          + bonus + `</div>`;
      } else {
        tiles += `<button onclick="xhrpg.dvCardPickOpen()" title="${T('เสียบการ์ด')}" style="box-sizing:border-box;min-width:0;height:44px;display:flex;align-items:center;justify-content:center;font-size:16px;font-weight:700;color:#d97706;background:#fffbeb;border:1px dashed #f59e0b;border-radius:8px;padding:0;cursor:pointer;line-height:1">＋</button>`;
      }
    }
    return `<div style="border:1px solid #fde68a;background:#fffbeb99;border-radius:10px;padding:8px 9px;margin-top:8px">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">
        <span style="font-size:11px;font-weight:700;color:#b45309">${T('🎴 การ์ดเสริมพลัง')}</span>
        <span style="font-size:10px;font-weight:600;color:#b45309;background:#fef3c7;border-radius:5px;padding:1px 7px">${T('{a}/{b} รู', {a: Math.min(cards.length, DV_SLOTS), b: DV_SLOTS})}</span>
      </div>
      <div style="display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:4px">${tiles}</div>
    </div>`;
  }
  function _renderDivine() { // เนื้อหาแท็บสัตว์เทพ
    const awake = (player && +player.dv_pet | 0) > 0;
    // แถวล็อก Horus/Medusa (เต็มบรรทัด · เทา)
    const lockedRows = [['dv_horus', 'Horus'], ['dv_medusa', 'Medusa']].map(([k, n]) =>
      `<div style="border:1px solid #e2e8f0;border-radius:12px;background:#f8fafc;padding:8px 12px;display:flex;align-items:center;gap:10px;margin-top:8px">
        <img src="${baseUrl}assets/pets/${k}.png" style="width:40px;height:40px;border-radius:10px;background:#e2e8f0;filter:grayscale(1);opacity:.5" alt="">
        <div style="min-width:0"><div style="font-size:12.5px;color:#94a3b8;font-weight:600">${n}</div><div style="font-size:10px;color:#cbd5e1">??? · ${T('เร็วๆ นี้')}</div></div>
        <span style="margin-left:auto;font-size:14px;color:#cbd5e1">🔒</span>
      </div>`).join('');
    if (!awake) {
      // ความคืบหน้าไข่ MVP: มอนทุกชนิด Lv ≤ 50 ชนิดละ ≥1 ฟอง
      const eggs = _eggsArr();
      const needList = Object.keys(monMasters).map(k => monMasters[k] && { id: +k, lv: monMasters[k].lv | 0, n: monMasters[k].n || '' })
        .filter(m => m && m.lv >= 1 && m.lv <= DV_EGG_MAX_LV);
      const missing = needList.filter(m => (((eggs[m.id] || {}).m) | 0) < DV_EGG_COST); // ต้องมีชนิดละ ≥3
      const have = needList.length - missing.length, ready = needList.length > 0 && missing.length === 0;
      const pct = needList.length ? Math.round(have / needList.length * 100) : 0;
      const missTxt = missing.slice(0, 3).map(m => `${T(m.n)} (${((eggs[m.id] || {}).m) | 0}/${DV_EGG_COST})`).join(' · ') + (missing.length > 3 ? ` … +${missing.length - 3}` : '');
      return `<div style="border:2px solid #f59e0b;border-radius:12px;background:#fffbeb;padding:11px 12px">
        <div style="display:flex;gap:10px;align-items:center">
          <img src="${baseUrl}assets/pets/dv_anubis.png" style="width:56px;height:56px;border-radius:12px;background:#1e293b" alt="">
          <div style="min-width:0">
            <div style="font-size:14px;font-weight:700;color:#78350f">Anubis <span style="font-size:10px;background:#fbbf24;color:#78350f;border-radius:6px;padding:1px 6px">${T('เทพอียิปต์')}</span></div>
            <div style="font-size:10.5px;color:#92400e;margin-top:2px">${T('⚔️ จู่โจมมอนอัตโนมัติ')}</div>
            <div style="font-size:10.5px;color:#92400e">${T('⚡ Chain Lightning กระจาย {n} ตัว · 🎴 ใส่การ์ดได้ {s} ช่อง', {n: 8, s: DV_SLOTS})}</div>
          </div>
        </div>
        <div style="margin-top:9px;background:#fff;border-radius:9px;padding:8px 10px;border:1px solid #fcd34d">
          <div style="display:flex;justify-content:space-between;font-size:11px;color:#92400e">
            <span>${T('🥚⭐ ไข่ MVP Lv.1-{a} (ทุกชนิด · ชนิดละ {c})', {a: DV_EGG_MAX_LV, c: DV_EGG_COST})}</span>
            <span style="font-weight:700">${have}/${needList.length} ${T('ชนิด')}</span>
          </div>
          <div style="height:8px;background:#fde68a;border-radius:4px;margin-top:5px;overflow:hidden"><div style="width:${pct}%;height:100%;background:${ready ? '#16a34a' : '#f59e0b'}"></div></div>
          ${missing.length ? `<div style="font-size:9.5px;color:#b45309;margin-top:4px">${T('ขาด:')} ${missTxt}</div>` : ''}
        </div>
        <button onclick="xhrpg.dvAwaken()" ${ready ? '' : 'disabled'} style="width:100%;margin-top:8px;text-align:center;padding:9px 0;border-radius:9px;border:none;background:${ready ? '#d97706' : '#d6d3d1'};color:${ready ? '#fff' : '#78716c'};font-size:13px;font-weight:700;cursor:${ready ? 'pointer' : 'default'}">${ready ? T('🏺⚡ ปลุก Anubis!') : T('🔒 สะสมไข่ให้ครบเพื่อปลุก')}</button>
      </div>` + lockedRows;
    }
    // ปลุกแล้ว — Lv/EXP + พลัง + การ์ด + แต้มอัพ + toggle
    const info = _dvLvInfo(player.dv_exp), st = _dvStatsC();
    const pct = Math.max(0, Math.min(100, Math.round(info.cur / Math.max(1, info.need) * 100)));
    const hpC = Math.max(0, Math.min(st.hp_max, parseInt(player.dv_hp) || 0));
    const down = !!(+player.dv_down || 0), on = (parseInt(player.dv_on ?? 1) || 0) === 1;
    const chain = _dvChainDmgC();
    const hpPct = Math.round(hpC / Math.max(1, st.hp_max) * 100);
    // ค่าโตต่อแต้ม (sync _dvStatsC): atk +10% ฐาน · hp +5% ฐาน & +2 DEF · reco +0.20%
    const gAtk = Math.round(DV_BASE.atk * 0.10), gHp = Math.round(DV_BASE.hp * 0.05);
    // ปุ่มอัพ mirror _petCombatRows (margin-top:auto ปักก้นกล่อง — มือถือบรรทัดตัดไม่เท่ากันปุ่มยังตรงแถว ไม่เบียดกัน) · ธีมทอง Anubis (เจ้าของเคาะ ไม่ใช้สีสาย PET)
    const dvBtn = (stat, on) => `<button onclick="xhrpg.dvUp('${stat}')" ${on ? '' : 'disabled'} style="width:100%;margin-top:auto;padding:4px;border:none;border-radius:6px;background:${on ? '#d97706' : '#e2e8f0'};color:${on ? '#fff' : '#94a3b8'};font-size:11px;font-weight:700;cursor:${on ? 'pointer' : 'default'}">${T('+ อัพ (1 แต้ม)')}</button>`;
    return `<div style="border:2px solid #f59e0b;border-radius:12px;background:#fffbeb;padding:11px 12px">
      <div style="display:flex;gap:10px;align-items:center">
        <img src="${baseUrl}assets/pets/dv_anubis.png" style="width:56px;height:56px;border-radius:12px;background:#1e293b;${down ? 'filter:grayscale(.7);opacity:.7' : ''}" alt="">
        <div style="flex:1;min-width:0">
          <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap">
            <span style="font-size:14px;font-weight:700;color:#78350f">Anubis</span>
            <span style="font-size:11px;background:#7c3aed;color:#fff;border-radius:6px;padding:1px 7px;font-weight:700">Lv.${info.lv}</span>
            <span style="font-size:9.5px;background:#fee2e2;color:#991b1b;border-radius:6px;padding:1px 6px">⭐ ${T('ระดับ MVP Lv.60')}${info.lv > 1 ? '+' : ''}</span>
            ${down ? `<span style="font-size:9.5px;background:#fef3c7;color:#b45309;border-radius:6px;padding:1px 6px">💫 ${T('สลบ — พักฟื้น')}</span>` : ''}
          </div>
          <div style="height:8px;background:#fde68a;border-radius:4px;margin-top:6px;overflow:hidden"><div style="width:${info.lv >= 99 ? 100 : pct}%;height:100%;background:#f59e0b"></div></div>
          <div style="display:flex;justify-content:space-between;font-size:9.5px;color:#b45309;margin-top:3px">
            <span>EXP ${info.cur.toLocaleString()} / ${info.need.toLocaleString()}</span>
          </div>
        </div>
      </div>
      <div style="display:flex;gap:5px;margin-top:9px">
        <div style="flex:1;background:#fff;border:1px solid #fcd34d;border-radius:8px;padding:5px 6px;text-align:center">
          <div style="font-size:9.5px;color:#92400e">⚔️ ATK</div><div style="font-size:15px;font-weight:800;color:#78350f">${st.atk.toLocaleString()}</div>
        </div>
        <div style="flex:1;background:#fff;border:1px solid #fcd34d;border-radius:8px;padding:5px 6px;text-align:center">
          <div style="font-size:9.5px;color:#92400e">🛡️ DEF</div><div style="font-size:15px;font-weight:800;color:#78350f">${st.def.toLocaleString()}</div>
        </div>
        <div style="flex:1.3;background:#fff;border:1px solid #fcd34d;border-radius:8px;padding:5px 6px;text-align:center">
          <div style="font-size:9.5px;color:#92400e">❤️ HP ${down ? '<b style="color:#dc2626">' + T('💫 สลบ') + '</b>' : ''}</div>
          <div style="font-size:14px;font-weight:800;color:${down ? '#dc2626' : '#16a34a'}">${hpC.toLocaleString()} <span style="font-size:9px;color:#94a3b8">/ ${st.hp_max.toLocaleString()}</span></div>
          <div style="height:4px;background:#e2e8f0;border-radius:2px;margin-top:2px"><div style="width:${hpPct}%;height:100%;background:${down ? '#dc2626' : '#16a34a'};border-radius:2px"></div></div>
        </div>
        <div style="flex:1;background:#fff;border:1px solid #fcd34d;border-radius:8px;padding:5px 6px;text-align:center">
          <div style="font-size:9.5px;color:#92400e">${T('💚 ฟื้น/วิ')}</div><div style="font-size:15px;font-weight:800;color:#78350f">${st.regen.toFixed(2)}%</div>
        </div>
      </div>
      <div style="margin-top:8px;background:#fff;border-radius:9px;padding:8px 10px;border:1px solid #fcd34d">
        <div style="font-size:11.5px;font-weight:700;color:#78350f">⚡ Chain Lightning <span style="font-size:9.5px;color:#b45309;font-weight:400">${T('ทุกจังหวะ · กระจาย {n} ตัว', {n: 8})}</span></div>
        <div style="display:flex;gap:6px;margin-top:6px">
          <span style="flex:1;text-align:center;background:#fef3c7;border-radius:7px;padding:5px 0;font-size:10px;color:#92400e">${T('DMG สายฟ้า')}<br><b style="font-size:12px">${chain.toLocaleString()}</b></span>
          <span style="flex:1;text-align:center;background:#fef3c7;border-radius:7px;padding:5px 0;font-size:10px;color:#92400e">ALL STAT<br><b style="font-size:12px">${_dvAllStatC().toLocaleString()}</b></span>
          <span style="flex:1;text-align:center;background:#fef3c7;border-radius:7px;padding:5px 0;font-size:10px;color:#92400e">${T('โบนัส Lv')}<br><b style="font-size:12px">+${info.lv}%</b></span>
        </div>
      </div>
      <div style="display:flex;justify-content:space-between;align-items:center;background:#fffbeb;border:1px solid #fcd34d;border-radius:8px;padding:5px 9px;margin-top:7px">
        <span style="font-size:11px;font-weight:700;color:#92400e">${T('🎯 แต้มอัพเกรด (Lv up +1)')}</span>
        <span style="display:flex;align-items:center;gap:6px">
          <span style="font-size:13px;font-weight:800;color:#b45309">${T('{a} แต้ม', {a: st.pts})}</span>
          <button onclick="xhrpg.dvResetUp()" title="${T('รีเซ็ตแต้มอัพ (เลือกจ่าย G ตาม Lv / {p} P)', {p: _PET_RESET_P})}" style="font-size:9.5px;font-weight:700;color:#b45309;background:#fff;border:1px solid #f59e0b;border-radius:6px;padding:2px 7px;cursor:pointer">${T('♻️ รีเซ็ต')}</button>
        </span>
      </div>
      <div style="display:flex;gap:5px;margin-top:6px">
        <div style="flex:1;display:flex;flex-direction:column;background:#fff;border:1.5px solid #fbbf24;border-radius:9px;padding:6px 4px;text-align:center">
          <div style="font-size:10px;font-weight:700;color:#92400e">⚔️ ATK <span style="color:#64748b;font-weight:400">Lv.${player.dv_up_atk | 0}</span></div>
          <div style="font-size:8.5px;color:#64748b;margin:2px 0">${T('+{a} ATK/แต้ม', {a: gAtk.toLocaleString()})}</div>${dvBtn('atk', st.pts > 0)}
        </div>
        <div style="flex:1;display:flex;flex-direction:column;background:#fff;border:1.5px solid #fbbf24;border-radius:9px;padding:6px 4px;text-align:center">
          <div style="font-size:10px;font-weight:700;color:#92400e">❤️ HP <span style="color:#64748b;font-weight:400">Lv.${player.dv_up_hp | 0}</span></div>
          <div style="font-size:8.5px;color:#64748b;margin:2px 0">${T('+{a} HP · +2 DEF/แต้ม', {a: gHp.toLocaleString()})}</div>${dvBtn('hp', st.pts > 0)}
        </div>
        <div style="flex:1;display:flex;flex-direction:column;background:#fff;border:1.5px solid #fbbf24;border-radius:9px;padding:6px 4px;text-align:center">
          <div style="font-size:10px;font-weight:700;color:#92400e">${T('💚 ฟื้นตัว')} <span style="color:#64748b;font-weight:400">Lv.${player.dv_up_reco | 0}</span></div>
          <div style="font-size:8.5px;color:#64748b;margin:2px 0">${T('+0.20%/แต้ม')}</div>${dvBtn('reco', st.pts > 0)}
        </div>
      </div>
      ${_dvSocketStrip()}
      ${_dvCardPickerHtml()}
      <!-- 🔘 ปุ่มเปิด/ปิด — ใช้ _gunToggleBtn ตัวเดียวกับผู้ติดตามคนอื่น (นักบวช/อัศวิน/นักธนู)
           เจ้าของสั่ง 2026-08-13 "ให้เหมือนกับผู้ติดตามคนอื่นๆ" — เดิมเป็นปุ่มเขียวเต็มความกว้างคนละแบบ
           ⚠️ ใช้คีย์ 'ใช้งาน' ตัวเดียวกับของเดิม ⇒ ไม่ต้องเพิ่มคำแปลใหม่ และแปลครบ 7 ภาษาอยู่แล้ว -->
      <div style="margin-top:8px">${_gunToggleBtn('ใช้งาน', on ? 1 : 0, "xhrpg.dvToggle()")}</div>
    </div>` + lockedRows;
  }
  function _dvSetTab(on) { _dvTab = on | 0; _dvCardPick = false; renderPet(); } // สลับแท็บ = ปิดแผงเลือกการ์ดด้วย ไม่งั้นค้างข้ามแท็บ (⚠️ ต้องคงบรรทัด _dvCardPick ไว้)
  function dvAwaken() { _petPost('dv_awaken', {}); }
  function dvUp(stat) { _petPost('dv_up', { stat }); }
  function dvToggle() { _petPost('dv_toggle', {}); }
  function dvCardUnsocket(sidx) { _petCardUnsockOpen('dv', sidx | 0); }
  function dvCardSocket(mid, mvp) {
    _dvCardPick = false;   // ปิดแผงเลือกทันที (renderPet จะถูกเรียกใน _petPost หลัง server ตอบ)
    _petPost('dv_card_socket', { mid: mid | 0, mvp: mvp ? 1 : 0 });
  }
  // 🏺🎴 เลือกการ์ดเสียบ Anubis — **แผงในหน้า** โครงเดียวกับ picker ของโมดูล (_cardPickerHtml)
  //    เจ้าของสั่ง 2026-08-05: ของเดิมเป็น popup เต็มจอเด้งทับ ผู้เล่นงงว่าอยู่หน้าไหน
  //    ⚠️ เปิด/ปิดผ่าน state + renderPet() เท่านั้น ห้ามสร้าง element ลอยเอง (ไม่งั้นค้างหลังสลับแท็บ)
  let _dvCardPick = false;
  function dvCardPickOpen()  { _dvCardPick = true;  _cpReset(); renderPet(); }
  function dvCardPickClose() { _dvCardPick = false; renderPet(); }
  function _dvCardPickerHtml() {
    if (!_dvCardPick) return '';
    const cards = (player.cards && typeof player.cards === 'object' && !Array.isArray(player.cards)) ? player.cards
                : (() => { try { return JSON.parse(player.cards || '{}') || {}; } catch (e) { return {}; } })();
    let cells = '', _cpShow = 0, _cpTot = 0;
    Object.keys(cards).filter(id => monMasters[id] && (((cards[id] || {}).n | 0) > 0 || ((cards[id] || {}).m | 0) > 0))
      .sort((a, b) => ((monMasters[a].lv || 0) - (monMasters[b].lv || 0)) || (+a - +b))
      .forEach(id => {
        const mm = monMasters[id], o = cards[id] || {};
        [['n', false], ['m', true]].forEach(([k, mvp]) => {
          const cnt = o[k] | 0; if (cnt <= 0) return;
          _cpTot++; if (!_cpPass(mm, id, mvp)) return; _cpShow++; // 🔎 ตัวกรอง — นับยอดรวมก่อนกรองเสมอ
          const st = (mm.cs || '').toLowerCase(), clr = _CARD_STAT_CLR[st] || '#94a3b8', su = _CARD_STAT_LBL[st] || '?', v = _cardValue(mm.lv || 1, mvp);
          const sb = _monSpriteBg(mm.lv || 1);
          const art = sb
            ? `<div style="width:28px;height:28px;background:url('${sb.url}') 0 0/${sb.cols * 28}px ${sb.rows * 28}px no-repeat;image-rendering:pixelated"></div>`
            : `<div style="font-size:20px;line-height:1">${mm.e || '👾'}</div>`;
          cells += `<button onclick="xhrpg.dvCardSocket(${+id},${mvp ? 1 : 0})" title="${T(mm.n || '')}${mvp ? ' MVP' : ''}" style="position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;padding:3px 1px;background:${mvp ? '#fef2f2' : '#fff'};border:1px solid ${mvp ? '#fca5a5' : '#e7e5e4'};border-radius:7px;cursor:pointer;min-width:0">
            ${mvp ? `<span style="position:absolute;top:1px;left:2px;font-size:7px;font-weight:800;color:#fff;background:#dc2626;padding:0 2px;border-radius:3px">MVP</span>` : ''}
            ${cnt > 1 ? `<span style="position:absolute;top:1px;right:3px;font-size:8px;font-weight:700;color:${mvp ? '#dc2626' : clr}">&times;${cnt}</span>` : ''}
            <div style="height:30px;display:flex;align-items:center;justify-content:center">${art}</div>
            <span style="font-size:9px;font-weight:700;color:${clr}">+${v} ${su}${_sacPlus(+id, mm.lv || 1)}</span>
            ${mvp ? (() => { const b = _mvpCardBonus(+id, mm.lv || 1); return b.a > 0 ? `<span style="font-size:8px;font-weight:700;color:#7c3aed">+${b.a} ${_CB_LBL[b.t] || b.t}</span>` : ''; })() : ''}
          </button>`;
        });
      });
    if (!cells) cells = `<span style="font-size:11px;color:#78716c">${T(_cpTot > 0 ? 'ไม่มีการ์ดที่ตรงเงื่อนไข' : '— ไม่มีการ์ดในคลัง —')}</span>`;
    return `<div style="margin-top:8px;background:#fffbeb;border:1px solid #fcd34d;border-radius:9px;padding:7px">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px">
        <span style="font-size:11px;color:#b45309;font-weight:700">${T('🎴 เลือกการ์ดเสียบ')} &middot; Anubis</span>
        <button onclick="xhrpg.dvCardPickClose()" style="font-size:10px;padding:2px 8px;border:1px solid #a8a29e;border-radius:5px;background:#fff;color:#57534e;cursor:pointer">${T('ปิดหน้าต่าง')}</button>
      </div>
      ${_cpFilterBar('dv', _cpShow, _cpTot)}
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(48px,1fr));gap:4px">${cells}</div>
    </div>`;
  }
  // ── 🥚🔥 เนื้อหาแท็บบูชายัญไข่ MVP (docs/egg-sacrifice-design.md §8) ──────────────
  //    โชว์ **ทุกชนิดมอน** เหมือนสมุดไข่ — ชนิดที่ไม่มีไข่และยังไม่ปลดล็อกโชว์แบบจาง + บอกเหตุผลแทนปุ่ม
  //    🚨 **ห้ามเอา "มีไข่ในคลัง" มาเป็นตัวเรียง** — เคยทำกับแท็บบูชายัญการ์ดแล้วแถวจางถูกดันไปกองท้ายลิสต์
  //       จนผู้เล่นเลื่อนไม่ถึง (เจ้าของแจ้ง 2026-08-14) · เรียง: ดาวมาก (= ปลดล็อกแล้ว) → Lv สูง → id
  // 📊 STAT คร่าว ๆ ของชนิดที่ปลดล็อกแล้ว — "ฟักออกมาแล้วจะได้เท่านี้" (เจ้าของสั่ง 2026-08-15)
  //    🪞 สูตรเดียวกับ _petCombatStats()/xhrpg_pet_combat_stats() เป๊ะ — แก้ที่นั่นต้องแก้ที่นี่
  //    ใช้ Lv(UP) + แต้มอัพ "ที่จำไว้" (ไม่มี = Lv.1 แต้ม 0) · mvp ×2 เสมอ เพราะเส้นทางฟักฟรีบังคับ MVP
  //    ⚠️ ba/bh มาจาก monMasters (server ส่งในก้อน static) — ไม่มี = ไม่โชว์ ดีกว่าโชว์เลขมั่ว
  //    รับ stOverride เพื่อคิด "ถ้าบูชายัญเพิ่มอีก 1 ดาว จะได้เท่าไหร่" โดยไม่แตะข้อมูลจริง
  function _eggSacPreview(r, stOverride) {
    const ba = r.mm.ba | 0, bh = r.mm.bh | 0;
    // ⚠️ bh < 2 ไม่ใช่ < 1 — server รุ่นก่อนหน้าใช้ fallback `?? 1` ⇒ ก้อนที่ cache ไว้อาจมี bh = 1
    //    มอนจริงไม่มีตัวไหน base_hp = 1 (ต่ำสุดหลักร้อย) ⇒ เจอ 1 = ข้อมูลไม่ครบ ให้ซ่อนไปเลย
    //    ดีกว่าโชว์ ❤️ 8 แบบที่เจ้าของเจอ (2026-08-15)
    if (ba < 1 || bh < 2) return null;
    // 🐾 ถ้า "ชนิดนี้คือตัวที่ฟักอยู่ตอนนี้" → ใช้ค่าสด ไม่ใช่ค่าที่จำไว้ (เจ้าของถาม 2026-08-15)
    //    sac_eggs[mid] ถูกเขียนตอน **เก็บเข้าไข่** เท่านั้น ⇒ ระหว่างเลี้ยงอยู่ค่านั้นค้าง
    //    ไม่สลับ = เลี้ยงจน Lv ขึ้นแล้วแผงนี้ยังโชว์เลขเก่า ดูเหมือนบั๊ก
    //    mvp ก็ต้องเอาของจริง — ตัวที่ฟักก่อนปลดล็อกอาจไม่ใช่ MVP (เส้นทางฟักฟรีเท่านั้นที่บังคับ MVP)
    const live = !!(player && (player.pet_mid | 0) === r.id);
    const memo = _eggSacRow(r.id) || {};
    const lv  = live ? _petLvInfo(player.pet_exp).lv : _petLvInfo(Math.max(0, parseInt(memo.e) || 0)).lv;
    const uA  = live ? (player.pet_up_atk | 0) : (memo.a | 0);
    const uH  = live ? (player.pet_up_hp  | 0) : (memo.h | 0);
    const st  = stOverride == null ? _eggSacN(r.id) : stOverride;
    const mvp = live ? ((+player.pet_mvp || 0) ? 2 : 1) : 2;
    const es  = 1 + EGGSAC_PER * st;
    return {
      lv, st, live,
      atk: Math.max(1, Math.round(ba * (2 + 0.20 * lv + 0.30 * uA) * mvp * es) + _modTotalAtk() + (_cardCB().atk | 0)),
      hp:  Math.max(1, Math.round(0.5 * bh * (1 + 0.25 * lv) * mvp * es)),
      def: Math.max(0, Math.round(((r.mm.lv | 0) + lv + 2 * uH) * mvp * es)),
    };
  }
  // 📊 ตาราง STAT: ค่าตอนนี้ → ค่าหลังบูชายัญอีก 1 ดาว (เจ้าของสั่ง 2026-08-15 "ขอละเอียดกว่านี้")
  //    เต็มเพดานแล้ว = ไม่มีคอลัมน์ "ถ้าอัพ" (ไม่มีอะไรให้เทียบ)
  function _eggSacStatLine(r) {
    const now = _eggSacPreview(r);
    if (!now) return '';
    const nxt = now.st >= SAC_MAX ? null : _eggSacPreview(r, now.st + 1);
    const n = v => v.toLocaleString();
    // 📐 2 คอลัมน์ (เจ้าของสั่ง 2026-08-15 "เหลือที่เยอะเกิน") — เดิม 1 บรรทัด/สเตตัส กินความสูงฟรี ๆ
    //    ⚠️ ใช้ auto-fit + minmax(128px,1fr) ไม่ใช่ 2 คอลัมน์ตายตัว —
    //       เคสหนักสุด (มอน Lv.81 · 30 ดาว) เลขขึ้นหลักแสน "358,313 → 365,625"
    //       บังคับ 2 คอลัมน์บนจอแคบ 260px = ล้นกล่อง · auto-fit จะยุบเป็น 1 คอลัมน์ให้เอง
    const row = (ico, a, b) => {
      const up = b && b > a ? ` <span style="color:#16a34a;font-weight:700">→ ${n(b)}</span>` : '';
      return `<div style="display:flex;gap:3px;min-width:0;white-space:nowrap"><span>${ico}</span><b>${n(a)}</b>${up}</div>`;
    };
    return `<div style="margin-top:3px;padding:5px 7px;background:#fffbeb;border:1px solid #fde68a;border-radius:7px">
        <div style="color:#92400e;font-weight:700;margin-bottom:3px">${_gdEsc(now.live ? T('🐾 ตอนนี้ Lv(UP) {a}', {a: now.lv}) : T('ฟักที่ Lv(UP) {a}', {a: now.lv}))}${
          nxt ? ` <span style="color:#16a34a">${_gdEsc(T('→ ถ้าบูชายัญอีก 1 ดาว', {}))}</span>` : ''}</div>
        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(128px,1fr));gap:2px 10px">
          ${row('⚔️', now.atk, nxt && nxt.atk)}
          ${row('❤️', now.hp,  nxt && nxt.hp)}
          ${row('🛡️', now.def, nxt && nxt.def)}
        </div>
      </div>`;
  }
  // 🐾 ปุ่มเรียกใช้ในแท็บนี้เลย (เจ้าของถาม 2026-08-15 "ทำไมปุ่มเปิดใช้ไม่อยู่ที่นี่")
  //    เดิมต้องไปกดที่สมุดไข่ ทั้งที่หน้านี้คือหน้าที่บอกว่า "ปลดล็อกแล้ว" — ไม่สมเหตุสมผล
  //    ⚠️ ฟักได้ทีละตัว (server กันอยู่แล้ว) → มีสัตว์อยู่ = ปุ่มจาง + บอกเหตุผล ไม่ใช่ซ่อนเงียบ ๆ
  function _eggSacCallBtn(mid) {
    const cur = player ? (player.pet_mid | 0) : 0;
    if (cur === mid) return `<div style="margin-top:6px;text-align:center;font-size:10.5px;font-weight:700;color:#16a34a">🐾 ${_gdEsc(T('กำลังใช้ตัวนี้อยู่'))}</div>`;
    if (cur > 0)     return `<div style="margin-top:6px;text-align:center;font-size:10px;color:#94a3b8">${_gdEsc(T('เก็บสัตว์ตัวปัจจุบันก่อนถึงจะเรียกตัวนี้ได้'))}</div>`;
    return `<button onclick="xhrpg.petHatchAsk(${mid},1)" style="width:100%;margin-top:6px;padding:7px;border:none;border-radius:8px;background:#16a34a;color:#fff;font-size:11.5px;font-weight:700;cursor:pointer;font-family:inherit">🐾 ${_gdEsc(T('เรียกใช้ — ฟรี'))}</button>`;
  }
  function _renderEggSac() {
    const eggs = _eggsArr();
    const rows = Object.keys(monMasters)
      .map(k => { const mm = monMasters[k]; return mm ? { id: +k, mm, mvp: (eggs[k] || {}).m | 0, st: _eggSacN(+k) } : null; })
      .filter(r => !!r)
      .sort((a, b) => (b.st - a.st) || ((b.mm.lv | 0) - (a.mm.lv | 0)) || (a.id - b.id));
    const head = `<div style="border:1px solid #fecaca;background:#fef2f2;border-radius:10px;padding:8px 11px;font-size:11px;color:#991b1b;margin-bottom:8px">
        🥚🔥 ${T('ใช้ไข่ ⭐MVP บูชายัญ → ปลดล็อกสัตว์ชนิดนั้นถาวร (สูงสุด {a} ดาว)', {a: SAC_MAX})}<br>
        <span style="color:#b91c1c">${T('ฟักและเก็บฟรีตลอด · เลเวลไม่หาย · ยิ่งดาวมากสัตว์ยิ่งแรง')}</span>
      </div>`;
    if (!rows.length) return head + `<div style="text-align:center;color:#94a3b8;padding:22px;font-size:12.5px">${T('ยังไม่มีข้อมูลมอนสเตอร์ — เข้าเกมสักครู่')}</div>`;
    const nAll = rows.length;
    const nUnl = rows.filter(r => r.st > 0).length;
    const nReady = rows.filter(r => r.st < SAC_MAX && r.mvp >= 1).length;
    const sumStars = rows.reduce((s, r) => s + r.st, 0);
    const bar = _sacSumBar([
      { v: '⭐ ' + sumStars, k: T('ดาวรวม') },
      { v: nUnl + '/' + nAll, k: T('ปลดล็อกแล้ว') },
      { v: '🔥 ' + nReady, k: T('พร้อมบูชา') },
    ]) + _sacFiltBar('e', nAll, nReady, nUnl);
    const fv = _sacFilt.e || 'all';
    const view = fv === 'ready' ? rows.filter(r => r.st < SAC_MAX && r.mvp >= 1)
               : fv === 'star'  ? rows.filter(r => r.st > 0) : rows;
    if (!view.length) return head + bar + `<div style="text-align:center;color:#94a3b8;padding:20px;font-size:12px">${T('ไม่มีรายการในตัวกรองนี้')}</div>`;
    const curPet = player ? (player.pet_mid | 0) : 0;
    return head + bar + view.map(r => {
      const lv = r.mm.lv | 0, st = r.st, unl = st > 0, full = st >= SAC_MAX;
      const memo = _eggSacRow(r.id) || {};
      const mult = (1 + EGGSAC_PER * st).toFixed(2);
      const mPts = (memo.a | 0) + (memo.h | 0) + (memo.r | 0), mExp = Math.max(0, parseInt(memo.e) || 0);
      const hasMemo = unl && (mExp > 0 || mPts > 0);
      const can = !full && r.mvp >= 1;
      const dim = (!unl && r.mvp < 1); // ไม่มีไข่ + ยังไม่ปลดล็อก = จาง (แต่ยังอยู่ในลำดับเดิม ไม่ถูกดันไปท้าย)
      // ② ผลลัพธ์บรรทัดเดียว — ยังเป็นประโยค "ที่มา → ผล" ตามที่เจ้าของสั่งไว้ 2026-08-15
      const effect = unl
        ? `<span style="color:#b45309">${_gdEsc(T('⭐ {a} ดาว → พลังตัวสัตว์ ×{b}', {a: st, b: mult}))}</span>`
        : `<span style="color:#cbd5e1">${T('ยังไม่ปลดล็อก')}</span>`;
      const stock = `🥚<b style="color:${r.mvp > 0 ? '#b91c1c' : '#cbd5e1'}">⭐${T('ในคลัง {a} ฟอง', {a: r.mvp})}</b>`;
      const btn = full ? _sacTag('✅ ' + T('เต็มเพดาน {a} ดาว', {a: SAC_MAX}), '#16a34a')
        : can ? _sacGo('xhrpg.eggSacrifice(' + r.id + ')',
                       unl ? '🔥 ' + T('บูชายัญ') : '🔓 ' + T('ปลดล็อก'),
                       unl ? '#b91c1c' : '#7c3aed')
        : _sacTag(T('ยังไม่มีไข่ ⭐MVP ฟองนี้'), '#94a3b8');
      // 🐾 ปุ่มเรียกสัตว์ย้ายมาเป็นไอคอนมุมขวาบน — ไม่แย่งที่ปุ่มหลักอีกต่อไป
      //    เงื่อนไขเดิมทุกข้อ: ตัวนี้อยู่แล้ว = ป้ายเขียว · มีตัวอื่นอยู่ = จาง กดไม่ได้ · ว่าง = เรียกได้
      const corner = !unl ? '' : (curPet === r.id
        ? `<span title="${T('กำลังใช้ตัวนี้อยู่')}" style="position:absolute;top:7px;right:9px;font-size:11px">🐾</span>`
        : curPet > 0
          ? `<span title="${T('เก็บสัตว์ตัวปัจจุบันก่อนถึงจะเรียกตัวนี้ได้')}" style="position:absolute;top:6px;right:8px;width:22px;height:22px;border-radius:7px;border:1px solid #e2e8f0;background:#f8fafc;color:#cbd5e1;font-size:11px;line-height:20px;text-align:center">🐾</span>`
          : `<button onclick="xhrpg.petHatchAsk(${r.id},1)" title="${T('เรียกใช้ — ฟรี')}" style="position:absolute;top:6px;right:8px;width:22px;height:22px;padding:0;border:none;border-radius:7px;background:#16a34a;color:#fff;font-size:11px;line-height:1;cursor:pointer;font-family:inherit">🐾</button>`);
      const detail = (unl ? _eggSacStatLine(r) : '')
        + (hasMemo ? `<br>${T('💾 จำไว้: Lv(UP) {a} · แต้มอัพ {b} แต้ม', {a: _petLvInfo(mExp).lv, b: mPts})}` : '');
      return _sacShell({ key: 'e' + r.id, lv, emo: r.mm.e, name: T(r.mm.n || ''), st, on: unl, dim, effect, stock, btn, corner,
                         detail: unl ? detail : '' });
    }).join('');
  }
  function eggSacrifice(mid) {
    if (!player || player.line_uid === 'demo') return;
    const mm = monMasters[mid] || {};
    const first = !_eggSacUnl(mid | 0);
    if (!confirm(first ? T('บูชายัญไข่ {a}? ใช้ไข่ ⭐MVP {b} ฟอง — 🔓 ปลดล็อกชนิดนี้ถาวร (ไข่หายถาวร)', {a: T(mm.n || ''), b: 1})
                       : T('บูชายัญไข่ {a}? ใช้ไข่ ⭐MVP {b} ฟอง (ใช้แล้วหายถาวร)', {a: T(mm.n || ''), b: 1}))) return;
    $.post(baseUrl + 'xhrpg_upgrade.php', { line_uid: player.line_uid, action: 'egg_sacrifice', mid: mid | 0, lang: LANG() })
      .done(res => {
        let d; try { d = typeof res === 'string' ? JSON.parse(res) : res; } catch (e) { return; }
        if (d.ok) { player = d.player; renderPet(); updateHUD(); addLog([{ type: 'levelup', msg: d.msg }]); }
        else addLog([{ type: 'dead', msg: d.error || T('บูชายัญไม่สำเร็จ') }]);
      })
      .fail(() => addLog([{ type: 'dead', msg: T('❌ บูชายัญไม่สำเร็จ (เชื่อมต่อ server ไม่ได้)') }]));
  }
  function renderPet() {
    const el = document.getElementById('pet-list');
    if (!el) return;
    // 🏺 แถบแท็บ: 🐾 สัตว์เลี้ยง | 🏺 สัตว์เทพ | 🥚🔥 บูชายัญไข่ — โครงเดียวกับเมนู 🎴 การ์ด (ผู้เล่นเจอ pattern เดิม)
    //    ⚠️ 3 แท็บใน 1 แถว ~300px ⇒ ป้ายต้อง nowrap + ellipsis ไม่งั้นภาษายาว (es/pt) ดันสูงคนละแถว
    const _dvTb = (on, lbl, v, bg, fg) => `<button onclick="xhrpg._dvSetTab(${v})" style="flex:1;text-align:center;padding:7px 0;border-radius:9px;border:none;background:${on ? bg : '#f1f5f9'};color:${on ? fg : '#64748b'};font-size:12px;font-weight:${on ? 700 : 400};cursor:pointer;font-family:inherit;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${lbl}</button>`;
    const tabBar = `<div style="display:flex;gap:5px;margin-bottom:9px">
      ${_dvTb(_dvTab === 0, '🐾 ' + T('สัตว์เลี้ยง'), 0, '#7c3aed', '#fff')}
      ${_dvTb(_dvTab === 1, '🏺 ' + T('สัตว์เทพ'), 1, '#fbbf24', '#78350f')}
      ${_dvTb(_dvTab === 2, '🥚🔥 ' + T('บูชายัญไข่'), 2, '#b91c1c', '#fff')}
    </div>`;
    if (_dvTab === 1) {
      const html = tabBar + _renderDivine();
      if (el._lastHtml !== html) { el._lastHtml = html; el.innerHTML = html; }
      return;
    }
    if (_dvTab === 2) { // 🥚🔥 บูชายัญไข่ MVP
      const html = tabBar + _renderEggSac();
      if (el._lastHtml !== html) { el._lastHtml = html; el.innerHTML = html; }
      return;
    }
    let top = '';
    const mid = (player && player.pet_mid) | 0;
    // 🐛 2026-08-10 ผู้เล่นแจ้ง "กดเก็บเข้าไข่ไม่ได้ · เก็บ → ฟักตัวใหม่ → เก็บอีกที พังเลย"
    //    เดิมเงื่อนไขคือ `mid > 0 && monMasters[mid]` — ถ้าตารางชนิดมอนไม่มี id ตัวนั้น (ตาราง static
    //    ส่งครั้งเดียวตอน have_static=0 · cache xhrpg:master_meta ค้าง / มอนใหม่ที่ยังไม่ล้าง cache)
    //    การ์ดสัตว์เลี้ยงทั้งใบจะไม่เรนเดอร์ → **ปุ่มเก็บเข้าไข่หายไปด้วย** เพราะอยู่ในใบเดียวกัน
    //    ผลคือ soft-lock: server ยังถือว่ามีสัตว์อยู่ → ฟักตัวใหม่ก็ไม่ได้ ("มีสัตว์เลี้ยงฟักอยู่แล้ว")
    //    และเก็บเข้าไข่ก็ไม่ได้ เพราะไม่มีปุ่มให้กด — ตันสนิทจนกว่าจะได้ตารางใหม่
    //    ⚠️ ต่อจากนี้ยึด "pet_mid > 0 = มีสัตว์" อย่างเดียว · ไม่รู้จักชนิด ก็ยังต้องกดเก็บเข้าไข่ได้เสมอ
    if (mid > 0) {
      const mm = monMasters[mid] || { n: '', e: '👾', lv: (player.pet_olv | 0) || 1 }, mvp = !!(+player.pet_mvp || 0);
      const info = _petLvInfo(player.pet_exp); // ส่งค่าดิบ — _petLvInfo แปลงเองแบบไม่ตัด 32-bit
      const pct = Math.max(0, Math.min(100, Math.round(info.cur / Math.max(1, info.need) * 100)));
      const D = mvp ? 56 : 44, sb = _monSpriteBg(mm.lv || 1);
      const art = sb
        ? `<div style="width:${D}px;height:${D}px;background:url('${sb.url}') 0 0/${sb.cols * D}px ${sb.rows * D}px no-repeat;image-rendering:pixelated"></div>`
        : `<div style="font-size:${mvp ? 40 : 32}px;line-height:1">${mm.e || '👾'}</div>`;
      top = `<div style="border:1.5px solid ${mvp ? '#dc2626' : '#0f766e'};background:${mvp ? '#fef2f2' : '#f0fdfa'};border-radius:12px;padding:10px">
        <div style="display:flex;gap:10px;align-items:center">
          <div style="width:64px;height:64px;background:${mvp ? '#fee2e2' : '#ccfbf1'};border-radius:10px;display:flex;align-items:center;justify-content:center;overflow:hidden">${art}</div>
          <div style="flex:1;min-width:0">
            <div style="font-size:13px;font-weight:700;color:#111">${T(mm.n || 'สัตว์เลี้ยง')} ${mvp ? '<span style="font-size:10px;color:#fff;background:#dc2626;border-radius:4px;padding:1px 5px">MVP</span>' : ''} <span style="font-size:10px;color:#64748b;font-weight:400">${T('Lv.ต้นฉบับ {a}', {a: player.pet_olv | 0})}</span></div>
            <div style="font-size:12px;color:#0f766e;font-weight:600;margin-top:2px">Lv(UP) ${info.lv}${info.lv >= 99 ? ' (MAX)' : ` · EXP ${info.cur.toLocaleString()} / ${info.need.toLocaleString()}`}</div>
            <div style="height:7px;background:#e2e8f0;border-radius:4px;margin-top:4px;overflow:hidden"><div style="width:${info.lv >= 99 ? 100 : pct}%;height:100%;background:#14b8a6"></div></div>
          </div>
        </div>
        ${_petCombatRows(player, mvp)}
        ${_petSocketStrip()}
        <button onclick="xhrpg.petRecallAsk()" style="width:100%;margin-top:9px;background:#fff;border:1px solid ${_eggSacUnl(mid) ? '#b91c1c' : '#f59e0b'};color:${_eggSacUnl(mid) ? '#b91c1c' : '#b45309'};border-radius:9px;padding:7px;font-size:12px;font-weight:600;cursor:pointer">${_eggSacUnl(mid) ? T('🔓 เก็บเข้าไข่ฟรี — จำ Lv(UP)/แต้มอัพไว้ให้ · การ์ดคืนเข้าคลัง') : T('🥚 เก็บเข้าไข่ (10,000 G) — Lv(UP)/แต้มอัพเกรด รีเซ็ต · การ์ดคืนเข้าคลัง')}</button>
      </div>`;
    } else {
      top = `<div style="border:1px dashed #cbd5e1;border-radius:12px;padding:16px;text-align:center;color:#94a3b8;font-size:12px">
        <div style="font-size:26px">🐾</div>${T('ยังไม่มีสัตว์เลี้ยง — กดไข่ในสมุดด้านล่างเพื่อฟัก')}<br>
        <span style="font-size:10.5px">${T('สัตว์จะเดินตามคุณ · ช่วยโจมตีมอน (ATK/HP ตาม master) · อัพเกรดได้เมื่อ Lv up · ใส่การ์ดได้ตามระดับมอน')}</span>
      </div>`;
    }
    const html = tabBar + top + (_renderEggBook() || '<div style="text-align:center;color:#94a3b8;padding:16px;font-size:12px">' + T('ยังไม่มีข้อมูลมอนสเตอร์ — เข้าเกมสักครู่') + '</div>');
    if (el._lastHtml !== html) { el._lastHtml = html; el.innerHTML = html; }
  }
  function petHatchAsk(mid, mvp) {
    mid = mid | 0; mvp = !!mvp;
    const mm = monMasters[mid]; if (!mm) return;
    if ((player.pet_mid | 0) > 0) { addLog([{ type: 'dead', msg: T('มีสัตว์เลี้ยงฟักอยู่แล้ว — เก็บเข้าไข่ก่อน (10,000 G)') }]); return; }
    if (document.getElementById('pet-hatch-overlay')) return;
    // 🥚🔥 ปลดล็อกด้วยบูชายัญแล้ว = ฟรี + เป็น ⭐MVP เสมอ (server ตัดสินเอง — ค่า mvp ที่ส่งไปถูกเมินบนเส้นทางนี้)
    const unl = _eggSacUnl(mid);
    if (unl) mvp = true;
    const cost = unl ? 0 : (mm.lv || 1) * 100 * (mvp ? 10 : 1);
    // รูปสัตว์ = sprite เดียวกับหน้าสัตว์เลี้ยง/สมุดไข่ (_monSpriteBg) · ไม่มี sheet → emoji เดิม
    const _hD = mvp ? 56 : 44, _hSb = _monSpriteBg(mm.lv || 1);
    const _hArt = _hSb
      ? `<div style="width:${_hD}px;height:${_hD}px;background:url('${_hSb.url}') 0 0/${_hSb.cols * _hD}px ${_hSb.rows * _hD}px no-repeat;image-rendering:pixelated"></div>`
      : `<div style="font-size:${mvp ? 40 : 32}px;line-height:1">${mm.e || '👾'}</div>`;
    const ov = document.createElement('div');
    ov.id = 'pet-hatch-overlay';
    ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:10000;display:flex;align-items:center;justify-content:center;padding:16px';
    ov.innerHTML = `<div style="background:#fff;border-radius:14px;max-width:290px;width:100%;padding:16px;text-align:center;box-shadow:0 20px 60px rgba(0,0,0,.4)">
      <div style="display:flex;align-items:center;justify-content:center;gap:8px"><span style="font-size:26px;line-height:1">🥚</span><span style="font-size:18px;color:#94a3b8">→</span>${_hArt}</div>
      <div style="font-size:14px;font-weight:700;color:#111;margin-top:4px">${T('ฟักไข่ {a}?', {a: T(mm.n || '') + (mvp ? ' ⭐MVP' : '')})}</div>
      <div style="font-size:11px;color:#4b5563;margin-top:6px;line-height:1.7">${unl
        ? `<b style="color:#b91c1c">🔓 ${T('ปลดล็อกแล้ว')}</b><br>${T('ฟักฟรี ไม่กินไข่ ไม่เสียทอง · คืน Lv(UP)/แต้มอัพที่จำไว้')}`
        : `${T('ค่าฟัก Lv.{a} × 100', {a: mm.lv || 1})}${mvp ? ' × 10' : ''}<br><b style="color:#b45309">= ${cost.toLocaleString()} G</b><br>${T('เริ่มที่ Lv(UP) 1 · เดินตามคุณบนแผนที่')}${mvp ? T(' (ตัวใหญ่!)') : ''}`}</div>
      <div style="display:flex;gap:6px;margin-top:13px">
        <button class="ph-cancel" style="flex:1;font-size:13px;padding:8px;border:1px solid #a8a29e;border-radius:8px;background:#fff;color:#57534e;cursor:pointer">${T('ยกเลิก')}</button>
        <button class="ph-ok" style="flex:1;font-size:13px;padding:8px;border:none;border-radius:8px;background:#0f766e;color:#fff;font-weight:600;cursor:pointer">${T('🐣 ฟักเลย')}</button>
      </div>
    </div>`;
    ov.querySelector('.ph-cancel').addEventListener('click', () => ov.remove());
    ov.querySelector('.ph-ok').addEventListener('click', () => { ov.remove(); _petPost('pet_hatch', { mid, mvp: mvp ? 1 : 0 }); });
    document.body.appendChild(ov);
  }
  function petRecallAsk() {
    // 🥚🔥 ชนิดที่ปลดล็อกแล้ว: ฟรี · ไม่คืนไข่ (ไม่ได้กินไปตั้งแต่แรก) · จำ Lv(UP)/แต้มอัพไว้ให้ (server ตัดสินซ้ำอีกชั้น)
    if (!confirm(_eggSacUnl((player && player.pet_mid) | 0)
        ? T('เก็บสัตว์เลี้ยงเข้าไข่? ฟรี ไม่เสียทอง\nจำ Lv(UP)/แต้มอัพไว้ให้ ฟักใหม่ได้ของเดิมคืนครบ · การ์ดที่เสียบคืนเข้าคลัง')
        : T('เก็บสัตว์เลี้ยงเข้าไข่? เสีย 10,000 G\nLv(UP) จะรีเซ็ตเป็น 1 · การ์ดที่เสียบคืนเข้าคลังฟรี · ไข่กลับเข้าสมุด'))) return;
    _petPost('pet_recall', {});
  }
  function petCardUnsocket(sidx) { _petCardUnsockOpen('pet', sidx | 0); }
  // popup เลือกจ่าย 💰 G(=Lv×500) หรือ 💎 15 P — ใช้ทั้งสัตว์เลี้ยง (kind='pet') และสัตว์เทพ (kind='dv') · mirror popup ถอดการ์ดโมดูล
  function _petCardUnsockOpen(kind, sidx) {
    const dv = kind === 'dv';
    const lv = Math.max(1, dv ? _dvLvInfo(player.dv_exp).lv : ((_petCombatStats(player) || {}).lv || 1));
    const gCost = _PETCARD_UNSOCK_G_PER_LV * lv, pCost = _PETCARD_UNSOCK_P;
    const g = player.gold || 0, p = player.p_points || 0;
    const gDis = g < gCost, pDis = p < pCost, ico = dv ? '🏺' : '🐾';
    const el = document.createElement('div');
    el.id = 'petcard-unsock-modal';
    el.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,.6);z-index:9999;display:flex;align-items:center;justify-content:center;padding:16px';
    el.innerHTML = `<div style="background:#0f172a;border:1px solid #d97706;border-radius:14px;max-width:300px;width:100%;color:#e2e8f0;padding:18px;text-align:center;box-shadow:0 12px 40px rgba(2,8,23,.5)">
      <div style="font-size:30px">🎴</div>
      <div style="font-size:14px;font-weight:700;margin-top:4px">${T('ถอดการ์ดออกจากรู')}</div>
      <div style="font-size:11px;color:#94a3b8;margin-top:3px">${T('การ์ดกลับเข้าคลัง · เลือกวิธีจ่าย')}</div>
      <button onclick="xhrpg._petCardUnsockGo('${kind}',${sidx},'gold')" ${gDis ? 'disabled' : ''} style="width:100%;margin-top:12px;background:${gDis ? '#334155' : '#b45309'};color:#fff;border:none;border-radius:10px;padding:11px;font-size:13px;font-weight:700;cursor:pointer;opacity:${gDis ? .5 : 1}">💰 ${gCost.toLocaleString()} G <span style="font-size:10px;opacity:.85">${T('({i} Lv.{a})', {i: ico, a: lv})}</span></button>
      <button onclick="xhrpg._petCardUnsockGo('${kind}',${sidx},'p')" ${pDis ? 'disabled' : ''} style="width:100%;margin-top:8px;background:${pDis ? '#334155' : '#7c3aed'};color:#fff;border:none;border-radius:10px;padding:11px;font-size:13px;font-weight:700;cursor:pointer;opacity:${pDis ? .5 : 1}">💎 ${pCost} P</button>
      <button onclick="xhrpg._petCardUnsockClose()" style="width:100%;margin-top:8px;background:#334155;color:#cbd5e1;border:none;border-radius:10px;padding:9px;font-size:12px;cursor:pointer">${T('ยกเลิก')}</button>
    </div>`;
    el.addEventListener('click', e => { if (e.target === el) _petCardUnsockClose(); });
    document.body.appendChild(el);
  }
  function _petCardUnsockClose() { const el = document.getElementById('petcard-unsock-modal'); if (el) el.remove(); }
  function _petCardUnsockGo(kind, sidx, pay) {
    _petCardUnsockClose();
    _petPost(kind === 'dv' ? 'dv_card_unsocket' : 'pet_card_unsocket', { sidx: sidx | 0, pay });
  }
  // ── ♻️ รีเซ็ตแต้มอัพ (คืนแต้มทั้งหมด) — popup เลือกจ่าย 💰 Lv×1000 G หรือ 💎 20 P · ใช้ทั้งสัตว์เลี้ยง/สัตว์เทพ (kind='pet'|'dv') ──
  function petResetUp() { _petResetOpen('pet'); }
  function dvResetUp() { _petResetOpen('dv'); }
  function _petResetOpen(kind) {
    const dv = kind === 'dv';
    const st = dv ? _dvStatsC() : _petCombatStats(player);
    if (!st) return;
    const used = dv ? ((player.dv_up_atk | 0) + (player.dv_up_hp | 0) + (player.dv_up_reco | 0))
                    : ((player.pet_up_atk | 0) + (player.pet_up_hp | 0) + (player.pet_up_reco | 0));
    if (used < 1) { addLog([{ type: 'dead', msg: T('ยังไม่ได้ลงแต้ม — ไม่ต้องรีเซ็ต') }]); return; }
    const lv = Math.max(1, dv ? _dvLvInfo(player.dv_exp).lv : (st.lv || 1));
    const gCost = _PET_RESET_G_PER_LV * lv, pCost = _PET_RESET_P;
    const g = player.gold || 0, p = player.p_points || 0;
    const gDis = g < gCost, pDis = p < pCost, ico = dv ? '🏺' : '🐾';
    const el = document.createElement('div');
    el.id = 'petreset-modal';
    el.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,.6);z-index:9999;display:flex;align-items:center;justify-content:center;padding:16px';
    el.innerHTML = `<div style="background:#0f172a;border:1px solid #d97706;border-radius:14px;max-width:300px;width:100%;color:#e2e8f0;padding:18px;text-align:center;box-shadow:0 12px 40px rgba(2,8,23,.5)">
      <div style="font-size:30px">♻️</div>
      <div style="font-size:14px;font-weight:700;margin-top:4px">${T('รีเซ็ตแต้มอัพเกรด')}</div>
      <div style="font-size:11px;color:#94a3b8;margin-top:3px">${T('คืนแต้มทั้งหมด {n} แต้ม · เลือกวิธีจ่าย', {n: used})}</div>
      <button onclick="xhrpg._petResetGo('${kind}','gold')" ${gDis ? 'disabled' : ''} style="width:100%;margin-top:12px;background:${gDis ? '#334155' : '#b45309'};color:#fff;border:none;border-radius:10px;padding:11px;font-size:13px;font-weight:700;cursor:pointer;opacity:${gDis ? .5 : 1}">💰 ${gCost.toLocaleString()} G <span style="font-size:10px;opacity:.85">${T('({i} Lv.{a})', {i: ico, a: lv})}</span></button>
      <button onclick="xhrpg._petResetGo('${kind}','p')" ${pDis ? 'disabled' : ''} style="width:100%;margin-top:8px;background:${pDis ? '#334155' : '#7c3aed'};color:#fff;border:none;border-radius:10px;padding:11px;font-size:13px;font-weight:700;cursor:pointer;opacity:${pDis ? .5 : 1}">💎 ${pCost} P</button>
      <button onclick="xhrpg._petResetClose()" style="width:100%;margin-top:8px;background:#334155;color:#cbd5e1;border:none;border-radius:10px;padding:9px;font-size:12px;cursor:pointer">${T('ยกเลิก')}</button>
    </div>`;
    el.addEventListener('click', e => { if (e.target === el) _petResetClose(); });
    document.body.appendChild(el);
  }
  function _petResetClose() { const el = document.getElementById('petreset-modal'); if (el) el.remove(); }
  function _petResetGo(kind, pay) {
    _petResetClose();
    _petPost(kind === 'dv' ? 'dv_reset_up' : 'pet_reset_up', { pay });
  }
  // picker เลือกการ์ดจากคลังเสียบสัตว์ (ทุกใบเสียบได้ ไม่จำกัดอาวุธ)
  //    ⚠️ อันนี้เป็น overlay ลอยที่สร้างด้วยมือ (ไม่ใช่แผงที่ render ใหม่เอง) — กดตัวกรองแล้วต้อง
  //       ลบของเก่าแล้วเรียกใหม่ ตัว _cpRedraw('pet') ทำให้แล้ว · rebuild=true = ไม่รีเซ็ตตัวกรอง
  function petCardPickOpen(rebuild) {
    if (document.getElementById('pet-cardpick-overlay')) return;
    if (!rebuild) _cpReset();
    const cards = (player.cards && typeof player.cards === 'object' && !Array.isArray(player.cards)) ? player.cards
                : (() => { try { return JSON.parse(player.cards || '{}') || {}; } catch (e) { return {}; } })();
    let cells = '', _cpShow = 0, _cpTot = 0;
    Object.keys(cards).sort((a, b) => ((monMasters[a] && monMasters[a].lv) || 0) - ((monMasters[b] && monMasters[b].lv) || 0)).forEach(id => {
      const mm = monMasters[id] || {}, own = cards[id] || {};
      [['n', false], ['m', true]].forEach(([k, mvp]) => {
        const cnt = own[k] | 0; if (cnt < 1) return;
        _cpTot++; if (!_cpPass(mm, id, mvp)) return; _cpShow++; // 🔎 ตัวกรอง — นับยอดรวมก่อนกรองเสมอ
        const st = (mm.cs || '').toLowerCase(), clr = _CARD_STAT_CLR[st] || '#94a3b8', su = _CARD_STAT_LBL[st] || '?';
        cells += `<button onclick="xhrpg.petCardSocket(${id},${mvp ? 1 : 0})" style="display:flex;align-items:center;gap:7px;width:100%;background:${mvp ? '#fef2f2' : '#f8fafc'};border:1px solid ${mvp ? '#fca5a5' : '#e5e7eb'};border-radius:9px;padding:6px 9px;cursor:pointer;text-align:left">
          <span style="font-size:16px;flex:none">${mm.e || '🎴'}</span>
          <span style="flex:1;min-width:0;font-size:12px;font-weight:600;color:#1c1917;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${mvp ? '⭐' : ''}${T(mm.n || 'การ์ด')} <span style="font-size:9px;color:#64748b;font-weight:400">Lv.${mm.lv || 1} ×${cnt}</span></span>
          <span style="flex:none;text-align:right;line-height:1.25">
            <span style="display:block;font-size:11px;font-weight:700;color:${clr}">+${_cardValue(mm.lv || 1, mvp)} ${su}${_sacPlus(+id, mm.lv || 1)}</span>
            ${mvp ? (() => { const b = _mvpCardBonus(+id, mm.lv || 1); return b.a > 0 ? `<span style="display:block;font-size:8.5px;font-weight:700;color:#7c3aed">+${b.a} ${_CB_LBL[b.t] || b.t}</span>` : ''; })() : ''}
          </span>
        </button>`;
      });
    });
    if (!cells) cells = '<div style="text-align:center;color:#94a3b8;font-size:12px;padding:10px">' + T(_cpTot > 0 ? 'ไม่มีการ์ดที่ตรงเงื่อนไข' : '— ไม่มีการ์ดในคลัง —') + '</div>';
    const ov = document.createElement('div');
    ov.id = 'pet-cardpick-overlay';
    ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:10000;display:flex;align-items:center;justify-content:center;padding:16px';
    ov.onclick = e => { if (e.target === ov) ov.remove(); };
    ov.innerHTML = `<div style="background:#fff;border-radius:16px;padding:14px 15px;max-width:320px;width:100%;max-height:78vh;overflow:auto">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:9px">
        <span style="font-size:13.5px;font-weight:700;color:#1c1917">${T('🎴 เลือกการ์ดเสียบสัตว์เลี้ยง')}</span>
        <button onclick="this.closest('#pet-cardpick-overlay').remove()" style="border:none;background:#f1f5f9;color:#475569;font-size:14px;border-radius:8px;padding:3px 10px;cursor:pointer">✕</button>
      </div>
      <div style="font-size:10.5px;color:#78716c;margin-bottom:8px">${T('เสียบถาวร (ถอด Lv×{g} G หรือ {p} P · เก็บเข้าไข่คืนฟรี) · stat มีผลกับผู้เล่นเหมือนการ์ดในโมดูล', {g: _PETCARD_UNSOCK_G_PER_LV, p: _PETCARD_UNSOCK_P})}</div>
      ${_cpFilterBar('pet', _cpShow, _cpTot)}
      <div style="display:flex;flex-direction:column;gap:5px">${cells}</div>
    </div>`;
    document.body.appendChild(ov);
  }
  function petCardSocket(mid, mvp) {
    const ov = document.getElementById('pet-cardpick-overlay'); if (ov) ov.remove();
    _petPost('pet_card_socket', { mid: mid | 0, mvp: mvp ? 1 : 0 });
  }
  let _petBusy = false; // กันกดรัว (in-flight)
  function _petPost(action, extra) {
    if (_petBusy) return;
    _petBusy = true;
    $.post(baseUrl + 'xhrpg_upgrade.php', Object.assign({ line_uid: player.line_uid, action }, extra))
      .done(res => {
        _petBusy = false;
        let d; try { d = typeof res === 'string' ? JSON.parse(res) : res; } catch (e) { return; }
        if (d.ok) { player = d.player; renderPet(); addLog([{ type: 'levelup', msg: d.msg }]); }
        else addLog([{ type: 'dead', msg: d.error || T('ดำเนินการไม่สำเร็จ') }]);
      })
      .fail(() => { _petBusy = false; addLog([{ type: 'dead', msg: T('เชื่อมต่อไม่ได้ ลองใหม่อีกครั้ง') }]); });
  }

  function renderItems() {
    const autoOn    = (player.auto_use_potion ?? 1) ? 1 : 0;
    const threshold = player.auto_potion_threshold ?? 50;
    const lv        = player.house_lv || 0;
    const vit       = player.vit_eff ?? player.vit ?? 5; // VIT effective — cap ยาให้ตรงกับที่ server เติม
    const activeT   = _potionActiveT();
    const owned  = Array.isArray(player.treasures) ? player.treasures
                 : JSON.parse(player.treasures || '[]');
    const tQty = decodeQty(player.treasures_qty);
    const treasureCards = TREASURE_MASTER.map(t => {
      const have = owned.includes(t.id);
      return tcCard(t, have, tQty[t.id] || 0);
    }).join('');
    const useLabel = activeT.tier > 0
      ? T('ใช้ {i} +{h} HP', {i: _icoPotionHtml(activeT.tier, 13), h: activeT.heal}) // ขวดยา pixel-art ตาม tier (fallback ลูกบอล emoji เดิม)
      : T('ไม่มียา');
    const thOpts = [30,40,50,60,70,80,90].map(v =>
      `<option value="${v}" ${v===threshold?'selected':''}>${v}%</option>`).join('');
    const _il = document.getElementById('item-list'); const _ilHtml = `
      <div style="display:flex;align-items:center;gap:6px;margin:0 0 5px;flex-wrap:wrap">
        <span style="font-size:13px;color:#374151;font-weight:600">${_icoHtml('💊')} ${T('ยาฟื้นพลัง')}</span>
        <button class="abtn red" style="font-size:10px;padding:2px 8px" onclick="xhrpg.usePotionManual()" ${activeT.tier===0?'disabled':''}>${useLabel}</button>
        <label style="display:flex;align-items:center;gap:4px;font-size:11px;color:#92400e;cursor:pointer;user-select:none;white-space:nowrap" title="${T('ยาหมด → เดินกลับยานบินหยิบยาเอง (ปิด = พึ่งโดรน/แมวส่งอย่างเดียว)')}">
          <input type="checkbox" ${(player.auto_refill_potion ?? 0) ? 'checked' : ''} onchange="xhrpg.toggleAutoRefillPotion()" style="width:14px;height:14px;accent-color:#f59e0b;cursor:pointer">${T('ยาหมดกลับอัตโนมัติ')}
        </label>
        <span style="display:none">HP ${player.hp}/${player.hp_max}</span>
      </div>
      ${_renderPotionTierGrid(lv, vit)}
      <div style="font-size:10px;color:#6b7280;margin:3px 0 8px">${T('เปิด/ปิดแต่ละ tier · ใช้ tier สูงสุดที่เปิดและมียา')}</div>
      <div style="background:#f0fdf4;border:0.5px solid #86efac;border-radius:8px;padding:8px 10px;margin-bottom:8px">
        <div style="display:flex;align-items:center;gap:6px;font-size:13px;color:#166534;margin-bottom:4px">
          <span>${_icoHtml('💊', 13)} ${T('AUTO เมื่อ HP &lt;')}</span>
          <select style="font-size:12px;padding:2px 4px;border-radius:4px;border:0.5px solid #86efac;background:#dcfce7;color:#166534"
                  onchange="xhrpg.setAutoPotionThreshold(+this.value)">${thOpts}</select>
          <button class="abtn ${autoOn?'green':'grey'}" style="padding:2px 8px;font-size:12px" onclick="xhrpg.toggleAutoPotion()">
            ${autoOn?T('✅ เปิด'):T('⛔ ปิด')}
          </button>
        </div>
        <div style="font-size:11px;color:#166534">${T('ใช้ T สูงสุดที่เปิดและมียา · &lt; 30% ใช้เสมอแม้ปิด AUTO')}</div>
      </div>
      <div style="display:flex;align-items:center;gap:8px;background:#f5f3ff;border:1px solid #ddd6fe;border-radius:10px;padding:9px 12px;margin-bottom:8px">
        <span style="font-size:12px;color:#6d28d9;font-weight:500">${_icoGemHtml('blue',14)} ${T('เพชร')} <span style="color:#a78bfa;font-weight:400">${T('(ตีบวกโมดูล)')}</span></span>
        <span style="margin-left:auto;display:flex;gap:12px;font-size:13px;font-weight:600">
          <span style="color:#2563eb">${_icoGemHtml('blue')} ${player.diamond_blue||0}</span>
          <span style="color:#dc2626">${_icoGemHtml('red')} ${player.diamond_red||0}</span>
          <span style="color:#16a34a">${_icoGemHtml('green')} ${player.diamond_green||0}</span>
        </span>
      </div>
      ${_renderModuleBoxPanel()}
      ${_renderCardBoxPanel()}
      ${_renderEggBoxPanel()}
      ${_renderOrePanel()}
      ${_renderSeedsPanel()}
      ${renderEquipment()}
      <div class="treasure-panel">
        <div class="treasure-header">${T('🗃️ ของวิเศษ ของล้ำค่า')} <span class="treasure-count">${owned.length}/${TREASURE_MASTER.length}</span></div>
        <div class="treasure-grid">${treasureCards}</div>
      </div>
      ${_collectGrid('🗃️', 'ของวิเศษ ชิ้นส่วนสเตตัส',   STAT_PARTS_MASTER,   player.stat_parts,   player.stat_parts_qty)}
      ${_collectGrid('🗃️', 'ของวิเศษ ชิ้นส่วนอาวุธ',    WEAPON_PARTS_MASTER, player.weapon_parts, player.weapon_parts_qty)}
      ${_collectGrid('🗃️', 'ของวิเศษ ชิ้นส่วนไททัน',  HARDWARE_MASTER,     player.hardware,     player.hardware_qty)}
      ${_collectGrid('🗃️', 'ของวิเศษ ชิ้นส่วนยานบิน',      HOUSE_PARTS_MASTER,  player.house_parts,  player.house_parts_qty)}`;
    if (_il && _il._lastHtml !== _ilHtml) { _il._lastHtml = _ilHtml; _il.innerHTML = _ilHtml; } // เขียน DOM เฉพาะตอน HTML เปลี่ยนจริง — กัน innerHTML rebuild ทุก poll (แผง item แวบ)
  }

