                spawnFloatText(_fp.x + 8 + (_hi % 2) * 7, _fp.y - 12, (o.dc ? '💥-' : '-') + _hd, o.dc ? '#38bdf8' : '#60a5fa', o.dc ? 11 : 9, { alpha: FRIEND_DMG_ALPHA });
