    gwW1: '20:00', gwW2: '20:15', gwOpen: '20:30', gwFight: '20:35', gwEnd: '20:50', // 🚩 ศึกกิล
    cwW1: '21:00', cwW2: '21:15', cwOpen: '21:30', cwFight: '21:35', cwEnd: '21:50', // 🌍 ศึกประเทศ
