  let _cwFlagCc   = ''; // รหัสประเทศผู้ครองธง — ป้าย 🚩 หน้าธงชาติในอันดับประเทศ
  let _gwMini = (() => { try { return localStorage.getItem('xh_gw_mini') === '1'; } catch (e) { return false; } })(); // 🔽 หดแบนเนอร์ (ใช้ร่วมทั้งสองศึก)
