  function _warUpd(kind, v) {
    const S = _WAR[kind], D = _WAR_DEF[kind];
    if (v && v.st === 'ended') {
      if (v.t && v.t !== S.seenEnd) { S.seenEnd = v.t; _warResultPopup(D, v); }
      S.v = null; _warBannerUpd(kind);
      if (S.cd) { clearInterval(S.cd); S.cd = null; }
      return;
    }
    if (v && (v.st === 'pre' || v.st === 'open' || v.st === 'fight')) {
      S.v = v;
      S.v.until = Math.floor(Date.now() / 1000) + (v.in | 0); // นับถอยหลังเดินเองทุกวิ (poll มาแค่ ~1-3s)
      _warBannerUpd(kind);
      if (!S.cd) S.cd = setInterval(() => _warBannerUpd(kind), 1000);
      // popup ชวนเข้าร่วม — ครั้งเดียวต่อศึก · เลื่อนถ้าแผงประมูลเปิดอยู่ (ประกาศตรงวินาทีปิดบิดพอดี)
      if (v.can && v.fight && v.fight !== S.asked && v.fight !== S.declined && !document.getElementById('auc-panel')) {
        S.asked = v.fight; _warJoinPopup(kind, D, v);
      }
      return;
    }
    S.v = null; _warBannerUpd(kind);
    if (S.cd) { clearInterval(S.cd); S.cd = null; }
  }
  function _gwTimeStr(sec) { sec = Math.max(0, sec | 0); return Math.floor(sec / 60) + ':' + ('0' + (sec % 60)).slice(-2); }
  function _warBannerUpd(kind) {
    const S = _WAR[kind], D = _WAR_DEF[kind], bid = kind + '-banner';
    let el = document.getElementById(bid);
    if (!S.v) { if (el) el.remove(); return; }
    if (!el) {
      el = document.createElement('div');
      el.id = bid;
      _floatMount(el, 'top:8px;left:50%;transform:translateX(-50%);z-index:9500;background:' + D.bg + ';border:1px solid ' + D.bd + ';border-radius:12px;padding:6px 14px;color:' + D.fg + ';font-size:12px;font-weight:700;text-align:center;box-shadow:0 4px 14px rgba(0,0,0,.5);min-width:min(250px,90%);max-width:94%;box-sizing:border-box');
      el.dataset.mode = '';
    }
    const tstr = _gwTimeStr((S.v.until || 0) - Math.floor(Date.now() / 1000));
    if (S.v.st === 'pre') {
      if (el.dataset.mode !== 'pre') {
        el.dataset.mode = 'pre'; el.style.borderColor = '#f59e0b'; el.style.color = '#fde68a';
        el.innerHTML = '<div>' + D.ico + ' ' + _gdEsc(D.pre()) + ' · ⏳ <span class="war-t"></span></div>';
      }
      const _t = el.querySelector('.war-t'); if (_t) _t.textContent = tstr;
      return;
    }
    const mode = S.v.st + (S.v.in_arena ? 'A' : 'B');
    if (el.dataset.mode !== mode) {
      el.dataset.mode = mode;
      el.style.borderColor = S.v.st === 'fight' ? D.bdFight : D.bd;
      el.style.color = S.v.st === 'fight' ? D.fgFight : D.fg;
      const head = S.v.st === 'open'
        ? (S.v.in_arena ? '🛡️ ' + _gdEsc(D.openWait()) : D.ico + ' ' + _gdEsc(D.openIn()))
        : '⚔️ ' + _gdEsc(D.fight());
      el.innerHTML = '<div>' + head + ' ⏳ <span class="war-t"></span> · 👥 <span class="war-n"></span></div>'
                   + '<div class="war-sc" style="font-size:10.5px;color:#ddd6fe;margin-top:3px;line-height:1.45"></div>';
      // 🔽 ปุ่มหด — ตอนโดนรุมอยากเห็นจอชัดๆ · จำสถานะไว้ใน localStorage
      const tg = document.createElement('button');
      tg.className = 'war-tog';
      tg.style.cssText = 'position:absolute;top:2px;right:4px;background:transparent;border:0;color:inherit;font-size:12px;line-height:1;padding:2px 4px;cursor:pointer;opacity:.75';
      tg.onclick = () => { _gwMini = !_gwMini; try { localStorage.setItem('xh_gw_mini', _gwMini ? '1' : '0'); } catch (e) {} _WAR_KINDS.forEach(_warBannerUpd); };
      el.appendChild(tg);
      // 📜 แถวปุ่ม — เข้าร่วมศึก (เฉพาะคนที่ยังไม่เข้าและมีสิทธิ์) + ประวัติสังหาร (ทุกคน)
      const br = document.createElement('div');
      br.className = 'war-btns';
      br.style.cssText = 'display:flex;gap:6px;margin-top:5px;justify-content:center';
      if (!S.v.in_arena && S.v.can) {
        const b = document.createElement('button');
        b.className = 'war-join';
        b.textContent = '⚔️ ' + T('เข้าร่วมศึก');
        b.style.cssText = 'background:#7c3aed;color:#fff;border:0;border-radius:8px;padding:4px 16px;font-size:12px;font-weight:700;cursor:pointer';
        b.onclick = () => D.join();
        br.appendChild(b);
      } else if (!S.v.in_arena) {
        // 🔒 บอกเหตุผลที่เข้าไม่ได้ — เดิมไม่ขึ้นปุ่มเฉย ๆ ไม่มีคำอธิบายอะไรเลย
        //    ผู้เล่นแจ้ง 2026-08-07 (張正輝): "เปลี่ยนกิลแล้วเข้าศึกไม่ได้ 2 วันแล้ว" — จริง ๆ คือติดกติกา 48 ชม.
        //    แต่จอไม่เคยบอก เลยดูเหมือนระบบพัง (server กันถูกแล้ว นี่คือแก้เฉพาะการสื่อสาร)
        const w = document.createElement('span');
        w.style.cssText = 'font-size:11px;font-weight:700;color:' + D.fg + ';opacity:.72;padding:4px 10px;border:1px dashed ' + D.bd + ';border-radius:8px';
        //    ⏳ ชั่วโมงมาจาก server (cd_h) ไม่ฝังเลขในคำแปล — ปรับ XHRPG_GW_JOIN_COOLDOWN แล้วจอถูกเอง
        w.textContent = '🔒 ' + (kind === 'gw'
          ? ((S.v.gid > 0 && (S.v.cd_h | 0) > 0)
              ? T('ต้องอยู่กิลครบ {a} ชม. จึงร่วมศึกได้', { a: S.v.cd_h | 0 })
              : T('ต้องมีกิลก่อนจึงร่วมศึกได้'))
          : T('ต้องมีประเทศก่อนจึงร่วมศึกได้'));
        br.appendChild(w);
      }
      const lb = document.createElement('button');
      lb.textContent = '📜 ' + T('ประวัติศึก');
      lb.style.cssText = 'background:transparent;color:' + D.fg + ';border:1px solid ' + D.bd + ';border-radius:8px;padding:4px 12px;font-size:12px;font-weight:700;cursor:pointer';
      lb.onclick = () => _warLogPopup(kind);
      br.appendChild(lb);
      el.appendChild(br);
    }
    const _t = el.querySelector('.war-t'), _n = el.querySelector('.war-n'), _s = el.querySelector('.war-sc');
    if (_t) _t.textContent = tstr;
    if (_n) _n.textContent = T('{a} คน', { a: S.v.n | 0 });
    if (_s) { // 📊 สกอร์บอร์ดเป็น "ตาราง" คอลัมน์ตายตัว — ทีมเยอะแล้วชื่อ/แต้มยังตรงแถวกัน
      const top = (S.v.top || []).slice(0, 5);
      _s.textContent = '';
      if (!top.length) { _s.textContent = D.empty(); }
      else {
        const tb = document.createElement('div');
        tb.style.cssText = 'display:grid;grid-template-columns:14px minmax(0,1fr) auto;gap:0 6px;align-items:baseline;text-align:left';
        let mine = false;
        top.forEach((g, i) => {
          const isMine = String(g.g) === String(S.v.gid);
          if (isMine) mine = true;
          const rk = document.createElement('span');
          rk.style.cssText = 'text-align:center;opacity:.9';
          rk.textContent = i < 3 ? ['🥇', '🥈', '🥉'][i] : String(i + 1);
          const nm = document.createElement('span');
          nm.style.cssText = 'min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap' + (isMine ? ';color:#86efac;font-weight:800' : '');
          D.cell(nm, g);
          const pt = document.createElement('span');
          pt.style.cssText = 'text-align:right;font-weight:800;font-variant-numeric:tabular-nums' + (isMine ? ';color:#86efac' : '');
          pt.textContent = (g.p | 0);
          tb.appendChild(rk); tb.appendChild(nm); tb.appendChild(pt);
        });
        // ทีมเราไม่ติด 5 อันดับ → ต่อแถวของเราไว้ท้ายตาราง (คอลัมน์เดียวกัน อ่านเทียบได้ทันที)
        if (S.v.gid && !mine) {
          const rk = document.createElement('span'); rk.style.cssText = 'text-align:center;color:#fbbf24'; rk.textContent = '•';
          const nm = document.createElement('span'); nm.style.cssText = 'min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#fbbf24;font-weight:800'; nm.textContent = D.myTeam();
          const pt = document.createElement('span'); pt.style.cssText = 'text-align:right;font-weight:800;color:#fbbf24;font-variant-numeric:tabular-nums'; pt.textContent = (S.v.my | 0);
          tb.appendChild(rk); tb.appendChild(nm); tb.appendChild(pt);
        }
        _s.appendChild(tb);
      }
    }
    { // ย่อ/ขยาย: หดแล้วเหลือบรรทัดเวลา+จำนวนคนอย่างเดียว
      const tg = el.querySelector('.war-tog'), jb = el.querySelector('.war-btns');
      if (tg) tg.textContent = _gwMini ? '▸' : '▾';
      if (_s) _s.style.display = _gwMini ? 'none' : '';
      if (jb) jb.style.display = _gwMini ? 'none' : 'flex';
      el.style.padding = _gwMini ? '3px 22px 3px 10px' : '6px 22px 6px 14px';
      el.style.opacity = _gwMini ? '.82' : '1';
    }
  }
  // ══ 📜 ประวัติการสังหารระหว่างศึก (เจ้าของสั่ง 2026-08-05) ══════════════════════════
  //    ฟีด "รวมทั้งสนาม" ก้อนเดียว — นาย ก.[กิล ก.] ⚔️ นาย ข.[กิล ค.] · ใช้ร่วมทั้ง gw/cw
  //    ⚠️ ชื่อผู้เล่น/ชื่อกิล = ข้อความจากผู้เล่น → **textContent ล้วน ห้าม innerHTML** (บทเรียนแชท)
  //    ⚠️ ไม่มีประวัติย้อนหลัง — server เปิดให้เฉพาะช่วงห้องรอ/รบ (เจ้าของสั่ง)
  let _warLogTab = 0;   // 0 = ทั้งสนาม · 1 = เฉพาะของฉัน
  let _warLogMlv = 0;   // 🎯 เลเวลขั้นต่ำของเป้าที่นับแต้ม (server ส่งมา · 0 = ปิดเกณฑ์)
  let _warLogPpk = 0;   // 🔢 แต้มต่อ 1 การสังหาร (server ส่งมา ไม่ hardcode) — ใช้เขียนบรรทัดอธิบายท้ายฟีด
  function _warLogPopup(kind) {
    if (document.getElementById('war-log-pop')) return;
    const D = _WAR_DEF[kind];
    const ov = document.createElement('div');
    ov.id = 'war-log-pop';
    ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:10008;display:flex;align-items:center;justify-content:center;padding:16px';
    const box = document.createElement('div');
    box.style.cssText = 'background:#1e1b4b;border:1px solid ' + D.bd + ';border-radius:16px;width:100%;max-width:340px;overflow:hidden;display:flex;flex-direction:column;max-height:80vh';
    const hd = document.createElement('div');
    hd.style.cssText = 'padding:12px 14px 10px;border-bottom:1px solid #4c1d95;position:relative;flex:0 0 auto';
    const ti = document.createElement('div');
    ti.style.cssText = 'font-size:15px;font-weight:800;color:#e9d5ff';
    ti.textContent = '📜 ' + T('ประวัติการสังหาร');
    const x = document.createElement('button');
    x.style.cssText = 'position:absolute;top:6px;right:8px;background:transparent;border:0;color:#c4b5fd;font-size:16px;cursor:pointer;padding:2px 6px';
    x.textContent = '✕'; x.onclick = () => ov.remove();
    hd.appendChild(ti); hd.appendChild(x);
    const tabs = document.createElement('div');
    tabs.style.cssText = 'display:flex;gap:6px;padding:9px 14px 0;flex:0 0 auto';
    const sum = document.createElement('div');
    sum.style.cssText = 'margin:9px 14px 0;background:#2a2455;border-radius:10px;padding:6px 10px;font-size:12px;font-weight:800;color:#ddd6fe;text-align:center;flex:0 0 auto';
    const feed = document.createElement('div');
    feed.style.cssText = 'margin:9px 8px 12px;overflow-y:auto;flex:1 1 auto;min-height:60px';
    feed.textContent = '⏳';
    box.appendChild(hd); box.appendChild(tabs); box.appendChild(sum); box.appendChild(feed);
    ov.appendChild(box);
    ov.onclick = e => { if (e.target === ov) ov.remove(); };
    document.body.appendChild(ov);

    const myName = String((player && player.display_name) || '');
    let rows = [];
    const mkTab = (i, label) => {
      const b = document.createElement('button');
      b.style.cssText = 'flex:1;text-align:center;font-size:12px;font-weight:800;padding:5px 0;border-radius:8px;cursor:pointer;border:1px solid transparent;'
        + (_warLogTab === i ? 'background:#7c3aed;color:#fff;border-color:' + D.bd : 'background:#2e2a5e;color:#a5b4fc');
      b.textContent = label;
      b.onclick = () => { _warLogTab = i; draw(); };
      return b;
    };
    function draw() {
      tabs.textContent = '';
      tabs.appendChild(mkTab(0, T('ฟีดทั้งสนาม')));
      tabs.appendChild(mkTab(1, T('เฉพาะของฉัน')));
      let kn = 0, dn = 0;
      rows.forEach(r => { if (r.k === myName) kn++; if (r.v === myName) dn++; });
      sum.textContent = T('⚔️ {a} สังหาร · 💀 {b} ตาย', { a: kn, b: dn });
      const list = _warLogTab === 1 ? rows.filter(r => r.k === myName || r.v === myName) : rows;
      feed.textContent = '';
      if (!list.length) {
        const em = document.createElement('div');
        em.style.cssText = 'text-align:center;color:#8b84a8;font-size:12px;padding:18px 0';
        em.textContent = T('ยังไม่มีการสังหาร');
        feed.appendChild(em); return;
      }
      list.forEach((r, i) => {
        const ev = document.createElement('div');
        ev.style.cssText = 'display:grid;grid-template-columns:44px minmax(0,1fr) 30px;gap:0 5px;align-items:baseline;'
          + 'padding:4px 6px;border-radius:7px;font-size:11.5px;line-height:1.4'
          + (i % 2 ? ';background:rgba(255,255,255,.035)' : '');
        const ts = document.createElement('span');
        ts.style.cssText = 'color:#8b84a8;font-size:10.5px;font-variant-numeric:tabular-nums';
        const dt = new Date((r.t | 0) * 1000);
        ts.textContent = ('0' + dt.getHours()).slice(-2) + ':' + ('0' + dt.getMinutes()).slice(-2) + ':' + ('0' + dt.getSeconds()).slice(-2);
        const bd = document.createElement('span');
        bd.style.cssText = 'min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap';
        const kn2 = document.createElement('span');
        kn2.style.cssText = 'font-weight:800;color:' + (r.k === myName ? '#86efac' : '#e9d5ff');
        kn2.textContent = String(r.k || '?');
        const kt = document.createElement('span'); kt.style.cssText = 'color:#a5b4fc;font-size:10.5px;margin-left:3px'; D.tcell(kt, r.kt);
        const sw = document.createElement('span'); sw.style.cssText = 'margin:0 4px'; sw.textContent = '⚔️';
        const vn = document.createElement('span');
        vn.style.cssText = 'font-weight:800;color:' + (r.v === myName ? '#fca5a5' : '#cbd5e1');
        vn.textContent = String(r.v || '?');
        const vt = document.createElement('span'); vt.style.cssText = 'color:#a5b4fc;font-size:10.5px;margin-left:3px'; D.tcell(vt, r.vt);
        bd.appendChild(kn2); bd.appendChild(kt); bd.appendChild(sw); bd.appendChild(vn); bd.appendChild(vt);
        const gp = document.createElement('span');
        gp.style.cssText = 'text-align:right;font-weight:800;font-variant-numeric:tabular-nums;color:' + ((r.p | 0) > 0 ? '#4ade80' : '#6b7280');
        gp.textContent = (r.p | 0) > 0 ? '+' + (r.p | 0) : '—';
        ev.appendChild(ts); ev.appendChild(bd); ev.appendChild(gp);
        feed.appendChild(ev);
      });
      // 🔢 อธิบายวิธีคิดแต้มท้ายฟีด — ผู้เล่นแจ้ง "ฆ่าแล้วไม่ได้แต้ม" (2026-08-05)
      //    เลข {n} มาจาก server (XHRPG_WAR_PT_PER_KILL) ไม่ฝังในคีย์แปล — แก้ที่ config แล้วข้อความเปลี่ยนตาม
      if (_warLogPpk > 0) {
        const lg = document.createElement('div');
        lg.style.cssText = 'margin:6px 6px 0;padding-top:6px;border-top:1px solid #4c1d95;font-size:10.5px;color:#a5b4fc;line-height:1.5';
        lg.textContent = '🔢 ' + T('ทุกการสังหารได้ {n} แต้มเท่ากัน', { n: _warLogPpk });
        feed.appendChild(lg);
        // 🎯 เกณฑ์เลเวลเป้า — เหตุผลเดียวกับบรรทัดบน: ไม่บอกแล้วโดนแจ้งว่า "ฆ่าแล้วแต้มไม่ขึ้น = บั๊ก"
        //    เลข {n} มาจาก server (XHRPG_WAR_PT_MIN_LV) · 0 = ปิดเกณฑ์ → ไม่ต้องโชว์บรรทัดนี้
        if (_warLogMlv > 0) {
          const lg2 = document.createElement('div');
          lg2.style.cssText = 'margin:3px 6px 0;font-size:10.5px;color:#fcd34d;line-height:1.5';
          lg2.textContent = '🎯 ' + T('นับแต้มเฉพาะเป้าหมาย Lv.{n} ขึ้นไป', { n: _warLogMlv });
          feed.appendChild(lg2);
        }
      }
    }
    $.post(baseUrl + 'xhrpg_cwar.php',
      { line_uid: player.line_uid, lang: LANG(), session_token: sessionToken || '', action: 'war_log', kind: kind },
      d => {
        if (!d || !d.ok) { feed.textContent = ''; const e2 = document.createElement('div');
          e2.style.cssText = 'text-align:center;color:#fca5a5;font-size:12px;padding:18px 0';
          e2.textContent = String((d && d.error) || '?'); feed.appendChild(e2); return; }
        rows = Array.isArray(d.feed) ? d.feed : [];
        _warLogPpk = d.ppk | 0;
        _warLogMlv = d.mlv | 0;   // 🔢 เลเวลขั้นต่ำของเป้าที่นับแต้ม (server ส่งมา ไม่ hardcode)
        draw();
      }, 'json').fail(() => { feed.textContent = '⚠️'; });
  }
  function _warJoinPopup(kind, D, v) {
    if (document.getElementById('war-join-pop')) return;
    const ov = document.createElement('div');
    ov.id = 'war-join-pop';
    ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:10007;display:flex;align-items:center;justify-content:center;padding:16px';
    const box = document.createElement('div');
    box.style.cssText = 'background:#1e1b4b;border:1px solid ' + D.bd + ';border-radius:16px;padding:22px 24px;max-width:330px;text-align:center';
    box.innerHTML = '<div style="font-size:44px">' + D.ico + '</div>'
      + '<div style="font-size:17px;font-weight:800;color:#e9d5ff;margin-top:6px">' + _gdEsc(D.popTitle()) + '</div>'
      + '<div style="font-size:12.5px;color:#c7d2fe;margin-top:8px;line-height:1.55">' + _gdEsc(D.popBody()) + '</div>'
      + '<div style="font-size:11px;color:#a5b4fc;margin-top:6px;line-height:1.5">' + _gdEsc(T('เข้าร่วมแล้วจะวาร์ปเข้าสนาม · จบศึกระบบพากลับจุดเดิมอัตโนมัติ')) + '</div>';
    const row = document.createElement('div');
    row.style.cssText = 'display:flex;gap:8px;margin-top:14px';
    const bY = document.createElement('button');
    bY.textContent = '⚔️ ' + T('เข้าร่วม');
    bY.style.cssText = 'flex:1;background:#7c3aed;color:#fff;border:0;border-radius:10px;padding:9px 0;font-size:13px;font-weight:800;cursor:pointer';
    bY.onclick = () => { ov.remove(); D.join(); };
    const bN = document.createElement('button');
    bN.textContent = T('ไว้ก่อน');
    bN.style.cssText = 'flex:1;background:#334155;color:#fff;border:0;border-radius:10px;padding:9px 0;font-size:13px;font-weight:700;cursor:pointer';
    bN.onclick = () => { ov.remove(); _WAR[kind].declined = v.fight || 0; }; // ไม่เด้งซ้ำในศึกนี้
    row.appendChild(bY); row.appendChild(bN);
    box.appendChild(row); ov.appendChild(box);
    document.body.appendChild(ov);
  }
  // วาร์ปเข้าสนาม (server จำจุดเดิมให้ → จบศึกพากลับเอง) — มิเรอร์ castleEnter
  function _warEnterDone(d, msg) {
    currentMap = d.map | 0; player.map = currentMap;
    player.x = d.x; player.y = d.y; player.explore_cx = d.x; player.explore_cy = d.y;
    delete smoothPos['player'];                    // snap กล้อง (ข้ามแมพ)
    currentSpotId = 0; travelingToSpot = null; _haveMon = false;
    groundCanvas = null;
    buildGround(); closeMapSelect(); _homeBtnUpd(); updateHUD(); startAnim();
    addLog([{ type: 'levelup', msg }]);
  }
  function _gwJoin() {
    if (!player || !player.line_uid || player.line_uid === 'demo') return;
    _gdAct({ action: 'gwar_join' }, d => _warEnterDone(d, T('🚩 เข้าสู่สนามศึกชิงธงแล้ว!')));
  }
  function _cwJoin() {
    if (!player || !player.line_uid || player.line_uid === 'demo') return;
    $.post(baseUrl + 'xhrpg_cwar.php', { line_uid: player.line_uid, lang: LANG(), session_token: sessionToken || '', action: 'cwar_join' })
      .done(res => {
        // server ตอบไม่เป็น JSON = ฝั่ง server error (display_errors ปิด → body ว่าง) — บอกให้รู้ ไม่ใช่เงียบหาย
        let d; try { d = typeof res === 'string' ? JSON.parse(res) : res; } catch (e) { addLog([{ type: 'dead', msg: T('❌ เชื่อมต่อไม่ได้') }]); return; }
        if (!d || !d.ok) { alert((d && d.error) || T('❌ เชื่อมต่อไม่ได้')); return; }
        _warEnterDone(d, T('🌍 เข้าสู่สนามศึกชิงธงประเทศแล้ว!'));
      })
      .fail(() => addLog([{ type: 'dead', msg: T('❌ เชื่อมต่อไม่ได้') }]));
  }
  function _warResultPopup(D, v) {
    const ov = document.createElement('div');
    ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.62);z-index:10005;display:flex;align-items:center;justify-content:center;padding:16px';
    const box = document.createElement('div');
    const col = v.cancel ? '#78716c' : (v.mine ? '#f59e0b' : D.bd);
    box.style.cssText = 'background:#0f172a;border:1px solid ' + col + ';border-radius:16px;padding:22px 26px;max-width:340px;text-align:center';
    box.innerHTML = '<div style="font-size:44px">' + (v.cancel ? '🏳️' : D.ico) + '</div>';
    const h = document.createElement('div');
    h.style.cssText = 'font-size:17px;font-weight:800;margin-top:6px;color:' + (v.cancel ? '#a8a29e' : (v.mine ? '#fbbf24' : '#d8b4fe'));
    h.textContent = v.cancel ? D.noWar() : (v.mine ? D.winMine() : D.winOther());
    box.appendChild(h);
    const b1 = document.createElement('div');
    b1.style.cssText = 'font-size:13px;color:#e2e8f0;margin-top:8px;line-height:1.55';
    if (v.cancel) b1.textContent = T('ผู้เข้าร่วมไม่ครบเกณฑ์ — ธงเดิมอยู่ต่ออีกวัน');
    else if (D.id === 'cw') b1.innerHTML = '🚩 ' + _ccFlag(String(v.name || '').toUpperCase()) + _gdEsc(String(v.name || '?')) + ' — ' + _gdEsc(T('{a} แต้ม', { a: v.pts | 0 }));
    else b1.textContent = '🚩 ' + String(v.name || '?').slice(0, 20) + ' — ' + T('{a} แต้ม', { a: v.pts | 0 });
    box.appendChild(b1);
    if (!v.cancel) {
      const b2 = document.createElement('div');
      b2.style.cssText = 'font-size:11.5px;color:#a5b4fc;margin-top:6px;line-height:1.5';
      b2.textContent = T('ครองธงมา {a} วันติด', { a: v.streak | 0 }) + ' · ' + D.buffTxt();
      box.appendChild(b2);
      // 🥇🥈🥉 อันดับ 1-3 ของศึกรอบนี้ (เจ้าของขอ 2026-08-02) — โครงตารางเดียวกับสกอร์บอร์ดในแบนเนอร์
      //    โชว์เมื่อมีตั้งแต่ 2 ทีมขึ้นไป (ทีมเดียว = ซ้ำกับบรรทัดผู้ชนะด้านบน)
      const top = (v.top || []).slice(0, 3);
      if (top.length >= 2) {
        const tb = document.createElement('div');
        tb.style.cssText = 'display:grid;grid-template-columns:16px minmax(0,1fr) auto;gap:2px 7px;align-items:baseline;text-align:left;margin-top:10px;padding-top:9px;border-top:1px solid #1e293b;font-size:11.5px;color:#cbd5e1';
        top.forEach((g, i) => {
          const rk = document.createElement('span');
          rk.style.cssText = 'text-align:center';
          rk.textContent = ['🥇', '🥈', '🥉'][i];
          const nm = document.createElement('span');
          nm.style.cssText = 'min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap' + (i === 0 ? ';color:#fbbf24;font-weight:800' : '');
          D.cell(nm, g);
          const pt = document.createElement('span');
          pt.style.cssText = 'text-align:right;font-weight:800;font-variant-numeric:tabular-nums' + (i === 0 ? ';color:#fbbf24' : '');
          pt.textContent = T('{a} แต้ม', { a: g.p | 0 });
          tb.appendChild(rk); tb.appendChild(nm); tb.appendChild(pt);
        });
        box.appendChild(tb);
      }
    }
    const b = document.createElement('button');
    b.textContent = 'OK';
    b.style.cssText = 'margin-top:14px;background:#334155;color:#fff;border:0;border-radius:10px;padding:8px 28px;font-size:13px;font-weight:700;cursor:pointer';
    b.onclick = () => ov.remove();
    box.appendChild(b);
    ov.appendChild(box);
    ov.onclick = e => { if (e.target === ov) ov.remove(); };
    document.body.appendChild(ov);
  }
  // 🏟️ สีชื่อในสนามช่วงศึก: เขียว = พวกเดียวกัน (ตีไม่ได้) · แดง = ศัตรู · null = นอกช่วงศึก ใช้สีเดิม
  //    gw เทียบ guild_id · cw เทียบ wc (ประเทศจาก blob — ตรงกับที่ server ใช้กรองเป้า)
  // 🤝 gid กิลพันธมิตร — server ส่งมาทุก poll ตอนอยู่สนาม (map 4) · ใช้แค่ระบายสี การกันตีจริงอยู่ฝั่ง server
  let _gwAllies = [];
  function _gwNameColor(o) {
    if (currentMap !== 4) return null;
    const g = _WAR.gw.v, c = _WAR.cw.v;
    if (g && (g.st === 'open' || g.st === 'fight')) {
      const my = (player && player.guild_id) | 0;
      if (!my) return null;
      if ((o.gid | 0) === my) return '#16a34a';                       // 🟩 กิลเรา
      if (_gwAllies.indexOf(o.gid | 0) >= 0) return '#0891b2';        // 🤝 กิลพันธมิตร — ตีไม่ได้เหมือนกัน แต่แยกสีให้รู้ว่าคนละกิล
      return '#dc2626';                                               // 🟥 ศัตรู
    }
    if (c && (c.st === 'open' || c.st === 'fight')) {
      const my = String((player && player.country) || '').toUpperCase().slice(0, 2);
      return my ? ((String(o.wc || '').toUpperCase() === my) ? '#16a34a' : '#dc2626') : null;
    }
    return null;
  }
  // 🚩 ริบบิ้นบัฟธงขวาบน — ต่อบรรทัดใต้แบนเนอร์อีเวนต์ (server ส่งเฉพาะคนที่ได้บัฟจริง)
  //    gwf = ธงกิล (EXP/G) · cwf = ธงประเทศ (EXP/DROP) · ได้ทั้งคู่ = สองบรรทัด
  function _warFlagBanner(id, txt, grad, row) {
    let el = document.getElementById(id);
    if (!txt) { if (el) el.remove(); return; }
    if (!el) {
      const mm = document.getElementById('minimapCanvas'); // เกาะ parent เดียวกับแบนเนอร์อีเวนต์ (มุมขวาบน)
      el = document.createElement('div');
      el.id = id;
      el.style.cssText = 'position:absolute;right:3px;background:' + grad + ';color:#fff;font-size:9.5px;font-weight:800;border-radius:999px;padding:2px 9px;line-height:1.3;white-space:nowrap;z-index:30;box-shadow:0 2px 6px rgba(0,0,0,.35);pointer-events:none';
      (mm && mm.parentNode ? mm.parentNode : document.body).appendChild(el);
    }
    el.style.top = (-2 + row * 17) + 'px';
    if (el.textContent !== txt) el.textContent = txt;
  }
  const _mx = v => String(Math.round(v * 1000) / 1000); // 1.25×1.1 = 1.3750000000000002 → 1.375
  //    ถือสองธง = รวมเหลือบรรทัดเดียว โชว์ "ตัวคูณจริงที่ได้" (ธง EXP คูณทบกันจริงในสูตร idle_logic)
  //    ตัดคำ FLAG/COUNTRY ออก — อีโมจิบอกแล้วว่าธงอะไร (เจ้าของเคาะ 2026-08-02 · เดิมกินที่จนบังมินิแมพ)
  //    อีเวนต์ (newbie/ปกติ) ยุบเป็นบรรทัดเดียวอยู่แล้วด้วยกติกา max() ฝั่ง server → สูงสุด 2 บรรทัดเสมอ
  function _flagBannersUpd(gwf, cwf) {
    const row = document.getElementById('ev-mult-banner') ? 1 : 0; // มีแบนเนอร์อีเวนต์ = เริ่มบรรทัดถัดไป
    const GW = 'linear-gradient(90deg,#7c3aed,#c026d3)', CW = 'linear-gradient(90deg,#0284c7,#0d9488)';
    // 🏆 2026-08-11 ธงเป็นเกียรติล้วน — ไม่มีตัวคูณแล้ว (server ส่ง 1.0 มา) ⇒ ไม่ต้องมีแบนเนอร์บัฟ
    //    เช็คจากค่าที่ server ส่งจริง ไม่ hardcode → เปิดโบนัสกลับเมื่อไหร่ แบนเนอร์กลับมาเอง
    const _any = (f, ...k) => !!f && k.some(x => (+f[x] || 1) > 1);
    if (!_any(gwf, 'e', 'g')) gwf = null;
    if (!_any(cwf, 'e', 'd')) cwf = null;
    if (!gwf && !cwf) { _warFlagBanner('gw-flag-banner', '', GW, row); _warFlagBanner('cw-flag-banner', '', CW, row); return; }
    if (gwf && cwf) {
      _warFlagBanner('gw-flag-banner', '🚩🌍 EXP ×' + _mx((+gwf.e || 1.25) * (+cwf.e || 1.1))
                     + ' · G ×' + _mx(+gwf.g || 1.25) + ' · DROP ×' + _mx(+cwf.d || 1.1),
                     'linear-gradient(90deg,#7c3aed,#0d9488)', row);
      _warFlagBanner('cw-flag-banner', '', CW, row + 1); // '' = ลบทิ้ง (รวมไปอยู่บรรทัดบนแล้ว)
      return;
    }
    _warFlagBanner('gw-flag-banner', gwf ? '🚩 EXP ×' + _mx(+gwf.e || 1.25) + ' · G ×' + _mx(+gwf.g || 1.25) : '', GW, row);
    _warFlagBanner('cw-flag-banner', cwf ? '🌍 EXP ×' + _mx(+cwf.e || 1.1) + ' · DROP ×' + _mx(+cwf.d || 1.1) : '', CW, row);
  }
  function warpToMap(mapId) {
    mapId = mapId|0;
    if (!player || mapId === currentMap) { closeMapSelect(); return; }
    $.post(baseUrl + 'xhrpg_warp.php', { line_uid: player.line_uid, target_map: mapId })
      .done(res => {
        let d; try { d = typeof res === 'string' ? JSON.parse(res) : res; }
        catch (e) { closeMapSelect(); alert(T('วาร์ปไม่สำเร็จ: ตอบกลับผิดรูปแบบ')); return; }
        if (d && d.ok) {
          currentMap = d.map; player.map = d.map;
          player.x = d.x; player.y = d.y; player.explore_cx = d.x; player.explore_cy = d.y;
          delete smoothPos['player'];                 // snap ตัว+กล้อง (วาร์ปข้าม map)
          currentSpotId = 0; travelingToSpot = null;  // รีเซ็ตโซนที่เลือก → leash ใช้ spot 0 ของ map ใหม่
          const _sel = document.getElementById('spot-select'); if (_sel) _sel.dataset.built = ''; // dropdown สร้างใหม่ตาม spots map ใหม่
          _haveMon = false;                            // force have_static=0 → server ส่ง spots ของ map ใหม่
          buildGround();                               // สร้างพื้น map ใหม่ (ทราย/หญ้า)
          // ⚠️ ต้องเรียก _homeBtnUpd เอง — เราตั้ง currentMap ไปแล้ว poll จะไม่เห็นการเปลี่ยนแมพ
          //    (บั๊กจริง 2026-08-17: วาร์ปออกจากดันกิลทางเมนูนี้ แล้วป้าย "ออกจากดัน" ค้างบนจอ กดก็ bad_param)
          closeMapSelect(); render(); updateHUD(); _homeBtnUpd();
          const _md = MAP_DEFS.find(m => m.id === mapId);
          const nm = _md ? T(_md.name) : T('แผนที่ {a}', {a: mapId});
          addLog([{type:'retreat', msg: T('🗺️ วาร์ปไป {a}!', {a: nm})}]);
        } else if (d && d.error === 'level_locked') {
          closeMapSelect(); alert(T('ต้องถึง Lv.{a} ก่อนวาร์ป', {a: d.need || 25})); // ใช้คำแปลฝั่ง client เสมอ — เดิม d.msg (ไทยล้วนจาก server) ทับคำแปลจนต่างชาติเห็นไทย (บั๊กจริง 2026-07-18)
        } else if (d && d.error === 'level_too_high') { // 🌱 แมพผู้เล่นใหม่ — Lv เกินเพดาน
          closeMapSelect(); alert(T('แมพนี้สำหรับผู้เล่นใหม่ Lv. ไม่เกิน {n}', {n: d.cap || 35}));
        } else { closeMapSelect(); alert(T('วาร์ปไม่สำเร็จ: ') + ((d && d.error) || '?')); }
      })
      .fail(xhr => { closeMapSelect(); addLog([{type:'dead', msg: T('❌ วาร์ปไม่สำเร็จ (เชื่อมต่อไม่ได้ HTTP {a})', {a: (xhr && xhr.status)})}]); });
  }
  // 🏡👥 แบนเนอร์ "กำลังเยี่ยมบ้านของ X" + ปุ่มออก — สร้าง/ลบตาม _homeView (เรียกทุก poll)
  //     ชื่อผ่าน textContent (กัน XSS — ชื่อผู้เล่นตั้งเองได้)
  function _homeVisitBanner() {
    const id = 'home-visit-banner';
    let el = document.getElementById(id);
    if (!_homeVisiting()) { if (el) el.remove(); return; }
    if (!el) {
      el = document.createElement('div');
      el.id = id;
      const txt = document.createElement('span'); txt.id = id + '-t';
      const btn = document.createElement('button');
      btn.textContent = '🚪 ' + T('ออก');
      btn.style.cssText = 'border:none;background:#fff;color:#166534;border-radius:999px;padding:4px 11px;font-size:11px;font-weight:800;cursor:pointer;font-family:inherit';
      btn.onclick = () => warpHome();
      el.appendChild(txt); el.appendChild(btn);
      _floatMount(el, 'top:8px;left:50%;transform:translateX(-50%);z-index:9990;display:flex;align-items:center;gap:8px;background:rgba(22,163,74,.94);color:#fff;border-radius:999px;padding:6px 8px 6px 14px;font-size:12px;font-weight:700;box-shadow:0 4px 14px rgba(2,8,23,.3);pointer-events:auto;max-width:94%;box-sizing:border-box'); // 📌 เกาะกรอบเกม
    }
    const t = document.getElementById(id + '-t');
    if (t) t.textContent = '🏡 ' + T('กำลังเยี่ยมบ้านของ {a}', { a: String(_homeView.name || '?').slice(0, 16) });
  }
  // 🏡👥 เข้าไปเดินในบ้านเพื่อน — warp map 5 พร้อม home_uid (server ตั้ง home_in = instance ของเจ้าของ)
  //     ทำอะไรกับบ้านไม่ได้ (server gate ด้วย home_in) · ออกด้วยปุ่มบ้านเดิม (home_exit)
  function homeEnterFriend(uid) {
    if (!player || !uid) return;
    document.getElementById('home-visit')?.remove();
    $.post(baseUrl + 'xhrpg_warp.php', { line_uid: player.line_uid, session_token: sessionToken || '', target_map: 5, home_uid: uid })
      .done(res => {
        let d; try { d = typeof res === 'string' ? JSON.parse(res) : res; } catch (e) { alert(T('วาร์ปไม่สำเร็จ: ตอบกลับผิดรูปแบบ')); return; }
        if (d && d.ok) {
          currentMap = d.map; player.map = d.map;
          player.x = d.x; player.y = d.y; player.explore_cx = d.x; player.explore_cy = d.y;
          delete smoothPos['player'];
          currentSpotId = 0; travelingToSpot = null;
          _haveMon = false;
          buildGround(); render(); updateHUD(); _homeBtnUpd(); // ⚠️ เหตุผลเดียวกับ warpToMap — poll ไม่เห็นการเปลี่ยนแมพ
          addLog([{ type: 'retreat', msg: T('🏡 เข้าเยี่ยมบ้านเพื่อนแล้ว — ดูอย่างเดียว') }]);
        } else if (d && d.error === 'in_colosseum') { alert(T('เข้าบ้านไม่ได้ขณะอยู่ในสนามประลอง'));
        } else if (d && d.error === 'home_not_found') { alert(T('ไม่พบบ้านของผู้เล่นคนนี้'));
        } else { alert(T('วาร์ปไม่สำเร็จ: ') + ((d && d.error) || '?')); }
      })
      .fail(xhr => addLog([{ type: 'dead', msg: T('❌ วาร์ปไม่สำเร็จ (เชื่อมต่อไม่ได้ HTTP {a})', {a: (xhr && xhr.status)}) }]));
  }
  // ⭐ ชื่อแมพในเมนูเปลี่ยนแผนที่ — แมพระดับดาวโชว์ "ไอคอนเดียวกับแมพต้นทาง" แล้วติดดาวเป็นป้ายมุมขวาบนของชื่อ
  //    (สไตล์เดียวกับธงประเทศบนตรากิล — _gdEmFlag)
  //    ⚠️ ชื่อที่แปลไว้ยังขึ้นต้นด้วย "⭐ " อยู่ และตัดออก "เฉพาะตอนโชว์เป็นป้าย" เท่านั้น
  //       ที่อื่น (ป้ายโซนบน HUD · ไอคอนแมพในแชท · ปุ่มเลือกโซนฟาร์มออฟไลน์) เป็น text ล้วน ติดป้ายไม่ได้
  //       ถ้าไปตัด ⭐ ออกจากคีย์ด้วย = ชื่อซ้ำกับแมพต้นทางเป๊ะ ผู้เล่นแยกไม่ออกว่าอยู่แมพไหน
  function _mapNameHtml(m) {
    const n = T(m.name);
    if (!m.star) return n;
    return '<span style="position:relative;display:inline-block">' + n.replace(/^⭐\s*/, '') +
      '<span title="' + T('⭐ แผนที่ระดับดาว') + '" style="position:absolute;top:-10px;right:-20px;font-size:17px;line-height:1;text-shadow:0 1px 2px rgba(0,0,0,.28)">⭐</span></span>';
  }
  function openMapSelect() {
    if (!player || document.getElementById('mapsel-ov')) return;
    const lv = player.lv || 1, cur = currentMap;
    const ov = document.createElement('div');
    ov.id = 'mapsel-ov';
    ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.55);z-index:99999;display:flex;align-items:center;justify-content:center';
    ov.onclick = (e) => { if (e.target === ov) closeMapSelect(); };
    // 📐 แมพเยอะขึ้น (10 รายการ) — การ์ดจำกัด 88vh · ลิสต์เลื่อนในตัว · หัวข้อ+ปุ่มปิดตรึง (เจ้าของแจ้งปุ่มปิดตกจอ 2026-07-25)
    ov.innerHTML = '<div style="background:#fff;border-radius:14px;padding:14px 16px;width:290px;max-width:90vw;max-height:88vh;display:flex;flex-direction:column;box-shadow:0 8px 32px rgba(0,0,0,.35)">' +
      '<div style="flex:none;font-weight:800;font-size:15px;margin-bottom:10px;text-align:center;color:#334155">' + T('🗺️ เปลี่ยนแผนที่') + '</div>' +
      '<div style="flex:1;min-height:0;overflow-y:auto;margin:0 -4px;padding:0 4px">' +
      MAP_DEFS.filter(m => !m.hide).map(m => { // 🏡 บ้านของฉัน (hide) ไม่อยู่ในเมนู — เข้าทางปุ่มบ้านซ้ายจอ
        const isCur = m.id === cur;
        const tooLow = lv < m.req, tooHigh = m.cap && lv > m.cap; // 🌱 map7/8 มีเพดาน Lv (cap) — เกินล็อก
        // ⭐ แมพดาวต้องมี Ragnalok ถึงเกณฑ์ด้วย (server เป็นตัวตัดสินจริงที่ xhrpg_warp.php — ตรงนี้แค่ทำปุ่มเทา + บอกเหตุผล)
        const ragLow = (m.ragReq || 0) > 0 && (player.rag_lv | 0) < m.ragReq;
        const lock = (tooLow || tooHigh || ragLow) && !isCur;
        let sub = isCur ? T('📍 อยู่ที่นี่')
          : m.cap ? (tooHigh ? T('🔒 เกิน Lv.{a} แล้ว', {a: m.cap}) : tooLow ? T('🔒 ต้องถึง Lv.{a}', {a: m.req}) : T('🌱 ผู้เล่นใหม่ · Lv. ≤{a}', {a: m.cap}))
          : (tooLow ? T('🔒 ต้องถึง Lv.{a}', {a: m.req})
             : ragLow ? T('🔒 ต้องมี Ragnalok Lv.{a}', {a: m.ragReq})
             : m.ragReq ? T('พร้อมวาร์ป · Lv.{a}+ · Ragnalok {b}+', {a: m.req, b: m.ragReq})
             : T('พร้อมวาร์ป · Lv.{a}+', {a: m.req}));
        if (m.id === 4) sub += '<div style="font-size:10px;color:#b45309;font-weight:700;margin-top:1px">' + T('⚔️ PVP อิสระ · {a} คนในสนาม', {a: _colN}) + '</div>'; // 🏛️ จำนวนคนสดจาก poll ล่าสุด
        return '<button ' + ((isCur || lock) ? 'disabled ' : '') + 'onclick="xhrpg.warpToMap(' + m.id + ')" ' +
          'style="display:flex;align-items:center;gap:12px;width:100%;padding:11px;margin-bottom:8px;border-radius:10px;border:2px solid ' +
          (isCur ? '#16a34a' : '#e5e7eb') + ';background:' + (isCur ? '#dcfce7' : (lock ? '#f1f5f9' : '#fff')) +
          ';cursor:' + ((isCur || lock) ? 'default' : 'pointer') + ';opacity:' + (lock ? '.55' : '1') + '">' +
          '<span style="font-size:24px">' + m.emoji + '</span>' +
          '<span style="flex:1;text-align:left"><div style="font-weight:700;color:#1e293b">' + _mapNameHtml(m) + '</div>' +
          '<div style="font-size:11px;color:' + (isCur ? '#16a34a' : '#94a3b8') + '">' + sub + '</div></span>' +
          (isCur ? '<span style="color:#16a34a;font-size:18px">✓</span>' : (lock ? '' : '<span style="color:#3b82f6;font-size:16px">➜</span>')) +
          '</button>';
      }).join('') +
      '</div>' +
      '<button onclick="xhrpg.closeMapSelect()" style="flex:none;width:100%;padding:9px;margin-top:8px;border:none;border-radius:10px;background:#e2e8f0;color:#475569;font-weight:600;cursor:pointer">' + (LANG() === 'th' ? 'ปิด' : T('ปิดหน้าต่าง')) + '</button>' +
      '</div>';
    document.body.appendChild(ov);
  }
  function closeMapSelect() { const ov = document.getElementById('mapsel-ov'); if (ov) ov.remove(); }

  function logout() {
    _pollStopped = true;
    if (pollTimer) clearTimeout(pollTimer);
    closePanel();
    const isGoogle = player && String(player.line_uid ?? '').startsWith('google_');
    if (isGoogle) {
      // ล้าง PHP session แล้ว reload หน้าปกติ (ไม่มี ?auth=google)
      $.post(baseUrl + 'xhrpg_logout.php').always(() => {
        window.location.replace(window.location.pathname);
      });
    } else if (typeof liff !== 'undefined' && liff.isLoggedIn()) {
      liff.logout();
      window.location.replace(window.location.pathname);
    } else {
      startDemo(baseUrl);
    }
  }

