  function createDemoMonsters() {
    // ⚡ เดโมเบา: spec ×1.5 (~16 ตัว) — เดิม ×3 (33 ตัว) มือถือหน่วงตั้งแต่หน้า login (เจ้าของรายงาน 2026-07-19)
    const spec3 = DEMO_MONSTERS_SPEC.concat(DEMO_MONSTERS_SPEC.slice(0, 5));
    const list = spec3.map((spec, i) => {
      const ang = (i / spec3.length) * Math.PI * 2 + Math.random() * 0.5;
      const r   = 55 + Math.random() * 135; // 55-190px รอบ SPAWN (กล้องตามฮีโร่ + leash คุมฉากไว้แถว plaza)
      return {
        id: i + 1, zone: spec.zone,
        x: Math.max(10, Math.min(MAP_W-10, SPAWN_X + Math.cos(ang)*r)),
        y: Math.max(10, Math.min(MAP_H-10, SPAWN_Y + Math.sin(ang)*r)),
        hp: spec.hp, hp_max: spec.hp, lv: 1 + Math.floor(Math.random()*3), is_dead: 0, dead_at: 0,
        move_speed: spec.spd, name: spec.name, sprite_color: spec.color,
        base_atk: spec.atk, base_exp: spec.exp, base_gold: spec.gold,
        loot_ammo_pistol: spec.ammo,
        sprite_emoji: DEMO_EMOJI[spec.name] || '👾',
      };
    });
    // MVP บอสใหญ่ 1 ตัว กลางจอ — ให้ผู้เล่นปลอมรุมยิง ดูอลังการ
    list.push({
      id: 9001, zone: 3, is_mvp: 1,
      x: SPAWN_X + 40, y: SPAWN_Y - 30,
      hp: 1200, hp_max: 1200, lv: 10, is_dead: 0, dead_at: 0,
      move_speed: 0.25, name: 'จอมมารรัตติกาล', sprite_color: '#7f1d1d',
      base_atk: 60, base_exp: 120, base_gold: 30, loot_ammo_pistol: 5,
      sprite_emoji: '👹',
    });
    return list;
  }

  function demostepToward(obj, tx, ty, spd) {
    const dx = tx - obj.x, dy = ty - obj.y;
    const d  = Math.hypot(dx, dy);
    if (d < 1) return;
    obj.x += (dx/d) * Math.min(spd, d);
    obj.y += (dy/d) * Math.min(spd, d);
    obj.x  = Math.max(10, Math.min(MAP_W-10, obj.x));
    obj.y  = Math.max(10, Math.min(MAP_H-10, obj.y));
  }

  function demoNewExplore() {
    // เดโม: จำกัดรัศมีเดินสำรวจรอบ plaza (สอดคล้อง soft leash 230px — ฉากสวยอยู่กลางเกาะ)
    const r = 60 + Math.random() * 90; // ~60-150px รอบ SPAWN
    const ang = Math.random() * Math.PI * 2;
    player._etx = Math.max(10, Math.min(MAP_W-10, SPAWN_X + Math.cos(ang)*r));
    player._ety = Math.max(10, Math.min(MAP_H-10, SPAWN_Y + Math.sin(ang)*r));
  }

  // ── ผู้เล่นปลอม (client-side, เฉพาะหน้า login — ไม่มีในเซิร์ฟเวอร์/DB) ──────────
  const DEMO_FAKE_NAMES = ['ShadowKnight','BladePro','Mage99','GodArcher','TreeKing','Thunder','DarkNinja','IronWizard','HeadHunter','ArcherZ','GoldShield','BowMaster']; // เดโม = ก่อน login = EN เสมอ (นโยบาย) — ชื่อปลอมเป็นอังกฤษ

  function createFakePlayers() {
    const n = 5 + Math.floor(Math.random() * 3); // ⚡ เดโมเบา: 5-7 คน (เดิม 10-14 — AI+เลเซอร์ต่อคนกินเฟรมมือถือ)
    const names = DEMO_FAKE_NAMES.slice().sort(() => Math.random() - 0.5);
    const arr = [];
    for (let i = 0; i < n; i++) {
      const ang = Math.random() * Math.PI * 2;
      const r = 70 + Math.random() * 150; // ใกล้กลาง (ในจอ) 70-220px
      const sniper = Math.random() < 0.4;
      arr.push({
        name: names[i % names.length], is_dead: 0,
        x: Math.max(10, Math.min(MAP_W-10, SPAWN_X + Math.cos(ang)*r)),
        y: Math.max(10, Math.min(MAP_H-10, SPAWN_Y + Math.sin(ang)*r)),
        _gun: sniper ? '🎯' : '🔫',
        _range: sniper ? 120 : 70,             // world px
        _spd: 2.5 + Math.random()*1.5,
        _cd: Math.floor(Math.random()*3),       // สลับจังหวะยิง
        _etx: null, _ety: null,
      });
    }
    return arr;
  }

  function runFakePlayerAI(fp) {
    // หาเป้าใกล้สุดในรัศมี DETECT ไม่งั้นวนรอบผู้เล่น (กล้อง) เพื่อให้อยู่ในจอเสมอ
    const DETECT = 360;
    let target = null, bestD = Infinity;
    monsters.forEach(m => { if (m.is_dead) return; const d = dist(m, fp); if (d < bestD) { bestD = d; target = m; } });

    if (!target || bestD > DETECT) { // ไม่มีเป้าใกล้ → วนรอบผู้เล่น
      if (!fp._etx || dist(fp, {x:fp._etx, y:fp._ety}) < 12) {
        const a = Math.random()*Math.PI*2, rr = 30 + Math.random()*120;
        fp._etx = Math.max(10, Math.min(MAP_W-10, (player.x||SPAWN_X) + Math.cos(a)*rr));
        fp._ety = Math.max(10, Math.min(MAP_H-10, (player.y||SPAWN_Y) + Math.sin(a)*rr));
      }
      demostepToward(fp, fp._etx, fp._ety, fp._spd);
      return;
    }
    if (bestD > fp._range) { demostepToward(fp, target.x, target.y, fp._spd + 1.5); return; } // ไล่
    if (fp._cd > 0) { fp._cd--; return; }  // cooldown
    fp._cd = 2; // ⚡ เดโมเบา: ยิงทุก 3 tick (เดิมทุก 2) — ลดจำนวนเลเซอร์/FX ค้างจอพร้อมกัน
    spawnBullet(fp.x, fp.y, target.x, target.y, fp._gun); // เลเซอร์
    target.hp -= (fp._gun === '🎯' ? 60 : 38);
    if (target.hp <= 0) {
      target.hp = 0; target.is_dead = 1; target.dead_at = Date.now();
      const _gk = smoothPos['m' + target.id] || target; // ศพวางที่ตำแหน่งที่ตาเห็นจริง
      _pushMonGhost(target, _gk.x, _gk.y, true);
      deathMarkers.push({ x: target.x, y: target.y, born: performance.now(), icon: fp._gun });
      startAnim();
      if (target.is_mvp ? true : Math.random() < 0.35) {
        const tag = target.is_mvp ? '⭐ <b style="color:#ff4444">MVP</b> ' : '';
        addLog([{ type:'kill', msg:`🧑${fp.name}💀 ${tag}${target.sprite_emoji||'👾'} Lv.${target.lv||1}! EXP+${target.base_exp||10} G+${target.base_gold||3}` }]);
      }
    }
  }

  function fetchDemoOnline() {
    $.getJSON(baseUrl + 'xhrpg_online_count.php').done(d => {
      if (d && d.online_count != null) {
        const el = document.getElementById('online-count-label');
        if (el) el.textContent = T('ออนไลน์') + ' ' + d.online_count;
      }
    });
  }

  // ── สถานะเดโมฝั่ง client ทั้งหมด (ไม่มี network — ตัวเลข/เอฟเฟกต์จำลองในเครื่องล้วน) ──
  let _demoTickN = 0;       // ตัวนับ tick เดโม — คุมจังหวะ (โดนตี/ทองหยอด/สลับทิศ strafe)
  let _demoRailAt = 0;      // เวลายิง railgun ไททันครั้งล่าสุด (ยิงทุก ~5s)
  let _demoStrafeSign = 1;  // ทิศ strafe ค้างไว้หลาย tick — ขยับข้างนุ่มๆ ไม่สั่น
  const DEMO_DROP_ICONS = ['🪵','🪨','⚙️','🟫','🌿','💊','💎']; // ชุด icon เดียวกับ groundLoot ที่ดรอปในเกมจริง

  // ── ฆ่ามอนเดโม: เอฟเฟกต์ชุดเดียวกับ event kill จริง (X แดง + 💰 เด้ง + ของหล่นพื้น + บรรทัด log) ──
  function _demoKillFx(m, icon) {
    if (m.is_dead) return;
    m.hp = 0; m.is_dead = 1; m.dead_at = Date.now();
    const _kp = smoothed('m' + m.id, m.x, m.y); // จุดตาย = ตำแหน่ง smoothed ที่สไปรต์ถูกวาดจริง (สูตรเดียวกับ _monFxPos)
    _pushMonGhost(m, _kp.x, _kp.y, true); // ศพค้าง — ชุดเดียวกับ kill จริง
    deathMarkers.push({ x: _kp.x, y: _kp.y, born: performance.now(), icon: icon || '⚔️' });
    if (lootPops.length < 24) lootPops.push({ x: _kp.x, y: _kp.y - 8, spr: 'prop_money', born: performance.now() }); // 💰 เด้งตอนฆ่า
    if (groundLoot.length < 30 && Math.random() < 0.5) { // ของหล่นพื้นเป็นครั้งคราว (⚡ เดโมเบา: cap 30 — เดิม 60 กองจนกินเฟรม)
      const ic = DEMO_DROP_ICONS[Math.floor(Math.random() * DEMO_DROP_ICONS.length)];
      groundLoot.push({ x: _kp.x + 6, y: _kp.y + 4, icon: ic, born: performance.now() });
    }
    const exp = m.base_exp || 10, gold = m.base_gold || 3;
    player.exp += exp; player.gold += gold;
    const need = expNextHero(player.lv);
    if (player.lv < MAX_LV && player.exp >= need) { // 🧢 cap Lv60 (demo · เส้นฮีโร่)
      player.exp -= need; player.lv++; player.hp_max += 10; player.hp = player.hp_max;
      addLog([{ type:'levelup', msg:`🎉 LEVEL UP! Lv.${player.lv - 1} → Lv.${player.lv} — Stat Point +1` }]); // เดโม = EN เสมอ
    }
    // บรรทัดฆ่ารูปแบบเดียวกับเกมจริง — ขึ้น #mini-log + panel ผ่าน addLog (client ล้วน ไม่ยิงเซิร์ฟเวอร์)
    const who = (icon === '🪓' || icon === '⚡') ? `🤖${icon}` : `🧑${icon}`;
    const tag = m.is_mvp ? '⭐ <b style="color:#ff4444">MVP</b> ' : '';
    addLog([{ type:'kill', msg:`${who}💀 ${tag}${m.sprite_emoji || '👾'} Lv.${m.lv || 1}! EXP+${exp} G+${gold}` }]);
    startAnim();
  }

  // ── ไททัน Bob เดโม: ประกบเป้าของฮีโร่ → ฟันขวานทุก tick + railgun เหลืองทุก ~5s (วาดผ่าน drawRobot key 'robot' เดิม) ──
  function _runDemoRobot(target, now) {
    if (player.robot_x == null) { player.robot_x = player.x + 15; player.robot_y = player.y; }
    let tx, ty;
    if (target && dist(target, player) <= 200) {
      // วาร์ปเข้าประชิดเป้า — เยื้องมาฝั่งฮีโร่ ~14px ไม่ทับสไปรต์มอน
      const dx = player.x - target.x, dy = player.y - target.y, d = Math.hypot(dx, dy) || 1;
      tx = target.x + (dx / d) * 14; ty = target.y + (dy / d) * 14;
    } else { tx = player.x + 15; ty = player.y; } // ไม่มีเป้า → เดินเคียงข้างฮีโร่
    const rob = { x: player.robot_x, y: player.robot_y };
    demostepToward(rob, tx, ty, 18); // ก้าวไว — smoothing key 'robot' เกลี่ยให้ไหลลื่นเองใน drawRobot
    player.robot_x = rob.x; player.robot_y = rob.y;
    if (!target || target.is_dead) return;

    const rd = Math.hypot(target.x - rob.x, target.y - rob.y);
    const _ro = smoothed('robot', player.robot_x, player.robot_y); // จุดออกเอฟเฟกต์ = ตำแหน่งไททันที่วาดจริง (สูตร _fxOrigin)
    const _rt = smoothed('m' + target.id, target.x, target.y);     // ปลายทาง = ตำแหน่งมอนที่วาดจริง (สูตร _monFxPos)
    if (now - _demoRailAt > 5000 && rd <= 110) {
      // railgun: icon '⚡' → spawnBullet วาด laser เหลืองหนาเหมือนไททันจริง + ดาเมจก้อนใหญ่
      _demoRailAt = now;
      spawnBullet(_ro.x, _ro.y, _rt.x, _rt.y, '⚡');
      _rAtkUntil = Date.now() + 700; // เล่นท่าโจมตี (เหมือน ROBOT_ICONS ใน poll จริง)
      const dmg = 45 + Math.floor(Math.random() * 26); // 45-70
      spawnFloatText(_rt.x, _rt.y - 8, '-' + dmg, '#facc15', 12);
      _hitFlash[target.id] = Date.now() + 120;
      target.hp -= dmg; startAnim();
      if (target.hp <= 0) { _demoKillFx(target, '⚡'); return; }
    }
    if (rd <= 26) {
      // ขวานประชิด: icon '🪓' → melee icon จิ้มที่ตัวมอน + ท่า attack + เสียงขวาน (สูตรเดียวกับ e.icon '🪓')
      spawnBullet(_ro.x, _ro.y, _rt.x, _rt.y, '🪓');
      _rAtkUntil = Date.now() + 700; sfxAxe();
      const dmg = 10 + Math.floor(Math.random() * 9); // 10-18
      spawnFloatText(_rt.x, _rt.y - 8, '-' + dmg, '#f8fafc', 9);
      _hitFlash[target.id] = Date.now() + 120;
      target.hp -= dmg; startAnim();
      if (target.hp <= 0) _demoKillFx(target, '🪓');
    }
  }

  function runDemoTick() {
    if (!player || player.line_uid !== 'demo') return; // เดโมเท่านั้น — login แล้วห้ามแตะ state เกมจริง
    _demoTickN++;
    const now = Date.now();

    // ── Respawn มอนตายหลัง ~4s — เกิดใหม่ห่างฮีโร่ 100-220px (กล้องตามฮีโร่แล้ว → มีเป้าให้เดินไล่เสมอ) ──
    monsters.forEach(m => {
      if (!m.is_dead || !m.dead_at || now - m.dead_at < 4000) return;
      const a = Math.random() * Math.PI * 2, rr = 100 + Math.random() * 120;
      m.x = Math.max(10, Math.min(MAP_W - 10, player.x + Math.cos(a) * rr));
      m.y = Math.max(10, Math.min(MAP_H - 10, player.y + Math.sin(a) * rr));
      if (!m.is_mvp) m.lv = 1 + Math.floor(Math.random() * 3); // สุ่ม Lv 1-3 ใหม่ (MVP คง Lv เดิม)
      m.hp = m.hp_max; m.is_dead = 0; m.dead_at = 0;
      delete smoothPos['m' + m.id]; // จุดเกิดใหม่ → ตัด smoothing เก่าทิ้ง (กันสไปรต์ไหลข้ามแมพ)
      delete _monSeen[m.id];        // เริ่ม fade-in ใหม่ที่จุดเกิด (id เดิมถูก reuse)
    });

    // ── Player respawn (กันเหนียว — ปกติพื้น HP ด้านล่างกันตายอยู่แล้ว) ──
    if (player.is_dead) {
      player.x = SPAWN_X; player.y = SPAWN_Y;
      player.hp = Math.max(1, Math.floor(player.hp_max * 0.3));
      player.is_dead = 0;
      render(); updateHUD(); return;
    }

    // ── HP: อมตะแบบเดโม (ฟื้นไว + พื้น HP 45% ไม่เข้าโหมดถอย) — คงพฤติกรรมเดิม ──
    player.hp_potion = 5; // เติมยาเดโมไม่ให้หมด
    const regen = Math.max(5, Math.ceil(player.hp_max * 0.12)); // ฟื้น ~12%/tick
    if (player.hp < player.hp_max) player.hp = Math.min(player.hp_max, player.hp + regen);
    if (player.hp < player.hp_max * 0.45) player.hp = Math.floor(player.hp_max * 0.45); // กัน HP ตกจนติดโหมดถอย

    // ── มอน: ใกล้ฮีโร่ ≤180px → ไล่ช้าๆ 4.5px/tick · ไกลกว่า → เดินเรื่อยเปื่อย (ตำแหน่งไหลลื่นผ่าน smoothing เดิม) ──
    monsters.forEach(m => {
      if (m.is_dead) return;
      const d = dist(m, player);
      if (d <= 180 && d > 14) demostepToward(m, player.x, player.y, 5.8);
      else if (d > 180) {
        if (m._etx == null || dist(m, { x: m._etx, y: m._ety }) < 6) {
          const a = Math.random() * Math.PI * 2, rr = 20 + Math.random() * 50;
          m._etx = Math.max(10, Math.min(MAP_W - 10, m.x + Math.cos(a) * rr));
          m._ety = Math.max(10, Math.min(MAP_H - 10, m.y + Math.sin(a) * rr));
        }
        demostepToward(m, m._etx, m._ety, (m.move_speed || 0.4) * 3);
      }
    });

    // ── หาเป้าใกล้สุด ─────────────────────────────────────────
    let nearest = null, bestD = Infinity;
    monsters.forEach(m => {
      if (m.is_dead) return;
      const d = dist(m, player);
      if (d < bestD) { bestD = d; nearest = m; }
    });

    const RANGE = 90; // ระยะปืนพกเดโม (72+18 = วงเหลืองที่ drawRange วาดจริง)

    // ── เดิน/kite: เข้าหาเป้า ~17px/tick · ประชิด <24px ถอยตั้งระยะ · 24-90px สไลด์ข้างเบาๆ · leash 230px รอบ plaza ──
    if (dist(player, { x: SPAWN_X, y: SPAWN_Y }) > 230) {
      demostepToward(player, SPAWN_X, SPAWN_Y, 17); // soft leash: เกินรัศมี plaza → เดินกลับ (ฉากสวยคงอยู่)
    } else if (nearest && bestD > RANGE) {
      demostepToward(player, nearest.x, nearest.y, 17); // เดินเข้าหาเป้าความเร็วเกมจริง — drawPlayer หันตามทางเอง
    } else if (nearest && bestD < 24) {
      const kx = player.x + ((player.x - nearest.x) / (bestD || 1)) * 20; // back-step ถอยตั้งระยะ
      const ky = player.y + ((player.y - nearest.y) / (bestD || 1)) * 20;
      demostepToward(player, kx, ky, 17);
    } else if (nearest) {
      if (_demoTickN % 6 === 0) _demoStrafeSign = Math.random() < 0.5 ? -1 : 1; // สลับทิศนานๆ ครั้ง — ไม่ jitter
      const ax = (nearest.x - player.x) / (bestD || 1), ay = (nearest.y - player.y) / (bestD || 1);
      demostepToward(player, player.x - ay * 6 * _demoStrafeSign, player.y + ax * 6 * _demoStrafeSign, 6); // strafe เล็กๆ
    } else {
      // ไม่มีมอนเป็นเลย (รอ respawn) → เดินสำรวจรอบ plaza ต่อ
      if (!player._etx || dist(player, { x: player._etx, y: player._ety }) < 10) demoNewExplore();
      demostepToward(player, player._etx, player._ety, 17);
    }

    // ── ยิง: ในระยะ → รัว 3 นัด stagger ~250ms (เลเซอร์+แว่บไฟ+เลขดาเมจ+มอนแว่บขาว — pipeline เดียวกับปืนพกจริง) ──
    if (nearest && bestD <= RANGE) {
      targetMonsterId = nearest.id; // ล็อกเป้า → เส้นแดง + 🎯 + drawPlayer หันเข้าเป้า
      const mref = nearest, mid = nearest.id;
      _pShotMid = nearest.id;
      _pShotAng = Math.atan2(nearest.y - player.y, nearest.x - player.x); // หันตามทิศนัดจริง (กันหันสวนเลเซอร์)
      _pShotUntil = now + 340 + 500;
      for (let i = 0; i < 3; i++) {
        setTimeout(() => {
          if (!player || player.line_uid !== 'demo' || mref.is_dead) return; // login แล้ว/เป้าตาย → ทิ้งนัดค้าง
          const _o = smoothed('player', player.x, player.y);   // จุดยิง = ตำแหน่งสไปรต์จริง (สูตร _fxOrigin)
          const _t = smoothed('m' + mid, mref.x, mref.y);      // ปลายทาง = ตำแหน่งมอนที่วาดจริง (สูตร _monFxPos)
          spawnBullet(_o.x, _o.y, _t.x, _t.y, '🔫');
          const crit = Math.random() < 0.12;
          const dmg = (15 + Math.floor(Math.random() * 11)) * (crit ? 2 : 1); // 15-25 (คริ ×2)
          spawnFloatText(_t.x, _t.y - 8, (crit ? '💥-' : '-') + dmg, crit ? '#facc15' : '#f8fafc', crit ? 12 : 9);
          _hitFlash[mid] = Date.now() + 120;
          _pMuzzleUntil = Date.now() + 120; sfxShoot(); startAnim();
          mref.hp -= dmg;
          if (mref.hp <= 0) _demoKillFx(mref, '🔫');
        }, i * 250);
      }
      player.ammo_pistol = player.ammo_pistol > 3 ? player.ammo_pistol - 3 : 30; // นับกระสุนหลอก (หมดแล้วเติมเอง)
    } else {
      targetMonsterId = null;
    }

    // ── โดนตีโชว์บ้าง: มอนประชิด <18px ทุก ~3 tick → วงแดงวาบ + เลขแดงลอย + มอนพุ่งใส่ (สูตรเดียวกับ mon_atk) · ~30% หลบได้ → กลิ้ง + MISS (สูตรเดียวกับ dodge) ──
    if (nearest && bestD < 18 && _demoTickN % 3 === 0) {
      const _hpp = smoothed('player', player.x, player.y);
      if (Math.random() < 0.3) {
        _heroRollUntil = now + 600; // นักธนูกลิ้งหลบ
        spawnFloatText(_hpp.x, _hpp.y - 12, 'MISS', '#f59e0b', 9);
      } else {
        _heroHitUntil = now + 250;
        const hdmg = 3 + Math.floor(Math.random() * 6);
        spawnFloatText(_hpp.x, _hpp.y - 12, '-' + hdmg, '#ff3b3b', 19, { life: 1000, rise: 26, pop: true });
        player.hp = Math.max(Math.floor(player.hp_max * 0.45), player.hp - hdmg); // อมตะเดโม — ไม่ต่ำกว่าพื้น HP
      }
      const _asp = smoothed('m' + nearest.id, nearest.x, nearest.y);
      const _adx = _hpp.x - _asp.x, _ady = _hpp.y - _asp.y, _ad = Math.hypot(_adx, _ady) || 1;
      _lungeAnim[nearest.id] = { dx: (_adx / _ad) * 12, dy: (_ady / _ad) * 12, born: performance.now(), life: 240 };
      startAnim();
    }

    _runDemoRobot(nearest, now); // ไททัน Bob: ประกบเป้า + ขวาน/railgun

    // ── HUD มีชีวิต: EXP ไหลขึ้นช้าๆ + ทองหยอดเป็นครั้งคราว (ตัวเลขฝั่ง client ล้วน) ──
    player.exp += 1;
    if (_demoTickN % 5 === 0) player.gold += 1 + Math.floor(Math.random() * 3);

    others.forEach(runFakePlayerAI); // ผู้เล่นปลอมเดิน/ยิงมอน (ของเดิม)
    _snapGen++; // ปิดรอบ = ประกาศ snapshot ใหม่ให้ระบบ smoothing (จังหวะเดียวกับจบ poll จริง) — ตัวที่หยุดนิ่ง re-anchor เนียน
    render(); updateHUD();
  }

  function startDemo(url) {
    baseUrl = url || baseUrl;
    applyLang(); // 🌐 demo/ก่อน login = English เสมอ (_preLogin ยัง true) — แปล chrome static ทันที
    if (pollTimer)  { clearTimeout(pollTimer);  pollTimer  = null; }
    if (demoTimer)  { clearInterval(demoTimer); demoTimer  = null; }

    // Init canvas if not done yet
    if (!canvas) {
      canvas = document.getElementById('gameCanvas');
      canvas.width = DISPLAY_W; canvas.height = DISPLAY_H;
      ctx = canvas.getContext('2d');
      mini = document.getElementById('minimapCanvas');
      mini.width = 80; mini.height = 80;
      mCtx = mini.getContext('2d');
      buildTiles();
      loadSummerTiles();
      window.addEventListener('resize', resizeCanvas);
    }

    // Set demo player & monsters
    player   = Object.assign({}, DEMO_PLAYER);
    player.robot_x = SPAWN_X + 15; player.robot_y = SPAWN_Y; // ไททัน Bob เริ่มข้างฮีโร่ (เดโมขยับเองใน tick)
    _demoTickN = 0; _demoRailAt = 0; // รีเซ็ตจังหวะเดโม (logout → demo รอบใหม่)
    for (const k in smoothPos) delete smoothPos[k]; // ล้าง smoothing ค้างจากเซสชันก่อนหน้า — เริ่มฉากใหม่ไม่ไหลข้ามแมพ
    for (const k in _monSeen) delete _monSeen[k];   // ล้างเวลาแรกเห็น — ฉากใหม่ fade-in ใหม่หมด
    monGhosts.length = 0;                           // ล้างศพค้างข้ามฉาก
    _dyingMons.length = 0;                          // ล้างมอนที่ค้างฉากตายข้ามฉาก
    _interpMs = 1350; _lastSnapAt = 0;              // รีเซ็ตคาบ interpolation (เดโม tick = POLL_MS เป๊ะ / login ใหม่วัดใหม่)
    monsters = createDemoMonsters();
    monsters.push({ // MVP ปลอมกลางจอ ให้ผู้เล่นปลอมรุมตี (id ไม่ซ้ำกับ MVP ใน createDemoMonsters)
      id: 9002, zone: 1, x: SPAWN_X + 70, y: SPAWN_Y - 55,
      hp: 1500, hp_max: 1500, lv: 15, is_dead: 0, dead_at: 0,
      move_speed: 0.25, name: 'ราชาค้างคาว', sprite_color: '#ff4444',
      sprite_emoji: '🦇', base_atk: 30, base_exp: 200, base_gold: 55,
      loot_ammo_pistol: 4, is_mvp: true,
    });
    others   = createFakePlayers();

    resizeCanvas();
    _syncDpad(); // เดโม: ซ่อน D-pad เสมอ
    render(); updateHUD(); renderGuns(); renderItems(); renderStats();

    // Show login overlay, hide logout button, disable menu
    document.getElementById('login-overlay').style.display = 'flex';
    document.getElementById('logout-btn').style.display    = 'none';
    document.querySelectorAll('.menu-icon-btn, #open-log-btn').forEach(b => { b.disabled = true; b.classList.add('menu-locked'); });

    demoTimer = setInterval(runDemoTick, POLL_MS); // จังหวะเดียวกับ poll เกมจริง (1.0s)
    startAnim(); // render loop ต่อเนื่อง → demo ลื่น (smoothing ไหลระหว่าง tick)

    demoLogIdx = 0;
    const _demoEntry = () => { const e = DEMO_LOGS[demoLogIdx++ % DEMO_LOGS.length]; return { type: e.type, msg: T(e.msg) }; }; // แปลตอน push (สลับภาษาแล้ว log ใหม่ตามภาษา)
    addLog([_demoEntry()]);
    demoLogTimer = setInterval(() => {
      const entry = _demoEntry();
      const delay = 800 + Math.random() * 1200;
      setTimeout(() => addLog([entry]), delay);
    }, 2200);

    // ตัวนับออนไลน์ — เลขจริงจาก DB (รีเฟรชทุก 15s)
    fetchDemoOnline();
    if (demoOnlineTimer) clearInterval(demoOnlineTimer);
    demoOnlineTimer = setInterval(fetchDemoOnline, 15000);
  }

  // ── Init ──────────────────────────────────────────────────────────────────
  function init(p, url, token) {
    console.log('xhrpg canvas build: droptab-2026-07-17'); // 🏷️ ตรวจเวอร์ชัน JS ถึงเครื่องจริง (F12 → Console)
    player  = p;
    baseUrl = url;
    if (p && p.map != null) currentMap = _groundMap = (p.map | 0); // seed แผนที่จริงจากตัวละครก่อน bake พื้น — กัน buildGround สร้าง map1 แล้ว poll แรกค่อย rebuild (แวบไปทุ่งกลางก่อนโหลดทะเลทราย)
    _homeBtnUpd(); // 🏡 icon ปุ่มบ้านตรงกับแมพตั้งแต่ login (ค้างอยู่ในบ้าน = โชว์ปุ่มออก)
    sessionToken = token || null;
    _pollStopped = false; // ล้าง flag จาก logout→demo บนหน้าเดิม — login ใหม่แล้ว poll ต้องเดินต่อ
    // 😴 เริ่มนับนาฬิกา "พักจอ / human-check / เช็คอิน" ตรงนี้ = ตอนเข้าเกมจริง
    //    🐛 แก้ 2026-08-17 (เจ้าของแจ้ง "จอพักจอชอบเด้งมาเองตอน login เสร็จ"):
    //       ตัวแปรพวกนี้ถูกตั้งค่าตอน **สคริปต์โหลด** ไม่ใช่ตอนเข้าเกม ⇒ ถ้าค้างหน้า login /
    //       เดโม / รอ OAuth นานเกินเพดานพักจอ (VIP0 = 10 นาที) พอ login เสร็จ schedulePoll()
    //       รอบแรกจะเห็น "ไม่มี input เกินเพดาน" ทันที → เด้งจอเฝ้าบอทเลยทั้งที่เพิ่งเข้ามา
    //    หลักการเดียวกับฝั่ง server (game.php $_freshSession): **นับเฉพาะเวลาที่อยู่ในเกมจริง**
    //    🔒 ไม่เปิดช่องบอท: รีเซ็ตได้เฉพาะตอน init() = ต้อง login ใหม่จริง ๆ เท่านั้น
    _lastInputAt = Date.now(); _actFlag = true;
    _lastHumanPassAt = Date.now(); _humanUntil = Date.now() + 150000; _idleSuspect = false; _bmWhy = 'idle';
    _chLastPassAt = Date.now(); _chForce = false; _chCoolUntil = Date.now() + _chCoolMs();
    _chClear(); _bmClose(); // เผื่อค้างจากเซสชันก่อนบนหน้าเดิม (logout→demo→login) — _bmOn ค้าง = schedulePoll บล็อก poll ถาวร
    _syncSfxBtn(); _syncLockBtn(); applyMiniLogVis(); // ตั้งปุ่มเสียง/LOCK/mini-log ตามค่าที่บันทึกไว้
    _preLogin = false; // login จริงแล้ว — เข้าลำดับภาษาปกติ (ก่อนหน้านี้บังคับ English)
    applyLang(); // 🌐 แปล UI static ตามภาษา (override ผู้เล่น > region > browser) — region จาก poll แรกจะ re-apply เองถ้าเปลี่ยน
    // 🌐 login ครั้งแรกที่ยังไม่เคยเลือกภาษาบนเครื่องนี้ → เด้ง picker ให้เลือกเลย (ครั้งเดียวต่อเครื่อง)
    //    default ไฮไลต์ = ภาษาตามประเทศ (CF_REGION ฝังตอน render) · แตะพื้นหลังปิด = คง auto · เปลี่ยนทีหลังได้ที่ปุ่มภาษา
    try {
      if (!_langOv && !localStorage.getItem('xhrpg_lang_prompted')) {
        _langPromptPending = true; // เนื้อเรื่อง/onboarding จะรอต่อคิวหลัง picker ปิด (ดูบล็อกล่าง)
        setTimeout(() => { // 1200ms = หลัง popup รางวัล offline (800ms) — picker append ทีหลัง + z สูงกว่า = อยู่บนสุดเสมอ
          try { localStorage.setItem('xhrpg_lang_prompted', '1'); } catch (e) {} // เซ็ต flag ตอนแสดงจริง (ไม่ใช่ตอนตั้งเวลา) — พลาดรอบนี้ยังเด้งรอบหน้า
          openLangPicker();
        }, 1200);
      }
    } catch (e) {}
    _syncDpad(); // D-pad โชว์เฉพาะตอน AUTO OFF

    // inject session_token อัตโนมัติทุก $.post ไปยัง endpoint เกม
    const _origPost = $.post.bind($);
    $.post = function(url, data, ...rest) {
      if (data && typeof data === 'object' && sessionToken) {
        data.session_token = sessionToken;
      }
      return _origPost(url, data, ...rest);
    };

    canvas = document.getElementById('gameCanvas');
    canvas.width  = DISPLAY_W; canvas.height = DISPLAY_H;
    ctx = canvas.getContext('2d');

    mini = document.getElementById('minimapCanvas');
    mini.width = 80; mini.height = 80;
    mCtx = mini.getContext('2d');

    buildTiles();
    loadSummerTiles();
    resizeCanvas();
    window.addEventListener('resize', resizeCanvas);

    // Stop demo if running
    if (demoTimer) { clearInterval(demoTimer); demoTimer = null; }
    if (demoLogTimer) { clearInterval(demoLogTimer); demoLogTimer = null; }
    if (demoOnlineTimer) { clearInterval(demoOnlineTimer); demoOnlineTimer = null; }
    document.getElementById('login-overlay').style.display = 'none';
    document.getElementById('logout-btn').style.display    = 'block';
    document.querySelectorAll('.menu-icon-btn, #open-log-btn').forEach(b => { b.disabled = false; b.classList.remove('menu-locked'); });

    pollTimer = setTimeout(poll, POLL_MS);
    render(); updateHUD(); renderStats(); renderGuns(); renderItems();

    // แสดง story popup + onboarding ครั้งแรก (story ก่อน → onboarding ต่อ)
    // 🌐 ถ้าจะเด้ง picker เลือกภาษา → เนื้อเรื่องรอต่อคิวหลังเลือกเสร็จ (เนื้อเรื่องจะเป็นภาษาที่เพิ่งเลือกพอดี)
    const storyKey = 'xhrpg_story_seen_' + (p.line_uid || '');
    const onbKey   = 'xhrpg_onboarded_' + (p.line_uid || '');
    const needStory = !localStorage.getItem(storyKey);
    const needOnb   = !localStorage.getItem(onbKey);
    const _startIntro = () => {
      if (needStory) {
        try { localStorage.setItem(storyKey, '1'); } catch (e) {}
        showStoryPopup(needOnb ? () => showOnboarding(onbKey) : null);
      } else if (needOnb) showOnboarding(onbKey);
    };
    if (needStory || needOnb) {
      if (_langPromptPending) _afterLangPickCb = _startIntro; // รอ picker ปิดก่อน
      else setTimeout(_startIntro, 800);
    }
  }

  function setDir(dir) {
    manualDir = manualDir === dir ? null : dir;
    document.querySelectorAll('.dpad-btn').forEach(b => b.classList.remove('active'));
    if (manualDir) document.getElementById('dpad-' + manualDir)?.classList.add('active');
  }

  // ── D-pad overlay: โชว์เฉพาะตอน AUTO OFF (คุมเอง) · เดโม/ก่อน login ซ่อนเสมอ ──
  function _syncDpad() {
    const d = document.querySelector('.dpad-wrap');
    if (!d) return;
    const isDemo = !player || player.line_uid === 'demo';
    d.classList.toggle('show', !botEnabled && !isDemo);
  }

  function toggleBot() {
    botEnabled = !botEnabled;
    if (botEnabled && player) {
      // จำตำแหน่ง ณ ตอนเปิด AUTO ON เป็นจุดอ้างอิงรัศมีสำรวจ
      player.explore_cx = player.x;
      player.explore_cy = player.y;
    }
    const btn = document.getElementById('bot-toggle-btn');
    if (btn) {
      btn.textContent  = botEnabled ? '🤖 AUTO ON' : '🤖 AUTO OFF';
      btn.style.background = botEnabled ? '#16a34a' : '#4b5563';
    }
    _syncDpad();
  }

  function setExploreRadius(r) {
    exploreRadius = r;
    // reset center to current position + force new target
    if (player) {
      player.explore_cx = player.x;
      player.explore_cy = player.y;
      delete player.explore_tx; delete player.explore_ty;
    }
    _syncExploreBtns();
  }
  // ไฮไลต์ปุ่มรัศมีให้ตรงกับ exploreRadius จริงเสมอ — ถ้าค่า auto-leash ของโซน (เช่น ทะเลทราย 133m) ไม่ตรงปุ่มไหน = ไม่ไฮไลต์ (สื่อว่ายังไม่ได้เลือกเอง คลิกปุ่มเพื่อกำหนดระยะสำรวจ)
  function _syncExploreBtns() {
    const cur = Math.round(exploreRadius);
    document.querySelectorAll('.er-btn').forEach(b => {
      const v = parseInt((b.id || '').replace('er-', '')) || 0;
      b.classList.toggle('active', v === cur);
    });
    const ec = document.getElementById('er-current'); // ปุ่มบน HUD (ใต้ LOCK ATK) โชว์รัศมีที่เลือก
    if (ec) ec.textContent = `📍 ${cur}m`;
  }
  // คลิกปุ่ม HUD → วนรัศมี 100→150→200→300 (ค่าที่ไม่อยู่ในชุด → เริ่ม 100)
  function cycleExploreRadius() {
    const presets = [100, 150, 200, 300];
    const i = presets.indexOf(Math.round(exploreRadius));
    setExploreRadius(presets[(i + 1) % presets.length]);
  }

  // ── 🌙 Offline Zone Farm — เลือกโซนฟาร์มตอนออฟไลน์ (สูงสุด 3 โซน) ────────────
  let _offSel = new Set();   // โซนที่เลือก — key "map:zone" รวมทุกแมพ (โควตา 3 นับรวมข้ามแท็บ)
  let _offMap = 1;           // map ของแท็บที่กำลังดู
  let _offMapNames = {};     // {mapId: ชื่อ} — ไว้โชว์ breakdown
  const _OFF_MAX = 3;
  const _offKey = (m, z) => `${m | 0}:${z | 0}`;
  // ══════════════ ⚔️ PVP — ดวลผู้เล่น ══════════════
  let _pvpInvSeen = '';      // duel id ของ popup คำท้าที่โชว์แล้ว (กันเด้งซ้ำทุก poll)
  let _pvpLastPh = '';       // phase ล่าสุด — จับ transition count→fight = "FIGHT!"
  function _pvpPost(data, cb) {
    $.post(baseUrl + 'xhrpg_pvp.php', Object.assign({ line_uid: player.line_uid, session_token: sessionToken || '' }, data))
      .done(res => cb && cb(res)).fail(() => cb && cb(null));
  }
  // ── 🏟️ ดันท้าบอส (Boss Arena 1v1) — บัตร G เข้าดัน · ชนะปลด Skip · โควตาฟรี+P ตาม VIP (server เป็นคนคิด) ──
  let _arenaRes = null, _arenaPage = 0; // เก็บ info ล่าสุด + หน้าปัจจุบัน (แบ่งหน้า 15 ตัว)
  const _ARENA_PER_PAGE = 15;
  function _arenaPost(data, cb) {
    $.post(baseUrl + 'xhrpg_arena.php', Object.assign({ line_uid: player.line_uid, session_token: sessionToken || '' }, data))
      .done(res => cb && cb(res)).fail(() => cb && cb(null));
  }
  function openArenaPanel() {
    if (!player || !player.line_uid) return;
    const old = document.getElementById('arena-panel'); if (old) old.remove();
    const el = document.createElement('div');
    el.id = 'arena-panel';
    el.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,.6);z-index:9998;display:flex;align-items:center;justify-content:center;padding:16px';
    el.innerHTML = `<div style="background:#0f172a;border:1px solid #b45309;border-radius:16px;max-width:360px;width:100%;max-height:88vh;display:flex;flex-direction:column;overflow:hidden;color:#e2e8f0;box-shadow:0 12px 40px rgba(2,8,23,.5)">
      <div style="background:#b45309;padding:12px 16px;text-align:center;position:relative;flex:none">
        <button onclick="document.getElementById('arena-panel').remove()" aria-label="ปิด" style="position:absolute;top:9px;right:11px;width:28px;height:28px;border-radius:8px;border:none;background:rgba(0,0,0,.28);color:#fff;font-size:15px;line-height:1;cursor:pointer">✕</button>
        <div style="font-size:24px;line-height:1">🏟️</div>
        <div style="font-size:15px;font-weight:700;margin-top:2px">${T('ดันท้าบอส — 1 ต่อ 1')}</div>
      </div>
      <div style="padding:12px 13px;overflow:auto;flex:1;min-height:0" id="arena-body">${T('⏳ กำลังโหลด...')}</div>
    </div>`;
    el.addEventListener('click', e => { if (e.target === el) el.remove(); });
    document.body.appendChild(el);
    _arenaFetch();
  }
  function _arenaFetch() {
    _arenaPost({ action: 'info' }, res => {
      if (!document.getElementById('arena-body')) return;
      if (!res || !res.ok) { document.getElementById('arena-body').innerHTML = (res && res.error) ? '❌ ' + res.error : T('❌ โหลดไม่สำเร็จ'); return; }
      _arenaRes = res; // คงหน้าเดิม (_arenaPage) — ชนะ/แพ้กลับมาไม่เด้งหน้า 1 · clamp ใน _arenaRenderList กันเกินช่วง
      _arenaRenderList();
    });
  }
  function _arenaSetPage(n) { _arenaPage = n; _arenaRenderList(); const bd = document.getElementById('arena-body'); if (bd) bd.scrollTop = 0; }
  function _arenaRenderList() {
    const bd = document.getElementById('arena-body'), res = _arenaRes; if (!bd || !res) return;
    const D = 30;
    const freeLeft = Math.max(0, res.free_max - Math.min(res.used, res.free_max));
    const paidLeft = Math.max(0, res.paid_max - res.paid);
    const head = `<div style="display:flex;justify-content:space-between;background:rgba(180,83,9,.15);border:1px solid #b45309;border-radius:9px;padding:6px 10px;margin-bottom:8px;font-size:11px">
      <span>${T('ฟรีวันนี้เหลือ')} <b style="color:#fbbf24">${freeLeft}/${res.free_max}</b></span>
      <span>${T('ซื้อด้วย P ได้อีก')} <b style="color:#fbbf24">${paidLeft}/${res.paid_max}</b></span>
    </div>` + (res.in_arena ? `<div style="background:#7f1d1d;border-radius:9px;padding:7px;margin-bottom:8px;text-align:center;font-size:11.5px;font-weight:700">${T('⚔️ กำลังสู้บอสอยู่ — กลับไปดูในแมพ!')}</div>` : '');
    const _art = (lv, emoji, gray) => { const sb = _monSpriteBg(lv || 1); const f = gray ? 'filter:grayscale(1);opacity:.55' : '';
      return sb ? `<div style="width:${D}px;height:${D}px;background:url('${sb.url}') 0 0/${sb.cols * D}px ${sb.rows * D}px no-repeat;image-rendering:pixelated;${f}"></div>` : `<div style="font-size:20px;line-height:1;${f}">${emoji}</div>`; };
    // 💰 ย่อเลขเฉพาะตั้งแต่ 1 ล้าน — เจ้าของขอเห็น "64,000" เต็มๆ
    //    ⚠️ ห้ามใช้ _gdShortG ที่มีอยู่แล้ว เพราะตัวนั้นย่อตั้งแต่หลักพัน (64,000 → "64k") ผิดโจทย์
    const _arG = (n) => (n >= 1e6) ? (n / 1e6).toFixed(n % 1e6 ? 2 : 0) + 'M' : n.toLocaleString();
    // แถวบอส 2 บรรทัด: บรรทัด 1 = สไปรต์+Lv+ชื่อเต็ม (ไม่บีบ) · บรรทัด 2 = ปุ่มราคา + 📜
    const bossRow = b => {
      const safeName = (b.name || '').replace(/['"<>]/g, '');
      const act = b.won ? 'skip' : 'enter', ico = b.won ? '⏩' : '⚔️', dis = res.in_arena ? 'disabled' : '', op = res.in_arena ? .45 : 1;
      // ⏩ ปุ่มคูณ: N = min(5, โควตาที่เหลือของสกุลนั้น) — เจ้าของเคาะ "ลดเลขอัตโนมัติ" 2026-08-13
      //    N < 2 = ไม่ต้องมีปุ่ม (×1 ซ้ำกับปุ่มเดี่ยวอยู่แล้ว) ⇒ **ปุ่มที่เห็น = ปุ่มที่กดได้จริงเสมอ**
      //    ไม่มีกรณีกด ×5 แล้วได้ 1 อีกต่อไป (โควตา G มีแค่ 1-6/วัน ปุ่ม ×5 ตายตัวจึงโกหกเกือบทุกคน)
      const gLeft = Math.max(0, (res.free_max | 0) - (res.used | 0));
      const pLeft = Math.max(0, (res.paid_max | 0) - (res.paid | 0));
      const gN = Math.min(5, gLeft), pN = Math.min(5, pLeft);
      // ทุกปุ่มหน้าตาเดียวกัน: บรรทัด 1 = ราคารวมที่จ่ายจริง · บรรทัด 2 = จำนวนครั้ง ⇒ สูงเท่ากันหมด ไม่เอียง
      const btn = (pay, n, price, bg) =>
        `<button onclick="xhrpg._arenaGo(${b.mid},'${b.won ? 'skip' : act}','${pay}','${safeName}',${b.lv},${b.ticket},${b.pcost}${n > 1 ? ',' + n : ''})" ${dis}
          style="flex:1;min-width:0;background:${bg};color:#fff;border:none;border-radius:7px;padding:5px 2px;font-size:10.5px;font-weight:700;letter-spacing:-.2px;cursor:pointer;opacity:${op};line-height:1.25"
          >${price}<br><span style="font-size:9px;opacity:.8;font-weight:600">×${n}</span></button>`;
      const buttons = [
        btn('g', 1, _arG(b.ticket) + ' G', '#b45309'),
        (b.won && gN >= 2) ? btn('g', gN, _arG(b.ticket * gN) + ' G', '#92400e') : '',
        btn('p', 1, b.pcost + ' P', '#7c3aed'),
        (b.won && pN >= 2) ? btn('p', pN, (b.pcost * pN) + ' P', '#6d28d9') : '',
      ].join('');
      return `<div style="position:relative;border:1px solid ${b.won ? '#0d9488' : '#334155'};background:rgba(30,41,59,.8);border-radius:10px;padding:7px 9px;margin-bottom:7px">
        ${b.won ? '<span style="position:absolute;top:6px;right:8px;font-size:13px">✅</span>' : ''}
        <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">
          <div style="width:${D}px;flex:0 0 auto;display:flex;justify-content:center">${_art(b.lv, b.emoji, false)}</div>
          <div style="flex:1;min-width:0;font-size:12.5px;font-weight:700;color:#f1f5f9;padding-right:18px"><span style="font-size:10px;font-weight:600;color:#fbbf24">Lv.${b.lv}</span> ${T(b.name)}</div>
        </div>
        <div style="display:flex;gap:5px;align-items:stretch">
          <span style="flex:0 0 auto;display:flex;align-items:center;font-size:13px;opacity:.9">${ico}</span>
          ${buttons}
          <button onclick="xhrpg._arenaHist(${b.mid},'${safeName}')" title="ประวัติรางวัล" style="flex:0 0 auto;background:rgba(51,65,85,.9);color:#cbd5e1;border:1px solid #334155;border-radius:7px;padding:5px 8px;font-size:13px;cursor:pointer">📜</button>
        </div>
      </div>`;
    };
    // 🔒 บอสตัวถัดไปที่ยังไม่ปลด — โชว์บนสุดแค่ 1 ตัว (ใกล้ปลดสุด) เฉพาะหน้าแรก
    const lockRow = (_arenaPage === 0) ? (res.locked || []).slice().sort((a, b) => a.lv - b.lv).slice(0, 1).map(b =>
      `<div style="display:flex;align-items:center;gap:8px;border:1px dashed #475569;background:rgba(15,23,42,.6);border-radius:10px;padding:7px 9px;margin-bottom:7px;opacity:.8">
        <div style="width:${D}px;flex:0 0 auto;display:flex;justify-content:center">${_art(b.lv, b.emoji, true)}</div>
        <div style="flex:1;min-width:0;font-size:12.5px;font-weight:700;color:#64748b;overflow:hidden;text-overflow:ellipsis;white-space:nowrap"><span style="font-size:10px;font-weight:600;color:#64748b">Lv.${b.lv}</span> ${T(b.name)}</div>
        <span style="flex:0 0 auto;font-size:10px;font-weight:700;color:#f59e0b;background:rgba(180,83,9,.2);border:1px solid #b45309;border-radius:6px;padding:3px 8px">🔒 ${(b.unlock_rag | 0) > 0 ? T('ปลดที่ 🌟{a}', {a: b.unlock_rag}) : T('ปลดที่ Lv.{a}', {a: b.unlock_lv})}</span>
      </div>`).join('') : '';
    // แบ่งหน้า 15 ตัว (การเรียงจาก server คงเดิม — Lv มาก→น้อย)
    const all = res.bosses || [];
    const pages = Math.max(1, Math.ceil(all.length / _ARENA_PER_PAGE));
    if (_arenaPage >= pages) _arenaPage = pages - 1;
    const slice = all.slice(_arenaPage * _ARENA_PER_PAGE, (_arenaPage + 1) * _ARENA_PER_PAGE);
    const rows = slice.map(bossRow).join('') || `<div style="text-align:center;color:#94a3b8;font-size:12px;padding:16px">${T('ยังไม่มีบอสให้ท้า (ต้อง Lv สูงกว่าบอสอย่างน้อย 10)')}</div>`;
    const pager = pages > 1 ? `<div style="display:flex;align-items:center;justify-content:center;gap:10px;margin-top:4px">
      <button onclick="xhrpg._arenaSetPage(${_arenaPage - 1})" ${_arenaPage === 0 ? 'disabled' : ''} style="background:#334155;color:#fff;border:none;border-radius:7px;padding:5px 12px;font-size:13px;font-weight:700;cursor:pointer;opacity:${_arenaPage === 0 ? .4 : 1}">‹</button>
      <span style="font-size:11.5px;color:#cbd5e1">${T('หน้า {a}/{b}', {a: _arenaPage + 1, b: pages})}</span>
      <button onclick="xhrpg._arenaSetPage(${_arenaPage + 1})" ${_arenaPage >= pages - 1 ? 'disabled' : ''} style="background:#334155;color:#fff;border:none;border-radius:7px;padding:5px 12px;font-size:13px;font-weight:700;cursor:pointer;opacity:${_arenaPage >= pages - 1 ? .4 : 1}">›</button>
    </div>` : '';
    bd.innerHTML = head + lockRow + rows + pager;
  }
  const _arEsc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  // 🎨 สีชิปรางวัลตามชนิดของ (ดูจาก icon นำหน้า) — พื้นอ่อน/ตัวเข้มโทนเดียวกัน อ่านง่ายกว่าม่วงล้วน
  function _arChipStyle(d) {
    const c = String(d || '').charAt(0) === '🎁' || d.startsWith('🎁') ? ['#faf5ff', '#7c3aed'] // กล่องการ์ด
      : d.startsWith('🧰') || d.startsWith('🪺') || d.startsWith('🥚') ? ['#f0fdf4', '#15803d'] // กล่องไข่/ไข่
      : d.startsWith('💎') ? ['#eff6ff', '#1d4ed8'] : d.startsWith('🔴') ? ['#fef2f2', '#b91c1c'] // เพชร
      : d.startsWith('📦') || d.startsWith('🔧') ? ['#fffbeb', '#b45309'] // กล่องโมดูล/โมดูล/ชิ้นส่วนอาวุธ
      : d.startsWith('🎴') ? ['#fdf4ff', '#a21caf'] : ['#f8fafc', '#475569']; // การ์ด / ของวิเศษอื่น
    return `background:${c[0]};color:${c[1]};border:1px solid ${c[1]}22`;
  }
  // 🎁 popup รางวัล (ตอนชนะ/skip — server ยิง event arena_reward) — ชิปแปลผ่าน _mvpDropT เหมือนแท็บ MVP
  function _arenaRewardPopup(name, drops, runs) {
    const old = document.getElementById('arena-reward'); if (old) old.remove();
    const chips = (drops && drops.length)
      ? drops.map(d => `<span style="${_arChipStyle(String(d || ''))};border-radius:8px;padding:4px 10px;font-size:11px;font-weight:600;white-space:nowrap;max-width:100%;overflow:hidden;text-overflow:ellipsis">${_arEsc(_mvpDropT(d))}</span>`).join('')
      : `<span style="color:#94a3b8;font-size:11px">${T('(ไม่มีของดรอปรอบนี้ — ได้ EXP/G)')}</span>`;
    const el = document.createElement('div');
    el.id = 'arena-reward';
    el.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,.65);z-index:10001;display:flex;align-items:center;justify-content:center;padding:20px';
    el.innerHTML = `<div style="background:#fff;border-radius:18px;max-width:330px;width:100%;overflow:hidden;text-align:center;box-shadow:0 20px 50px rgba(0,0,0,.45)">
      <div style="background:#b45309;padding:16px 16px 12px;color:#fff;position:relative">
        <div style="position:absolute;top:8px;left:14px;font-size:15px;opacity:.55">🏟️</div><div style="position:absolute;top:8px;right:14px;font-size:15px;opacity:.55">🏆</div>
        <div style="font-size:38px;line-height:1;filter:drop-shadow(0 3px 6px rgba(0,0,0,.35))">🎁</div>
        <div style="font-size:14.5px;font-weight:800;margin-top:6px">${T('รางวัลจากบอส {n}', {n: T(name || '')})}${(runs || 1) > 1 ? ` <span style="background:rgba(255,255,255,.25);border-radius:6px;padding:0 6px">×${runs}</span>` : ''}</div>
        <div style="font-size:10px;color:#fde68a;margin-top:2px">${T('🏆 ชนะแล้ว — Skip บอสตัวนี้ได้ตลอด')}</div>
      </div>
      <div style="padding:12px 14px 14px">
        <div style="display:flex;flex-wrap:wrap;gap:5px;justify-content:center;max-height:44vh;overflow-y:auto">${chips}</div>
        <button onclick="document.getElementById('arena-reward').remove();xhrpg.openArenaPanel()" style="width:100%;margin-top:12px;background:#b45309;color:#fff;border:none;border-radius:10px;padding:10px;font-size:13px;font-weight:700;cursor:pointer;box-shadow:0 3px 0 #7c3a09">${T('เยี่ยม! ไปตีต่อ')}</button>
      </div>
    </div>`;
    el.addEventListener('click', e => { if (e.target === el) el.remove(); });
    document.body.appendChild(el);
  }
  // 📜 ประวัติรางวัลต่อบอส (15 รายการล่าสุด · เก็บ 14 วัน)
  function _arenaHist(mid, name) {
    _arenaPost({ action: 'hist', mid: mid }, res => {
      const old = document.getElementById('arena-hist'); if (old) old.remove();
      const ago = t => { const s = Math.max(0, Date.now() / 1000 - t); return s < 3600 ? T('{a} นาทีก่อน', {a: Math.max(1, Math.floor(s / 60))}) : s < 86400 ? T('{a} ชม.ก่อน', {a: Math.floor(s / 3600)}) : T('{a} วันก่อน', {a: Math.floor(s / 86400)}); };
      const rows = (res && res.hist && res.hist.length)
        ? res.hist.map(r => `<div style="border:1px solid #e2e8f0;border-radius:9px;padding:7px 9px;margin-bottom:6px">
            <div style="font-size:10px;color:#64748b;margin-bottom:4px">🏆 ${ago(r.t)}</div>
            <div style="display:flex;flex-wrap:wrap;gap:4px">${(r.d && r.d.length) ? r.d.map(d => `<span style="background:#f3e8ff;color:#7c3aed;border-radius:6px;padding:2px 8px;font-size:10px;font-weight:600;white-space:nowrap">${_arEsc(_mvpDropT(d))}</span>`).join('') : `<span style="color:#94a3b8;font-size:10px">${T('(ไม่มีของดรอปรอบนี้ — ได้ EXP/G)')}</span>`}</div>
          </div>`).join('')
        : `<div style="text-align:center;color:#94a3b8;font-size:12px;padding:14px">${T('ยังไม่มีประวัติ — ชนะบอสตัวนี้ครั้งแรกกันเลย!')}</div>`;
      const el = document.createElement('div');
      el.id = 'arena-hist';
      el.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,.65);z-index:10001;display:flex;align-items:center;justify-content:center;padding:18px';
      el.innerHTML = `<div style="background:#fff;border-radius:16px;max-width:330px;width:100%;max-height:75vh;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 20px 50px rgba(0,0,0,.4)">
        <div style="padding:12px 14px 8px;text-align:center;flex:none">
          <div style="font-size:13.5px;font-weight:800;color:#1e293b">📜 ${T('ประวัติรางวัล — {n}', {n: T(name || '')})}</div>
        </div>
        <div style="padding:0 12px;overflow:auto;flex:1;min-height:0">${rows}</div>
        <div style="padding:10px 12px;flex:none"><button onclick="document.getElementById('arena-hist').remove()" style="width:100%;background:#334155;color:#fff;border:none;border-radius:9px;padding:8px;font-size:12.5px;font-weight:700;cursor:pointer">${T('ปิดหน้าต่าง')}</button></div>
      </div>`;
      el.addEventListener('click', e => { if (e.target === el) el.remove(); });
      document.body.appendChild(el);
    });
  }
  // ❌ ป้ายเตือนแดงกลางจอ (เข้าดันไม่ได้/G-P ไม่พอ/โควตาเต็ม) — เดิมมีแค่บรรทัด log จางๆ คนไม่เห็นว่าทำไมเงียบ
  function _arenaToast(msg) {
    let t = document.getElementById('arena-toast');
    if (t) t.remove();
    t = document.createElement('div');
    t.id = 'arena-toast';
    t.textContent = msg;
    // ⚠️ z-index ต้องสูงกว่า overlay ทุกตัว (การ์ด EQ2 = 10008 · popup อื่นถึง 10050) — เดิม 10005 ทำให้ toast ไปอยู่
    //    "หลัง" ฉากดำของการ์ด = กดปุ่มแล้วเหมือนไม่มีอะไรเกิดขึ้น (เจอจริงกับปุ่มสุ่ม option EQC 2026-07-29)
    _floatMount(t, 'top:16%;left:50%;transform:translateX(-50%);z-index:10060;background:rgba(153,27,27,.95);color:#fff;border:1px solid #f87171;border-radius:12px;padding:10px 18px;font-size:13px;font-weight:700;max-width:88%;box-sizing:border-box;text-align:center;box-shadow:0 8px 24px rgba(0,0,0,.45);transition:opacity .4s;pointer-events:none'); // 📌 เกาะกรอบเกม
    setTimeout(() => { t.style.opacity = '0'; setTimeout(() => t.remove(), 450); }, 3000);
  }
  // 💀 ป้ายแจ้ง "ถูกสังหาร" ตอนฟื้นกลับมา (เจ้าของสั่ง 2026-08-15)
  //    ⚠️ ตั้งใจให้เป็น **การแสดงผลล้วน** — ไม่หน่วงเกม ไม่แตะ server ไม่มี state ค้าง
  //       ⇒ ไม่มีทางบล็อกการเล่นถาวร (คำถามเจ้าของ) · เกมเดินต่อข้างใต้ป้ายตามปกติ
  //    ปิดเองใน 2.5 วิ หรือกด "ลุยต่อ" · กดที่พื้นหลังก็ปิด
  let _deadCardT = 0;
  function _deadCard() {
    const old = document.getElementById('dead-card');
    if (old) old.remove();
    clearTimeout(_deadCardT);
    const box = document.createElement('div');
    box.id = 'dead-card';
    const close = () => { clearTimeout(_deadCardT); box.style.opacity = '0'; setTimeout(() => box.remove(), 300); };
    box.innerHTML =
      `<div style="font-size:40px;line-height:1">💀</div>
       <div style="font-size:17px;font-weight:800;margin-top:4px">${_gdEsc(T('ถูกสังหาร'))}</div>
       <div style="font-size:12px;opacity:.9;margin-top:6px;line-height:1.5">${_gdEsc(T('กลับมาที่จุดเริ่มต้นแล้ว — เกราะและพลังงานเต็ม'))}</div>
       <button id="dead-go" style="margin-top:12px;padding:7px 26px;border:1px solid #f87171;border-radius:10px;background:#b91c1c;color:#fff;font-size:13px;font-weight:800;cursor:pointer">${_gdEsc(T('ลุยต่อ'))}</button>`;
    // 📍 top:8px กลางจอบน — ตำแหน่งเดียวกับแบนเนอร์แจ้งศึกกิล (เจ้าของสั่ง 2026-08-16 · เดิมลอยกลางจอ บังตัวละคร)
    _floatMount(box, 'top:8px;left:50%;transform:translateX(-50%);z-index:10060;background:rgba(15,23,42,.94);color:#fff;border:1px solid #f87171;border-radius:16px;padding:14px 24px;max-width:86%;box-sizing:border-box;text-align:center;box-shadow:0 12px 32px rgba(0,0,0,.55);transition:opacity .3s');
    box.querySelector('#dead-go')?.addEventListener('click', close);
    box.addEventListener('click', e => { if (e.target === box) close(); });
    _deadCardT = setTimeout(close, 2500); // ปิดเองใน 2.5 วิ (เดิม 3 วิ — เจ้าของสั่งลด 0.5 วิ 2026-08-16)
  }
  let _arenaBusy = 0; // 🖐️ กันกดรัว — ปุ่มไม่ได้ทำงานทันที (server วางคีย์ให้ poll ทำต่อ) คนเลยกดซ้ำเพราะนึกว่าไม่ติด
  function _arenaGo(mid, mode, pay, name, lv, g, pc, count) {
    if (Date.now() - _arenaBusy < 2500) return; // ยังรอคำตอบ/รอ poll กินคำสั่งอยู่ — กดซ้ำไม่มีผล (server กัน NX อีกชั้น)
    _arenaBusy = Date.now();
    // ⏩ ปุ่มคูณใช้ได้ทั้ง G และ P แล้ว และเป็นเลขอะไรก็ได้ 1-5 (client ลดเลขตามโควตาที่เหลือ)
    //    🔒 clamp ที่นี่เป็นแค่ความสุภาพ — server clamp จริงอีก 2 ชั้น (endpoint + tick)
    count = (mode === 'skip') ? Math.max(1, Math.min(5, count | 0)) : 1;
    // ⚡ กดแล้ว process ทันที ไม่มี popup ยืนยัน (เจ้าของสั่ง 2026-07-18 — เดิมช้า) · endpoint หัก G/P + ปัดกรณีไม่พอ/โควตาเต็มเองอยู่แล้ว
    _arenaPost({ action: mode, mid: mid, pay: pay, count: count }, res => {
      if (!res) { addLog([{ type: 'default', msg: T('❌ เชื่อมต่อไม่ได้') }]); return; }
      // ⚠️ บาง error ส่ง "รหัส" มาใน error แล้วส่งคำแปลมาใน msg (เช่น in_home / in_colosseum)
      //    เดิมโชว์ res.error ตรงๆ ⇒ ผู้เล่นเห็นคำว่า "in_home" ทั้งที่คำแปลถูกส่งมาแล้ว ⇒ ใช้ msg ก่อนเสมอ
      const _erT = res.error ? (res.msg || res.error) : '';
      addLog([{ type: 'default', msg: res.error ? '❌ ' + _erT : res.msg }]);
      if (res.error) { _arenaBusy = 0; _arenaToast('❌ ' + _erT); } // เด้งป้ายแดงให้เห็นชัด (endpoint ปัด: G/P ไม่พอ · โควตาเต็ม · ยังไม่ปลด Skip) · ปลดล็อกให้กดแก้ได้ทันที
      if (!res.error) { const el2 = document.getElementById('arena-panel'); if (el2) el2.remove(); }
    });
  }
  //    🏴‍☠️ แท็บเริ่มต้น = ปล้นบ้าน (เจ้าของสั่ง 2026-08-16 · เดิมเป็นท้าดวล)
  function openPvpPanel(tab) { if (!player || !player.line_uid) return; _pvpPage = 0; _pvpRenderShell(tab || 'raid'); } // เปิดแผงใหม่ = กลับหน้า 1 เสมอ
  function _pvpClose() { const el = document.getElementById('pvp-panel'); if (el) el.remove(); }
  function _pvpTab(tab) { _pvpRenderShell(tab); }
